async def _exec_manage_bastion(args: dict) -> dict:
    """Bastion lifecycle: enroll/revoke/update/list/latest. Calls the nac_commit SERVICE directly
    (no HTTP shim) — entity-scoped throughout."""
    try:
        from server import brain_service
        from server.network import nac_commit
        a = args or {}
        op = (a.get("op") or "list").strip().lower()
        token_id = int(a["token_id"]) if a.get("token_id") is not None else None
        pool = brain_service.get_pool()
        eid = brain_service._entity_id
        res = await nac_commit.manage_bastion(
            pool, eid, op, name=(a.get("name") or "bastion"),
            token_id=token_id, version=(a.get("version") or ""))
        if op in ("list", "status"):
            return _bastion_list_view(res, token_id)
        return {"status": "ok", "result": res}
    except Exception as e:
        return _refused_if_caller(e, f"manage_bastion failed: {getattr(e, 'detail', None) or e}")


def _bastion_list_view(res: dict, token_id) -> dict:
    """manage_bastion op='list' for the Host: nac_status's roster
    (_nac_bastion_row), or with token_id that one bastion's whole record.

    The service (nac_commit.manage_bastion -> bastions_list) returns every
    machine's whole check-in record, which the Network app's /bastions routes
    keep reading unchanged; up to 57,000 characters measured,
    re-sent on every later call of its turn. token_id is the id the roster
    carries, and a typed turn already checks the server behind it
    (turn_types.TYPE_SERVER_TOKEN_ARGS)."""
    machines = (res or {}).get("bastions") if isinstance(res, dict) else None
    if not isinstance(machines, list):
        return {"status": "ok", "result": res}
    if token_id is not None:
        b = next((m for m in machines if m.get("id") == token_id), None)
        if b is None:
            return _refused(f"no bastion with token_id {token_id} on this host. Its bastions: "
                            + (", ".join(f"{m.get('id')} ({m.get('hostname') or m.get('name')})"
                                         for m in machines) or "none"))
        return {"status": "ok", "result": {"bastion": b}}
    return {"status": "ok", "result": {
        "bastions": [_nac_bastion_row(b) for b in machines],
        "online": sum(1 for b in machines if b.get("online")),
        "full_record": ("manage_bastion(op='list', token_id=<id>) or "
                        "nac_status(server='<hostname>') returns one bastion's whole record"),
    }}


async def _exec_decision_resolve(args: dict) -> dict:
    """Resolve one of the host's OWN pending decisions. The resolve service scopes to this pod's
    entity (WHERE entity_id = _self_entity_id), so a host can only resolve its own queue; the
    platform-change-approval path fires only for cseries_proposal rows, which live solely in the
    operator Host's queue — that is the public-own vs operator split, enforced by scoping.

    Calls the service directly (no route shim): same code path as the FastAPI
    /api/decisions/{id}/resolve route."""
    try:
        from server import brain_service, decisions_service
        from server.routes.decisions import _self_entity_id
        a = args or {}
        did = a.get("decision_id")
        if did is None:
            return _refused("decision_id required")
        chosen = a.get("chosen_key")
        if not chosen:
            return _refused("chosen_key required")
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "brain pool not ready"}
        eid = _self_entity_id()
        if eid is None:
            return {"status": "error", "result": "this container has no host id bound"}
        try:
            res = await decisions_service.resolve_decision_service(
                pool, eid, int(did), str(chosen), a.get("chosen_rationale"),
            )
        except decisions_service.DecisionResolveError as e:
            return _refused_if_caller(e, f"decision_resolve failed: {e.detail}")
        return {"status": "ok", "result": res}
    except Exception as e:
        return _refused_if_caller(e, f"decision_resolve failed: {getattr(e, 'detail', None) or e}")


async def _exec_install_app(args):
    a = args or {}
    app_id = (a.get("app_id") or "").strip()
    if not app_id:
        return _refused("app_id is required")
    version = (a.get("version") or "").strip() or None
    try:
        from server import brain_service
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "pool unavailable"}
        from server.applications import installer
        from server.applications.platform_tools import (
            allowed_for_entity, current_entity_id,
        )
        from server.routes.applications import _fetch_bundle_from_store, _StoreError
        eid = current_entity_id()
        # Platform-tool gate (defense in depth — the store gate also enforces).
        if not allowed_for_entity(app_id, eid):
            return _refused(f"{app_id!r} is a platform tool; this host is not in its install allow-list")
        try:
            data = await _fetch_bundle_from_store(app_id, version)
        except _StoreError as e:
            return _refused_if_caller(e, f"store fetch failed: {e}")
        try:
            app = await installer.install_bundle(pool, data, source="manual")
        except installer.AppRuntimeOverPlan as e:
            # The host is the one telling the user, so it needs the sentence,
            # not a traceback: what the app needs, what is left, which tier
            # carries it. The install already rolled itself back.
            return _refused(str(e), over_plan={
                "app_id": e.app_id, "needs_mi": e.needs_mi,
                "headroom_mi": e.headroom_mi, "upgrade_to": e.upgrade_to})
        # Post-install allow-list re-check + rollback (mirrors the route).
        if not allowed_for_entity(app.id, eid):
            try:
                await installer.uninstall_app(pool, app.id, purge=True)
            except Exception:
                pass
            return _refused(f"{app.id!r} is a platform tool; this host is not in its install allow-list")
        return {"status": "ok", "result": {
            "app_id": app.id, "name": app.name, "version": app.version,
            "provenance": app.provenance, "status": app.status, "installed": True,
        }}
    except Exception as e:
        return _refused_if_caller(e, f"install_app failed: {getattr(e, 'detail', None) or e}")


async def _exec_uninstall_app(args):
    a = args or {}
    app_id = (a.get("app_id") or "").strip()
    if not app_id:
        return _refused("app_id is required")
    purge = bool(a.get("purge", False))
    try:
        from server import brain_service
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "pool unavailable"}
        from server.applications import installer
        from server.applications.supervisor import get_supervisor
        # Stop any running sidecar before tearing the bundle out from under it.
        sup = get_supervisor()
        if sup is not None:
            running = sup.get(app_id)
            if running is not None:
                await sup._terminate(running)
                async with sup._lock:
                    sup._by_app.pop(app_id, None)
                    sup._refs.pop(app_id, None)
        res = await installer.uninstall_app(pool, app_id, purge=purge)
        return {"status": "ok", "result": res}
    except Exception as e:
        return _refused_if_caller(e, f"uninstall_app failed: {getattr(e, 'detail', None) or e}")


async def _exec_refresh_app_store(args):
    try:
        from server import brain_service
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "pool unavailable"}
        from server.applications.public_store import store_client
        bc = store_client()
        if not bc._connected:
            return {"status": "error", "result": "no App Store is reachable"}
        from server.applications.default_install import _sync_store_upgrades
        res = await _sync_store_upgrades(bc, pool)
        return {"status": "ok", "result": res}
    except Exception as e:
        return _refused_if_caller(e, f"refresh_app_store failed: {getattr(e, 'detail', None) or e}")


async def _exec_list_app_catalog(args):
    try:
        from server import brain_service
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "pool unavailable"}
        from server.applications.public_store import store_client
        bc = store_client()
        if not bc._connected:
            return {"status": "error", "result": "no App Store is reachable"}
        envelope = await bc.request_full("appstore.list", {})
        if not envelope.get("ok"):
            return {"status": "error", "result": envelope.get("error") or "store error"}
        catalog = (envelope.get("data") or {}).get("apps", [])
        from server.applications import registry
        from server.applications.platform_tools import (
            allowed_for_entity, current_entity_id,
        )
        installed_by_id = {x.id: x for x in await registry.list_active(pool)}
        eid = current_entity_id()
        out = []
        for entry in catalog:
            aid = entry.get("app_id")
            if not aid or not allowed_for_entity(aid, eid):
                continue
            local = installed_by_id.get(aid)
            installed_ver = local.version if local else None
            latest = entry.get("latest_version")
            if local:
                if latest and installed_ver == latest:
                    status_str = "up_to_date"
                elif latest and installed_ver != latest:
                    status_str = "update_available"
                else:
                    status_str = "installed"
            else:
                status_str = "not_installed"
            out.append({
                "app_id": aid,
                "name": entry.get("name") or aid,
                "latest_version": latest,
                "installed_version": installed_ver,
                "install_status": status_str,
                "price_micros": entry.get("price_micros"),
                "provenance": entry.get("provenance") or entry.get("tier"),
            })
        return {"status": "ok", "result": {"apps": out}}
    except Exception as e:
        return _refused_if_caller(e, f"list_app_catalog failed: {getattr(e, 'detail', None) or e}")


async def _exec_purchase_app(args):
    a = args or {}
    app_id = (a.get("app_id") or "").strip()
    if not app_id:
        return _refused("app_id is required")
    try:
        from server.applications.platform_tools import (
            allowed_for_entity, current_entity_id,
        )
        eid = current_entity_id()
        if not allowed_for_entity(app_id, eid):
            return _refused(f"{app_id!r} is a platform tool; this host is not in its install allow-list")
        from server.applications.public_store import store_client
        bc = store_client()
        if not bc._connected:
            return {"status": "error", "result": "no App Store is reachable"}
        # Stripe Connect is the single purchase path for paid apps, so an agent can install FREE apps but cannot spend
        # money on the host's behalf. This op records free-path entitlements;
        # a paid app comes back as checkout_required and the human buys it in
        # the Store app.
        envelope = await bc.request_full("appstore.purchase", {"app_id": app_id})
        if not envelope.get("ok"):
            return {"status": "error", "result": envelope.get("error") or "purchase failed"}
        data = envelope.get("data") or {}
        if data.get("checkout_required"):
            # Not a failure the agent can retry its way out of — say plainly
            # that a person has to make this purchase, and how.
            price = data.get("price_micros")
            price_str = f"${int(price) / 1_000_000:.2f}" if price else "a fee"
            return _refused({
                "checkout_required": True,
                "message": (
                    f"{app_id!r} is a paid app ({price_str}). Paid apps are "
                    f"bought by you, not by me: open the Store app and use "
                    f"Buy, which goes through Stripe. The seller sets their "
                    f"own refund policy — it's shown on the listing before "
                    f"you pay."),
                **data})
        return {"status": "ok", "result": data}
    except Exception as e:
        return _refused_if_caller(e, f"purchase_app failed: {getattr(e, 'detail', None) or e}")


# manage_site / manage_site_domain dispatch over the caller-scoped webapp.* bridge
# ops the Sites app uses. The bridge fixes entity_id from the mTLS handshake, so a
# host can only touch its OWN sites — these are thin surfaced dispatchers.
#
# op='publish': the host publishes a site bundle (a zip) it
# already BUILT into its OWN governed workspace ($CEIGAS_WORKSPACE) — NOT an in-chat
# raw upload. The handler reads the zip through the sandboxed file_access capability
# (path-traversal / size guarded) and forwards {slug, zip_b64} to the SAME
# webapp.publish_bundle bridge op the Sites app's upload uses. The bridge fixes the
# publisher from the mTLS cert, so a host can only publish under its OWN identity.
_MANAGE_SITE_OPS = {
    "list":      ("webapp.sites", ()),
    "analytics": ("webapp.analytics", ()),
    "publish":   ("webapp.publish_bundle", ("slug",)),
    "unpublish": ("webapp.unpublish", ("slug",)),
    "suspend":   ("webapp.suspend", ("slug",)),
    "resume":    ("webapp.resume", ("slug",)),
    "restart":   ("webapp.restart", ("slug",)),
    "expose":    ("webapp.set_exposure", ("slug", "policy")),
}


# A published bundle up to this size rides in-band (zip_b64), exactly as every
# bundle did when the kernel read it whole (it refused past 10 MB), so a
# bridge that predates staged parts still takes it. Past it the bundle is sent
# in parts, read from disk one part at a time, so memory is bounded by a part,
# never by the bundle.
_PUBLISH_IN_BAND_MAX = 10 * 1024 * 1024
# One part, under the bridge's own per-part maximum (the bridge's
# _BUNDLE_PART_MAX, 16 MiB) — and small enough that a part,
# its base64 and the JSON line carrying it stay a few tens of MB.
_PUBLISH_PART_BYTES = 8 * 1024 * 1024


async def _publish_bundle_body(fh, size: int, send) -> dict:
    """What the publish op carries for the open bundle `fh`: {"zip_b64": ...}
    for a bundle that fits in-band, else {"upload_id", "parts", "sha256"}
    after sending each part with `send("bundle.upload_part", ...)`.
    {"error": ...} when the platform refuses a part."""
    import base64 as _b64
    import hashlib as _hl
    import secrets as _sec
    if size <= _PUBLISH_IN_BAND_MAX:
        return {"zip_b64": _b64.b64encode(fh.read()).decode("ascii")}
    upload_id = _sec.token_hex(16)
    digest = _hl.sha256()
    seq = 0
    while True:
        chunk = fh.read(_PUBLISH_PART_BYTES)
        if not chunk:
            break
        digest.update(chunk)
        env = await send("bundle.upload_part", {
            "upload_id": upload_id, "seq": seq,
            "data_b64": _b64.b64encode(chunk).decode("ascii")})
        del chunk
        if not (isinstance(env, dict) and env.get("ok")):
            err = (env or {}).get("error") if isinstance(env, dict) else env
            return {"error": (f"publish failed: part {seq + 1} of the {size}-byte bundle "
                              f"was not taken by the platform: {err}. A bundle over "
                              f"{_PUBLISH_IN_BAND_MAX // (1024 * 1024)} MB is sent in parts, "
                              "which the platform's bridge must accept.")}
        seq += 1
    return {"upload_id": upload_id, "parts": seq, "sha256": digest.hexdigest()}


async def _exec_manage_site(args):
    a = args or {}
    op = (a.get("op") or "").strip()
    if op not in _MANAGE_SITE_OPS:
        return _refused(f"op must be one of {sorted(_MANAGE_SITE_OPS)} (got {op!r})")
    bridge_op, required = _MANAGE_SITE_OPS[op]
    params = {}
    for key in required:
        if key == "policy":
            # policy is a dict, not a plain string — handled in the op=='expose'
            # branch below; do NOT run it through the strip/lower string coercion.
            continue
        val = (a.get(key) or "").strip().lower()
        if not val:
            return _refused(f"{key} is required for op={op!r}")
        params[key] = val
    if op == "expose":
        # Pass the policy dict through INTACT (not lowercased/stringified). Like
        # the HTTP route, this is a dumb forward — the bridge's webapp.set_exposure
        # does the creator-email seed + fail-closed validation from the mTLS
        # entity_id. Validate only that a non-empty 'tier' is present; the
        # controller validates tier membership.
        policy = a.get("policy")
        if not isinstance(policy, dict) or not (
            isinstance(policy.get("tier"), str) and policy.get("tier").strip()
        ):
            return _refused("policy (a dict with a non-empty 'tier') is required for op='expose'")
        params["policy"] = policy
    if op == "analytics" and a.get("hours") is not None:
        try:
            params["hours"] = int(a.get("hours"))
        except (TypeError, ValueError):
            return _refused("hours must be an integer")
    if op == "publish":
        # The bundle is a zip the host built into its governed workspace; read it
        # through the sandboxed file_access capability (NOT an in-chat upload), then
        # forward base64 to webapp.publish_bundle alongside the slug.
        bundle_path = (a.get("bundle_path") or "").strip()
        if not bundle_path:
            return _refused("bundle_path is required for op='publish' "
                            "(a .zip built into the host's workspace)")
        try:
            from server.capabilities import file_access
        except Exception as e:
            return _refused_if_caller(e, f"publish failed: file_access capability unavailable: {e}")
        # Streamed, never through read_file. The bundle is opened ONCE: the licence check reads that
        # open file (its central directory and manifest only), and the same
        # file is what goes out, so the check and the publish see the same
        # bytes. Memory stays bounded whatever the bundle's size:
        #   - up to _PUBLISH_IN_BAND_MAX it rides in-band as zip_b64, as every
        #     bundle did before (a bridge without parts still takes it);
        #   - past that it is sent in parts of _PUBLISH_PART_BYTES with
        #     bundle.upload_part, read from the file one part at a time, and
        #     the publish names the upload (upload_id + parts + sha256) instead
        #     of carrying the bytes (the bridge's op_bundle_upload_part).
        # How big a bundle may be is the platform's call — its zip-bomb guard
        # on what a bundle unpacks to — and its refusal comes back in its words.
        fh, _bundle_size, _open_err = file_access.open_file(bundle_path)
        if fh is None:
            # A path the model named that is not there, not a file or outside
            # the workspace is its outcome (file_access.Refusal); an OSError
            # opening a file that IS there stays the platform's.
            if getattr(_open_err, "input_refused", False):
                return _refused(f"publish failed reading bundle: {_open_err}")
            return {"status": "error",
                    "result": f"publish failed reading bundle: {_open_err}"}
        try:
            if _bundle_size == 0:
                # The bundle the model built and named is empty.
                return _refused("publish failed: empty bundle")
            # The author's licence gates THIS lane too. It publishes BYTES rather
            # than a tree, so neither publish_site_service gate ever saw it — and
            # the manifest survives inside the bundle, so a zip of someone else's
            # installed app would otherwise reach the public web through here.
            # get_pool() is Optional (brain_service.py:149); no pool means the
            # check cannot run, and an unrunnable rights check refuses.
            try:
                from server import brain_service as _brain
                from server.routes.applications import (
                    ShipError as _ShipError,
                    _license_gate_site_zip as _lic_zip,
                )
            except Exception as e:
                return _refused_if_caller(e, f"publish refused: licence check unavailable: {e}")
            _pool = _brain.get_pool()
            if _pool is None:
                return {"status": "error",
                        "result": "publish refused: cannot check the app licence "
                                  "right now (no database) — refused, not guessed"}
            try:
                await _lic_zip(_pool, fh)
            except _ShipError as e:
                return _refused_if_caller(e, e.detail)
            fh.seek(0)
            try:
                from server.main import get_bridge_client
                _bc = get_bridge_client()
            except Exception:
                _bc = None
            if _bc is None or not getattr(_bc, "_connected", False):
                return {"status": "error", "result": "bridge not connected"}
            _staged = await _publish_bundle_body(fh, _bundle_size, _bc.request_full)
        except OSError as e:
            return _refused_if_caller(e, f"publish failed reading bundle: {e}")
        finally:
            fh.close()
        if _staged.get("error"):
            return {"status": "error", "result": _staged["error"]}
        params.update(_staged)
    try:
        from server.main import get_bridge_client
        bc = get_bridge_client()
        if bc is None or not getattr(bc, "_connected", False):
            return {"status": "error", "result": "bridge not connected"}
        envelope = await bc.request_full(bridge_op, params)
        if not envelope.get("ok"):
            return {"status": "error", "result": envelope.get("error") or f"{bridge_op} failed"}
        return {"status": "ok", "result": envelope.get("data") or {}}
    except Exception as e:
        return _refused_if_caller(e, f"manage_site failed: {getattr(e, 'detail', None) or e}")


# Custom-domain ops on a host's own sites — caller-scoped webapp.* bridge ops.
_MANAGE_SITE_DOMAIN_OPS = {
    "list":          ("webapp.domain_list", ()),
    "add":           ("webapp.domain_add", ("slug", "domain")),
    "verify":        ("webapp.domain_verify", ("domain",)),
    "remove":        ("webapp.domain_remove", ("domain",)),
    "records":       ("webapp.dns_records_list", ("domain",)),
    "record_set":    ("webapp.dns_record_set", ("domain", "name", "type")),
    "record_delete": ("webapp.dns_record_delete", ("domain", "name", "type")),
}


async def _exec_manage_site_domain(args):
    a = args or {}
    op = (a.get("op") or "").strip()
    if op not in _MANAGE_SITE_DOMAIN_OPS:
        return _refused(f"op must be one of {sorted(_MANAGE_SITE_DOMAIN_OPS)} (got {op!r})")
    bridge_op, required = _MANAGE_SITE_DOMAIN_OPS[op]
    params = {}
    for key in required:
        raw = a.get(key)
        val = (str(raw) if raw is not None else "").strip()
        if key in ("slug", "domain"):
            val = val.lower()
        elif key == "type":
            val = val.upper()
        if not val:
            return _refused(f"{key} is required for op={op!r}")
        params[key] = val
    if op == "add":
        method = (a.get("method") or "connect").strip().lower()
        if method not in ("connect", "delegate"):
            return _refused("method must be 'connect' or 'delegate'")
        params["method"] = method
    if op == "record_set":
        values = a.get("values") or []
        if not isinstance(values, list) or not [v for v in values if str(v).strip()]:
            return _refused("at least one value is required for op='record_set'")
        params["values"] = values
        try:
            params["ttl"] = int(a.get("ttl") or 3600)
        except (TypeError, ValueError):
            return _refused("ttl must be an integer")
    try:
        from server.main import get_bridge_client
        bc = get_bridge_client()
        if bc is None or not getattr(bc, "_connected", False):
            return {"status": "error", "result": "bridge not connected"}
        envelope = await bc.request_full(bridge_op, params)
        if not envelope.get("ok"):
            return {"status": "error", "result": envelope.get("error") or f"{bridge_op} failed"}
        return {"status": "ok", "result": envelope.get("data") or {}}
    except Exception as e:
        return _refused_if_caller(e, f"manage_site_domain failed: {getattr(e, 'detail', None) or e}")


async def _exec_inbox_read(args):
    a = args or {}
    message_id = (a.get("message_id") or "").strip()
    if not message_id:
        return _refused("message_id (uuid) required")
    try:
        # Reuse the bridge memory handler verbatim — it is the in-pod
        # service the /api/inbox/read route delegates to. It resolves
        # its own pool + entity_id and scopes the read to this host as
        # recipient, returning an {ok, ...message} envelope. Reading a
        # message also marks it read (UPDATE ... SET read_at).
        from server.bridge.memory_handlers import _entity_id, handle_inbox_read
        # A person's chat is the Host's to read only through the reading
        # switch (server/circles_reading.py visible_sql), the same predicate
        # host_message reads by. Without this, an id the model saw while the
        # switch was on (op='thread' returns message ids) stays readable here
        # after the switch is off or the person cleared the chat. Refused as
        # "not found", the same as an id that is not there.
        from server import brain_service as _bs
        from server.circles_reading import visible_sql
        import uuid as _uuid
        _pool = _bs.get_pool()
        try:
            _uuid.UUID(message_id)
            _valid = True
        except ValueError:
            _valid = False      # handle_inbox_read refuses it in its own words
        if _pool is not None and _valid:
            _closed = await _pool.fetchval(
                "SELECT 1 FROM inbox_messages m WHERE m.message_id = $1::uuid "
                f"AND m.to_entity_id = $2 AND NOT {visible_sql('m', '$2')}",
                message_id, int(_entity_id()))
            if _closed:
                return _refused("not found")
        env = await handle_inbox_read({"message_id": message_id})
        if not env.get("ok", False):
            # An id that is not there or is malformed is the model's input,
            # answered exactly as a closed one above, so the two cannot be told
            # apart. A pool or host-id hiccup (retryable) stays the platform's.
            if not env.get("retryable"):
                return _refused(env.get("error") or "not found")
            return {"status": "error", "result": env.get("error") or "inbox_read failed"}
        env.pop("ok", None)
        return {"status": "ok", "result": env}
    except Exception as e:
        return _refused_if_caller(e, f"inbox_read failed: {getattr(e, 'detail', None) or e}")


async def _exec_circles_manage(args: dict) -> dict:
    """Circles (network communications) op-dispatch for the host.

    One tool, several read/write ops over the host's Circles surface —
    the same module-level helpers the /api/circles routes use (NOT the
    route handlers): self-thread + host<->host DM threads are pod-local
    (entity_memory / inbox_messages), group circles fan out to the bridge.

      list_conversations  -> sidebar payload (self pin + entity DM threads + circles)
      read_thread         -> messages for one thread (self | entity | circle)
      list_circles        -> the host's group circles
      create_circle       -> create a new group circle (write)
      send_circle_message -> post a message into a group circle (write)
    """
    a = args or {}
    op = (a.get("op") or "").strip()
    if not op:
        return _refused("op is required (one of: list_conversations, read_thread, list_circles, create_circle, send_circle_message)")
    try:
        from server import brain_service
        from server.routes import circles as cir
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "pool unavailable"}
        eid = cir._entity_id()
        if eid is None:
            return {"status": "error", "result": "host not initialized"}

        if op == "list_conversations":
            self_pane = {
                "id": "self", "kind": "self",
                "display_name": await cir._entity_display_name(),
                "unread_count": 0,
            }
            entity_items = await cir._list_entity_threads(eid)
            circles_data = await cir._bridge_call("circles.list", {"entity_id": eid}) or {}
            circle_items = [
                {
                    "id": c.get("id"),
                    "display_name": c.get("circle_name") or c.get("name") or f"circle {c.get('id')}",
                    "unread_count": 0,
                }
                for c in (circles_data.get("circles") or circles_data.get("items") or [])
            ]
            return {"status": "ok", "result": {
                "self": self_pane, "entities": entity_items, "circles": circle_items,
            }}

        if op == "read_thread":
            kind = (a.get("kind") or "").strip()
            thread_id = a.get("thread_id")
            if kind not in ("self", "entity", "circle"):
                return _refused("kind must be one of: self, entity, circle")
            if kind == "self":
                return {"status": "ok", "result": {
                    "messages": await cir._read_self_thread(),
                    "members": [], "policy": {"private": True},
                }}
            if kind == "entity":
                try:
                    peer_id = int(thread_id)
                except (TypeError, ValueError):
                    return _refused("thread_id (the other host's id) is required for kind 'entity' (a host DM thread)")
                return {"status": "ok", "result": await cir._read_entity_thread(peer_id)}
            # circle
            try:
                circle_id = int(thread_id)
            except (TypeError, ValueError):
                return _refused("thread_id (circle id) is required for a circle thread")
            data = await cir._bridge_call("circles.messages", {"circle_id": circle_id, "limit": 200})
            if not data:
                return {"status": "ok", "result": {"messages": [], "members": [], "policy": {}}}
            self_name = await cir._entity_display_name()
            messages = []
            for m in reversed(data.get("messages") or []):
                sender = m.get("sender_entity_id")
                is_self = sender == eid
                messages.append({
                    "author_name": self_name if is_self else (m.get("sender_name") or f"Host {sender}"),
                    "author_kind": "self" if is_self else "entity",
                    "body": m.get("content") or "",
                    "created_at": m.get("created_at"),
                })
            return {"status": "ok", "result": {
                "messages": messages,
                "members": data.get("members", []),
                "policy": data.get("policy", {}),
            }}

        if op == "list_circles":
            circles_data = await cir._bridge_call("circles.list", {"entity_id": eid}) or {}
            items = [
                {
                    "id": c.get("id"),
                    "display_name": c.get("circle_name") or c.get("name") or f"circle {c.get('id')}",
                }
                for c in (circles_data.get("circles") or circles_data.get("items") or [])
            ]
            return {"status": "ok", "result": {"circles": items, "count": len(items)}}

        if op == "create_circle":
            name = (a.get("name") or "").strip()
            if not name:
                return _refused("name is required to create a circle")
            data = await cir._bridge_call("circles.create", {
                "entity_id": eid,
                "name": name[:120],
                "description": (a.get("description") or "")[:500],
            })
            if not data or not data.get("id"):
                return {"status": "error", "result": "bridge couldn't create the circle (platform bridge unavailable)"}
            return {"status": "ok", "result": {
                "id": data.get("id"),
                "display_name": data.get("circle_name") or name,
            }}

        if op == "send_circle_message":
            text = (a.get("body") or "").strip()
            if not text:
                return _refused("body is required to send a circle message")
            try:
                circle_id = int(a.get("circle_id"))
            except (TypeError, ValueError):
                return _refused("circle_id is required to send a circle message")
            data = await cir._bridge_call("circles.message", {
                "circle_id": circle_id, "content": text,
            })
            if not data:
                return {"status": "error", "result": "bridge couldn't deliver the circle message (platform bridge unavailable)"}
            return {"status": "ok", "result": data}

        return _refused(f"unknown op: {op}")
    except Exception as e:
        return _refused_if_caller(e, f"circles_manage failed: {getattr(e, 'detail', None) or e}")


async def _exec_calendar_read(args):
    """Read one calendar event, or (op='runs') its execution history.

    The runs half is a WIRING fix, not a new capability: calendar_event_runs
    has existed since v072, the offline runner writes a row per fire, and both
    `handle_calendar_runs` and GET /api/calendar/{id}/runs already read it —
    but no host tool ever called them, so the host could not see whether its
    own scheduled work was succeeding. Standing ops are created without asking
    the user, which makes 'can anyone see the outcome' load-bearing rather
    than a convenience.
    """
    a = args or {}
    op = (a.get("op") or "read").strip().lower()
    _OPS = {"read", "runs"}
    if op not in _OPS:
        return _refused(f"op must be one of {sorted(_OPS)} (got {op!r})")
    event_id = (a.get("event_id") or "").strip() if isinstance(a.get("event_id"), str) else a.get("event_id")
    if not event_id:
        return _refused("event_id is required")
    try:
        if op == "runs":
            from server.bridge.memory_handlers import handle_calendar_runs
            env = await handle_calendar_runs({"event_id": event_id})
            if not env.get("ok", False):
                return {"status": "error", "result": env.get("error") or "calendar_read runs failed"}
            return {"status": "ok", "result": env}
        from server.bridge.memory_handlers import handle_calendar_read
        env = await handle_calendar_read({"event_id": event_id})
        if not env.get("ok", False):
            return {"status": "error", "result": env.get("error") or "calendar_read failed"}
        return {"status": "ok", "result": env}
    except Exception as e:
        return _refused_if_caller(e, f"calendar_read failed: {getattr(e, 'detail', None) or e}")


async def _exec_task_template(args: dict, *, turn_type: dict | None = None,
                              session_id: str | None = None,
                              interaction_context: str | None = None,
                              thread_id: str | None = None) -> dict:
    """Manage the host's reusable scheduled-task TEMPLATES (runbooks) — a saved
    name + prompt and/or ordered steps + optional default recurrence that
    schedule_task can stamp out (schedule_task op='create' template_id=<id>).
    Strictly entity-scoped (server.brain_service pool + _entity_id; no raw
    secrets). Ops:
      create -> save a template (name + prompt and/or steps[] + optional recurrence)
      list   -> the host's own templates
      delete -> remove one of the host's own templates by id
    """
    a = args or {}
    op = (a.get("op") or "list").strip()
    _OPS = {"create", "list", "delete"}
    if op not in _OPS:
        return _refused(f"op must be one of {sorted(_OPS)} (got {op!r})")
    try:
        from server import brain_service
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "task_template failed: pool unavailable"}
        eid = brain_service._entity_id

        if op == "create":
            name = (a.get("name") or "").strip()
            if not name:
                return _refused("name is required for op='create'")
            prompt = (a.get("prompt") or "").strip()
            steps = a.get("steps") or []
            if not isinstance(steps, list):
                return _refused("steps must be a list of strings")
            steps = [str(s) for s in steps if str(s).strip()]
            if not prompt and not steps:
                return _refused("provide a prompt and/or at least one step for op='create'")
            recurrence = (a.get("recurrence") or "").strip() or None
            if recurrence:
                from mastercode.brain.entity_clock import _recurrence_seconds
                if _recurrence_seconds(recurrence) is None:
                    return _refused("recurrence must be one of: hourly, daily, weekly, monthly, or every:<seconds>")
            import json as _json
            # A template written by a TYPED turn carries that type into every
            # task later stamped from it (v185). A closed turn writes
            # none.
            _tpl_type = None
            if turn_type is not None:
                if turn_type.get("status") != "active" or not turn_type.get("id"):
                    return _refused("this turn holds nothing, so it cannot write a template")
                _tpl_type = str(turn_type["id"])
            row = await pool.fetchrow(
                "INSERT INTO entity_task_templates (entity_id, name, prompt, steps, recurrence, type_id) "
                "VALUES ($1, $2, $3, $4::jsonb, $5, $6::uuid) RETURNING id, created_at",
                int(eid), name[:200], (prompt or None), _json.dumps(steps), recurrence, _tpl_type)
            # A template is instructions carried forward, so it is written
            # into the thread it was saved in, the way a scheduled task's plan
            # is (turn types: nothing runs later that the thread did not show).
            _ic = (interaction_context or "").strip()
            _proj = None
            if _ic.startswith("project:"):
                try:
                    _proj = int(_ic.split(":", 1)[1])
                except (TypeError, ValueError):
                    _proj = None
            _origin = {k: v for k, v in (
                ("interaction_context", _ic or None), ("session_id", session_id),
                ("project_id", _proj),
                ("thread_id", (str(thread_id).strip() or None) if thread_id else None),
            ) if v is not None}
            from mastercode.brain.offline_task_runner import post_to_origin_thread
            _posted = await post_to_origin_thread(
                pool, int(eid), _origin or None,
                (f"Saved runbook template **{name[:200]}** (#{row['id']})"
                 + (f", repeating {recurrence} when scheduled" if recurrence else "")
                 + ". When it runs I'll pick up from here:\n"
                 + _planned_text(prompt=prompt, steps=steps)),
                extra_tags={"task_template_id": row["id"]},
                fallback_session=f"task_template:{row['id']}")
            if not _posted:
                await pool.execute(
                    "DELETE FROM entity_task_templates WHERE id=$1 AND entity_id=$2",
                    row["id"], int(eid))
                return {"status": "error", "result": (
                    "the template was not saved: it could not be written into this "
                    "thread, and saved instructions are only what the thread shows.")}
            return {"status": "ok", "result": {
                "id": row["id"], "name": name,
                "steps": len(steps), "recurrence": recurrence,
                "created_at": row["created_at"].isoformat() if row["created_at"] else None}}

        if op == "list":
            rows = await pool.fetch(
                "SELECT id, name, prompt, steps, recurrence, created_at "
                "FROM entity_task_templates WHERE entity_id=$1 "
                "ORDER BY created_at DESC LIMIT 200",
                int(eid))
            out = []
            for r in rows:
                steps = r["steps"]
                if isinstance(steps, str):
                    try:
                        steps = json.loads(steps)
                    except Exception:
                        steps = []
                out.append({
                    "id": r["id"], "name": r["name"], "prompt": r["prompt"],
                    "steps": steps or [], "recurrence": r["recurrence"],
                    "created_at": r["created_at"].isoformat() if r["created_at"] else None})
            return {"status": "ok", "result": {"templates": out}}

        # op == "delete"
        tid = a.get("template_id")
        if tid in (None, ""):
            return _refused("template_id is required for op='delete'")
        try:
            tid = int(tid)
        except (TypeError, ValueError):
            return _refused("template_id must be an integer")
        res = await pool.execute(
            "DELETE FROM entity_task_templates WHERE id=$1 AND entity_id=$2",
            tid, int(eid))
        if res.endswith(" 0"):
            return _refused(f"no task_template with id {tid} for this host")
        return {"status": "ok", "result": {"deleted": tid}}
    except Exception as e:
        return _refused_if_caller(e, f"task_template failed: {getattr(e, 'detail', None) or e}")


async def _exec_reachout(args: dict, *, turn_type: dict | None = None) -> dict:
    """How the host reaches its person — channels, triggers, and a test fire.

    A doorbell, not a conversation: a short
    message on a channel the USER owns, carrying a link back into the thread
    that needs them. Every rule lives in server/reachout/service.py, which the
    /api/reachout routes call too — so this tool and the Circles pane can never
    end up enforcing two different things.

    Ops:
    BUILDING a channel is NOT here — it is `reachout_channel`
    (_exec_reachout_channel below), which is deliberately in neither
    DIRECT_OP_TOOLS nor UNATTENDED_OP_TOOLS. Everything left on this tool
    either reads, subscribes an EXISTING channel to an event, fires one the
    user already approved, or removes one; none of them can point a credential
    at a new destination, which is why they are safe to run with nobody there.

    Ops:
      list           channels, triggers, the last 20 fires, and the event
                     vocabulary a trigger can match.
      add_trigger    channel + label + match_kind (+ match_event, match_jsonb).
      test           fire one channel once with a synthetic message.
      remove_channel / remove_trigger — the host may remove what IT created; a
                     row the user created is theirs, and the refusal says where.
    """
    a = args or {}
    op = (a.get("op") or "list").strip()
    _OPS = {"list", "add_trigger", "test", "remove_channel", "remove_trigger"}
    if op not in _OPS:
        return _refused(f"op must be one of {sorted(_OPS)} (got {op!r})")
    try:
        from server import brain_service
        from server.reachout import service as _ro
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "reachout failed: pool unavailable"}
        eid = brain_service._entity_id

        if op == "list":
            return {"status": "ok", "result": await _ro.list_state(pool, int(eid))}

        # A runbook channel fires a task. From a TYPED turn it may only be
        # set off (test) or subscribed (add_trigger) when it was built under
        # this turn's type — otherwise a typed turn could run an untyped (or
        # another type's) runbook it could not have written.
        if turn_type is not None and op in ("add_trigger", "test") and a.get("channel") not in (None, ""):
            _ch = a.get("channel")
            if isinstance(_ch, int) or (isinstance(_ch, str) and str(_ch).isdigit()):
                _crow = await pool.fetchrow(
                    "SELECT kind, action FROM reachout_channels WHERE id=$1 AND entity_id=$2",
                    int(_ch), int(eid))
            else:
                _crow = await pool.fetchrow(
                    "SELECT kind, action FROM reachout_channels WHERE name=$1 AND entity_id=$2",
                    str(_ch).strip(), int(eid))
            _act = _crow["action"] if _crow is not None else None
            if isinstance(_act, str):
                try:
                    _act = json.loads(_act)
                except ValueError:
                    _act = {}
            _act = _act if isinstance(_act, dict) else {}
            # The transport dispatches on action.type (server/reachout/
            # transports.py TRANSPORTS), so that is what makes it a runbook —
            # not the channel's kind label.
            if _crow is not None and str(_act.get("type") or "").strip() == "runbook":
                # The type the fired task runs under, decided the same way
                # _send_runbook decides it: the channel's, else its template's.
                _act_type = str(_act.get("type_id") or "")
                if not _act_type:
                    try:
                        _tpl_tid = await pool.fetchval(
                            "SELECT type_id FROM entity_task_templates "
                            "WHERE id=$1 AND entity_id=$2",
                            int(_act.get("template_id")), int(eid))
                    except (TypeError, ValueError):
                        _tpl_tid = None
                    _act_type = str(_tpl_tid or "")
                if turn_type.get("status") != "active" or _act_type != str(turn_type.get("id")):
                    return {"status": "denied", "reason": "type_denied", "result": (
                        f"the runbook channel {_ch!r} was not built under this turn's type, "
                        "so a turn of this type cannot set it off. Build one here with "
                        "reachout_channel, or ask the user.")}

        if op == "add_trigger":
            ch = a.get("channel")
            if ch in (None, ""):
                return _refused("channel is required for op='add_trigger' "
                                  "(its name, or its id from op='list')")
            # A trigger on a RUNBOOK channel runs a model turn each time it
            # fires, with nobody watching: the person's card adds it
            # (runtime/scheduled_approval). Other channels
            # (email, a webhook, the log) send a notice and run no model.
            # The channel is found exactly as add_trigger finds it
            # (service._resolve_channel), so the one checked here is the one
            # the trigger would be added to; an unknown channel falls through
            # to add_trigger's own refusal.
            try:
                _rch = await _ro._resolve_channel(pool, int(eid), ch)
            except _ro.ReachoutError:
                _rch = None
            _trow = (await pool.fetchrow(
                "SELECT action FROM reachout_channels WHERE id=$1 AND entity_id=$2",
                int(_rch["id"]), int(eid)) if _rch is not None else None)
            _tact = _trow["action"] if _trow is not None else None
            if isinstance(_tact, str):
                try:
                    _tact = json.loads(_tact)
                except ValueError:
                    _tact = {}
            # Stripped as the dispatcher strips it (service.fire: TRANSPORTS
            # is keyed on action.type.strip()), and validate_action stores the
            # type unstripped, so " runbook" runs a runbook too.
            if isinstance(_tact, dict) and str(_tact.get("type") or "").strip() == "runbook":
                _label = (a.get("label") or "").strip()
                _mkind = (a.get("match_kind") or "").strip()
                if not _label or not _mkind:
                    # add_trigger's own refusals, said now rather than on the
                    # person's click.
                    return _refused("label and match_kind are required for op='add_trigger'")
                from mastercode.runtime import scheduled_approval as _sa
                return await _sa.propose_trigger(
                    pool, int(eid), channel=_rch.get("name") or ch,
                    channel_id=int(_rch["id"]), label=_label, match_kind=_mkind,
                    match_event=(a.get("match_event") or None),
                    match_jsonb=(a.get("match_jsonb") or None))
            row = await _ro.add_trigger(
                pool, int(eid), channel=ch, label=a.get("label") or "",
                match_kind=a.get("match_kind") or "",
                match_event=(a.get("match_event") or None),
                match_jsonb=(a.get("match_jsonb") or None),
                created_by="host")
            out = dict(row)
            if out.get("created_at") is not None:
                out["created_at"] = out["created_at"].isoformat()
            return {"status": "ok", "result": out}

        if op == "test":
            ch = a.get("channel")
            if ch in (None, ""):
                return _refused("channel is required for op='test'")
            res = await _ro.test_fire(pool, int(eid), ch)
            return {"status": "ok", "result": res}

        if op == "remove_channel":
            ch = a.get("channel")
            if ch in (None, ""):
                return _refused("channel is required for op='remove_channel'")
            return {"status": "ok",
                    "result": await _ro.remove_channel(pool, int(eid), ch, actor="host")}

        # op == "remove_trigger"
        tid = a.get("trigger_id")
        try:
            tid = int(tid)
        except (TypeError, ValueError):
            return _refused("trigger_id is required for op='remove_trigger' "
                              "(an integer, from op='list')")
        return {"status": "ok",
                "result": await _ro.remove_trigger(pool, int(eid), tid, actor="host")}
    except Exception as e:
        # ReachoutError carries the sentence the host should repeat to the user
        # (why the channel was refused, and what to do about it), so it is
        # surfaced verbatim rather than wrapped in a traceback.
        return _refused_if_caller(e, f"reachout: {getattr(e, 'detail', None) or e}")


async def _exec_reachout_channel(args: dict, *, turn_type: dict | None = None) -> dict:
    """BUILD a way for the host to reach its person. Its own tool, on purpose.

    WHY THIS IS NOT AN OP ON `reachout`. Creating an `http_call` channel binds
    one of the host's sealed credentials to an outbound destination, and the
    vault broker will then send that credential there on any later fire —
    including fires with nobody present, which is the entire point of the
    feature. That is a WIDEN, and it is the same class of thing
    `keys_manage` is kept out of the deterministic lane for (direct_ops.py,
    "credential bytes: keys_manage, connect_compute — credential handling keeps
    its dedicated gates + UI path").

    Two walls, and they close different holes:

      THE LANE. This name is in neither DIRECT_OP_TOOLS nor
      UNATTENDED_OP_TOOLS, so `run_direct_op` refuses it outright ("not a
      registered deterministic op") and `offline_task_runner._run_op` never
      reaches it. A scheduled `op_tool` cannot name it. That is structural and
      needs nobody to remember anything.

      THE SECOND FACTOR. server/reachout/service.add_channel demands a
      step-up code for an http_call action, through the same verifier the NAC
      widens use. This is the wall that does not depend on the lane table
      staying right: a TOTP is time-based and lives on the user's
      authenticator, so no stored payload can carry one that still verifies
      later.

    Splitting the tool rather than gating inside one was the available choice:
    `run_direct_op` reaches tools through `_execute_meta_tool` with
    `interaction_context=None` — the SAME arguments the chat path's generic
    meta branch passes (runtime/session.py) — so a handler cannot tell which
    lane invoked it, and a check written as if it could would have been
    decoration.
    """
    a = args or {}
    try:
        from server import brain_service
        from server.reachout import service as _ro
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "reachout_channel failed: pool unavailable"}
        eid = brain_service._entity_id
        # One `quiet` object rather than three top-level arguments: fewer names
        # on the wire, and the three only ever make sense together (a `from`
        # with no `to` is not a window).
        _q = a.get("quiet") if isinstance(a.get("quiet"), dict) else {}
        # A runbook channel fires a task template. From a TYPED turn, a
        # template saved under ANOTHER type is refused here, as schedule_task
        # refuses it: otherwise text written under one type would run as a
        # wake-up of this one. The channel's own
        # type is stamped by turn_types.stamp_scheduled_work at the gate.
        if turn_type is not None:
            _act = a.get("action")
            if isinstance(_act, str):
                try:
                    _act = json.loads(_act)
                except ValueError:
                    _act = {}
            _act = _act if isinstance(_act, dict) else {}
            if str(_act.get("type") or "").strip() == "runbook":
                try:
                    _tpl_type = await pool.fetchval(
                        "SELECT type_id FROM entity_task_templates "
                        "WHERE id=$1 AND entity_id=$2",
                        int(_act.get("template_id")), int(eid))
                except (TypeError, ValueError):
                    _tpl_type = None   # add_channel refuses a bad template_id
                if _tpl_type and str(_tpl_type) != str(turn_type.get("id") or ""):
                    return {"status": "denied", "reason": "type_denied", "result": (
                        f"template {_act.get('template_id')} was saved under another "
                        "turn type, so a turn of this type cannot build a runbook on it.")}
        row = await _ro.add_channel(
            pool, int(eid),
            name=a.get("name") or "", kind=a.get("kind") or "",
            action=a.get("action"),
            cooldown_s=a.get("cooldown_s"),
            quiet_from=(_q.get("from") or None),
            quiet_to=(_q.get("to") or None),
            quiet_tz=(_q.get("tz") or None),
            created_by="host",
            stepup_code=a.get("stepup_code"))
        out = dict(row)
        if out.get("created_at") is not None:
            out["created_at"] = out["created_at"].isoformat()
        return {"status": "ok", "result": out}
    except Exception as e:
        return _refused_if_caller(e, f"reachout_channel: {getattr(e, 'detail', None) or e}")


def _planned_text(*, prompt: str = "", steps=None, op_tool: str = "",
                  op_args=None) -> str:
    """What a scheduled task will do, in the words it was given — the text
    written into the thread when the task is set (turns types: the thread is
    the chain of thought; nothing runs later that the thread did not show)."""
    if op_tool:
        return (f"run `{op_tool}` with {json.dumps(op_args or {}, sort_keys=True)}"
                " (a fixed op, no model)")
    _steps = [str(s).strip() for s in (steps or []) if str(s).strip()]
    if _steps:
        return "\n".join(f"{i}. {s}" for i, s in enumerate(_steps, 1))
    return str(prompt or "").strip() or "(nothing written)"


async def _exec_schedule_task(args: dict, *, session_id: str | None = None,
                              interaction_context: str | None = None,
                              turn_type: dict | None = None,
                              thread_id: str | None = None) -> dict:
    """Create + manage the host's own SCHEDULED tasks — calendar events with a future
    fire time and optional recurrence, fired offline by the task runner. Create writes
    through the calendar service (handle_calendar_append) so the row carries recurrence;
    the runner re-arms recurring events to their next occurrence.

    `session_id` / `interaction_context` are the ORIGIN, handed over by the
    dispatcher. Until they were, every fired task reported into
    the Circles self-thread no matter where it was promised — so a "I'll check
    on the bot in twenty minutes" said in a Workbench project thread came back
    somewhere the user was not looking. They are recorded on the row
    (related_project_id + payload.origin) and the runner reports through them.

    A fired task IS auto-run, by the offline runner.
    brain/offline_task_runner.run_offline_tasks_loop is dispatched per entity from
    server/main.py's lifespan — the one create_task site for it in the repo — gated
    only on `relay_entity_id > 0`, with no per-entity rollout flag. (Deliberately no
    line number: this docstring pinned one, and a pointer comment added one commit
    later pushed the gate nine lines down. The symbol name is the durable reference.)
    It deliberately does NOT boot UnifiedBrain: it polls
    calendar_events for due tasks, atomically claims each one (so two overlapping ticks
    cannot double-run it), runs its prompt through brain_service.send_message — the same
    governed turn pipeline as live chat, with identity, tools and the CEIGAS gate —
    reports into THE THREAD IT WAS SET IN (payload.origin; a Circles task that names no
    thread, such as the platform's own standing tasks, gets a topic of its own the first
    time it writes, and keeps it: offline_task_runner.ensure_origin_thread), re-arms recurrence,
    and appends a calendar_event_runs row per run.

    This block said the opposite for months. What it used to claim, and why it was
    wrong, is in git log and tests/test_schedule_task_doc_truth.py — not re-quoted
    here, because this file is one a model reads.

    Ops:
      create -> schedule a task (title, fire_at ISO, optional recurrence, prompt/steps;
                optional wake_on {event, match}: run when that platform event
                happens, with fire_at as the deadline — server/host_events.py)
      list   -> upcoming scheduled tasks (status='scheduled')
      cancel -> cancel a scheduled task by event_id
    """
    a = args or {}
    op = (a.get("op") or "list").strip()
    _OPS = {"create", "list", "cancel"}
    if op not in _OPS:
        return _refused(f"op must be one of {sorted(_OPS)} (got {op!r})")
    try:
        from server import brain_service
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "schedule_task failed: pool unavailable"}
        eid = brain_service._entity_id

        if op == "create":
            title = (a.get("title") or "").strip()
            fire_at = (a.get("fire_at") or "").strip()
            if not title:
                return _refused("title is required for op='create'")
            # A thread the person deleted gets no new task: the delete
            # cancelled the ones set in it, and one written as it landed
            # would only be refused at every fire.
            if thread_id:
                from mastercode.circles_threads import live_thread_id
                if await live_thread_id(pool, int(eid), thread_id) is None:
                    return _refused("this thread was deleted, so nothing is scheduled in it")
            if not fire_at:
                return _refused("fire_at (ISO timestamp) is required for op='create'")
            recurrence = (a.get("recurrence") or "").strip() or None

            # ── Standing-work lane ──────────────────────────
            # op_tool schedules ONE deterministic registry op that fires with
            # no model in the loop. Exclusive with prompt/steps/template_id:
            # a task is either the host's judgement on a schedule, or a fixed
            # op on a schedule, and silently preferring one over the other
            # would hide which lane the work actually ran in.
            op_tool = (a.get("op_tool") or "").strip()
            op_args = a.get("op_args")
            if op_tool:
                if a.get("prompt") or a.get("input") or a.get("steps") or \
                        a.get("template_id") not in (None, ""):
                    return _refused("op_tool is exclusive with prompt / steps / template_id — "
                        "a scheduled task either runs a deterministic op or runs "
                        "a governed turn, never both.")
                if op_args is not None and not isinstance(op_args, dict):
                    return _refused("op_args must be an object (the op's exact arguments).")
                # Fitness, not permission: does this op complete with nobody
                # there? The authoritative check runs again at fire time in the
                # offline runner — this copy exists so the host is told NOW
                # rather than discovering it from a failed run at 03:00.
                from mastercode.runtime.direct_ops import (
                    UNATTENDED_OP_TOOLS, is_unattended_op_tool,
                )
                if not is_unattended_op_tool(op_tool):
                    return _refused(f"`{op_tool}` cannot be scheduled: it does not complete "
                        "without someone present (its result is something a "
                        "person has to act on). Schedulable ops today: "
                        + ", ".join(sorted(UNATTENDED_OP_TOOLS)) + ".")

            # Optional runbook TEMPLATE: stamp out its prompt + steps into the
            # task payload, entity-scoped. The caller's own prompt/steps win;
            # the template's recurrence is inherited only if the caller didn't
            # pass one. (s1-runbook)
            t_prompt = a.get("prompt") or a.get("input") or ""
            t_steps = a.get("steps") or []
            template_id = a.get("template_id")
            _template_type = None
            _template_name = None
            if template_id not in (None, ""):
                try:
                    tid = int(template_id)
                except (TypeError, ValueError):
                    return _refused("template_id must be an integer")
                trow = await pool.fetchrow(
                    "SELECT name, prompt, steps, recurrence, type_id FROM entity_task_templates "
                    "WHERE id=$1 AND entity_id=$2",
                    tid, int(eid))
                if trow is None:
                    return _refused(f"no task_template with id {tid} for this host")
                tsteps = trow["steps"]
                if isinstance(tsteps, str):
                    try:
                        tsteps = json.loads(tsteps)
                    except Exception:
                        tsteps = []
                if not t_prompt:
                    t_prompt = trow["prompt"] or ""
                if not t_steps:
                    t_steps = tsteps or []
                if not recurrence:
                    recurrence = (trow["recurrence"] or "").strip() or None
                _template_type = str(trow["type_id"]) if trow["type_id"] else None
                _template_name = trow["name"]

            # ── wake_on: run when something HAPPENS, fire_at is the deadline ──
            # (a Host scheduled a turn when it should have been monitoring).
            # The platform pulls the task forward at the one place the state
            # changes (server/host_events.emit); a task the event never reaches
            # runs at fire_at, and its pointer line says which of the two it was.
            # Checked after the template, because a template's recurrence is
            # inherited above.
            _wake = None
            if a.get("wake_on") not in (None, "", {}):
                from server.host_events import check_wake_on
                _wake, _why = check_wake_on(a.get("wake_on"))
                if _why:
                    return _refused(_why)
                if recurrence:
                    return _refused("wake_on cannot repeat: a wake fires once, when the thing "
                        "happens or at its deadline. Drop the recurrence (set a new wake "
                        "from the turn it starts if you need another), or drop wake_on "
                        "for a fixed schedule.")
                if op_tool:
                    return _refused("wake_on runs a turn, so it can say whether the thing "
                        "happened or the deadline came first; a fixed op cannot tell the "
                        "two apart. Use prompt (or steps) with wake_on.")

            # ── The governed-turn spend ceiling, refused at AUTHORING time ──
            # A prompt/steps task runs a full model turn on every fire. The
            # runner enforces a per-task ceiling at fire time
            # (offline_task_runner.max_runs_per_day / .runs_in_last_24h) because
            # this tool is not the only writer of a scheduled_task payload —
            # POST /api/calendar wraps handle_calendar_append directly. What
            # fire-time enforcement CANNOT do is tell the host NOW, so this
            # refuses the contradiction up front: a recurrence firing more often
            # than the ceiling allows would spend the first N turns of each day
            # and skip the rest, which is a schedule nobody chose. Naming both
            # numbers is the point — raising the ceiling and loosening the
            # recurrence are both real answers, and the host can pick.
            #
            # The OP lane is exempt: it runs no model, so there is nothing for a
            # spend ceiling to protect, and capping it would only break standing
            # work that already costs nothing. Passing one anyway is REFUSED
            # rather than accepted-and-dropped — it was validated here and then
            # silently not written to the payload, so the host would have been
            # told a limit was set that nothing anywhere would ever enforce.
            # The job's own budget, in dollars, when the person named one
            # ("spend up to $5 on this"): the runner stops the task once its
            # priced runs reach it (offline_task_runner.budget_state). It can
            # only narrow what runs; the person's limits still apply on top.
            _budget = a.get("budget_usd")
            if _budget is not None:
                if op_tool:
                    return _refused("budget_usd does not apply to op_tool: the op lane runs no "
                        "model and spends nothing.")
                try:
                    _budget = round(float(_budget), 4)
                except (TypeError, ValueError):
                    return _refused("budget_usd must be a number of dollars")
                if not _budget > 0:
                    return _refused("budget_usd must be more than $0; leave it out for no budget")
            _max_runs = a.get("max_runs_per_day")
            if _max_runs is not None:
                if op_tool:
                    return _refused("max_runs_per_day does not apply to op_tool: the op lane "
                        "runs no model, so it spends nothing and has no ceiling.")
                try:
                    _max_runs = int(_max_runs)
                except (TypeError, ValueError):
                    return _refused("max_runs_per_day must be a whole number of model turns a day")
                if _max_runs < 1:
                    return _refused("max_runs_per_day must be at least 1 model turn a day")
                # The person's limit is the most a task may carry (runtime/
                # user_limits, 2026-10-20): the Host can ask for less, and asks
                # the person for more.
                from mastercode.brain.offline_task_runner import person_turns_per_day
                if not op_tool and _max_runs > person_turns_per_day():
                    from mastercode.runtime import user_limits as _ul
                    return _refused(
                        f"max_runs_per_day {_max_runs} is above the person's limit of "
                        f"{person_turns_per_day()} model turns a day for one scheduled task. "
                        + _ul.hit_line("scheduled.turns_per_day"))

            if not op_tool:
                # The budget is in TURNS. The steps lane runs ONE GOVERNED TURN
                # PER STEP, so a fire of a 20-step task costs 20 turns, not 1 —
                # counting fires here would wave through 20x what the ceiling
                # says while every text the host reads calls them model turns.
                from mastercode.brain.offline_task_runner import person_turns_per_day
                _ceiling = _max_runs or person_turns_per_day()
                _limit = person_turns_per_day()
                _per_fire = len([s for s in (t_steps or []) if str(s).strip()]) or 1
                _step_note = (f" This task has {_per_fire} steps, and each step is a "
                              f"separate turn, so one fire costs {_per_fire} turns."
                              if _per_fire > 1 else "")
                # A single fire that cannot fit inside the whole daily ceiling is
                # a task that would never run once. Caught here regardless of
                # recurrence, because a one-shot hits it too.
                if _per_fire > _ceiling:
                    return _refused(f"One fire of this task runs {_per_fire} model turns (one per "
                        f"step), which is more than its ceiling of {_ceiling} turns a "
                        f"day — so it would never run at all. "
                        + (f"Raise max_runs_per_day to at least {_per_fire}, or use fewer steps."
                           if _per_fire <= _limit else
                           f"Use fewer steps, or ask the person to raise their limit "
                           f"scheduled.turns_per_day (now {_limit}, the most max_runs_per_day "
                           f"may be) with limits(op='propose')."))
                if recurrence:
                    from mastercode.brain.entity_clock import _recurrence_seconds
                    if _recurrence_seconds(recurrence) is None:
                        return _refused("recurrence must be one of: hourly, daily, weekly, monthly, or every:<seconds>")
                    _period = _recurrence_seconds(recurrence)
                    _fires = 86400 // _period if _period else 0
                    _implied = _fires * _per_fire
                    if _implied > _ceiling:
                        _slowest = -(-86400 * _per_fire // _ceiling)
                        return _refused(f"'{recurrence}' fires {_fires} times a day, which is "
                            f"{_implied} model turns, and this task's ceiling is "
                            f"{_ceiling} turns a day.{_step_note} Turns past the ceiling "
                            f"are skipped, so this schedule would stop partway through "
                            f"every day. Either "
                            + (f"raise max_runs_per_day to at least {_implied}"
                               if _implied <= _limit else
                               f"ask the person to raise their limit scheduled.turns_per_day "
                               f"(now {_limit}, the most max_runs_per_day may be) to at least "
                               f"{_implied} with limits(op='propose')")
                            + f", or space the schedule out to at least "
                            f"every:{_slowest} seconds. If the work is identical each "
                            f"time, op_tool runs it with no model at all and has no "
                            f"ceiling.")
            elif recurrence:
                from mastercode.brain.entity_clock import _recurrence_seconds
                if _recurrence_seconds(recurrence) is None:
                    return _refused("recurrence must be one of: hourly, daily, weekly, monthly, or every:<seconds>")
            # WHERE this was promised. A timer set mid-conversation owes its
            # answer to that conversation; `related_project_id` has been a
            # column on calendar_events all along and nothing ever wrote it
            # from here, so every fired task landed in the Circles self-thread
            # regardless of origin.
            _origin_project = None
            _ic = (interaction_context or "").strip()
            if _ic.startswith("project:"):
                try:
                    _origin_project = int(_ic.split(":", 1)[1])
                except (TypeError, ValueError):
                    _origin_project = None
            _origin = {k: v for k, v in (
                ("interaction_context", _ic or None),
                ("session_id", session_id),
                ("project_id", _origin_project),
                # The Circles thread it was set in: the plan is written
                # there now, and the fired turn thinks and reports there.
                ("thread_id", str(thread_id).strip() or None if thread_id else None),
            ) if v is not None}
            _body = ({"op": {"tool": op_tool, "args": op_args or {}}}
                     if op_tool else
                     {"prompt": t_prompt, "steps": t_steps})
            if _origin:
                _body["origin"] = _origin
            # A task written in a turn that read untrusted content carries
            # that into the turn it fires (runtime/turn_taint);
            # one written in a clean turn fires clean.
            from mastercode.runtime import turn_taint as _turn_taint
            _body = _turn_taint.stamp(_body)
            if _wake:
                _body["wake_on"] = _wake
            # Only the turn lane carries a ceiling — writing one onto an op
            # payload would suggest the op lane is capped, and it is not.
            if _max_runs is not None and not op_tool:
                _body["max_runs_per_day"] = _max_runs
            if _budget is not None:
                _body["budget_usd"] = _budget
            # ── The task's turn type ─────
            # A typed turn schedules under its OWN type only, never another
            # and never none: a wake-up is the same chain of thought
            # continuing later, inside the same walls. Across types only the
            # platform-written timeline crosses (no hidden
            # notes between turns — a note is the threat). An untyped turn
            # may name an active type or none. A closed turn schedules
            # nothing. The runner checks the type again at fire time.
            _want_type = str(a.get("type_id") or "").strip() or None
            _own_type = str((turn_type or {}).get("id") or "") or None if turn_type else None
            if turn_type is not None and turn_type.get("status") == "closed":
                return {"status": "error", "result": (
                    "this turn holds nothing (its turn type could not be read), "
                    "so it cannot schedule anything")}
            if turn_type is not None and _want_type and _want_type != _own_type:
                return _refused("a scheduled task runs under the type of the turn that sets it. "
                    "This turn cannot set work for another type; say in the thread "
                    "what that work is, and the user can take it there.")
            if turn_type is not None and _template_type and _template_type != _own_type:
                return _refused(f"template {template_id} was saved under another turn type, so a "
                    "turn of this type cannot run it.")
            # An untyped turn stamping a typed template keeps the template's type.
            _stamp = _own_type or _want_type or _template_type
            if _stamp:
                from mastercode.runtime.turn_types import load_turn_type_by_id
                _t = await load_turn_type_by_id(pool, int(eid), _stamp)
                if _t.get("status") != "active":
                    return _refused(f"type_id {_stamp!r}: {_t.get('closed_reason')}")
                if _want_type and _template_type and _want_type != _template_type:
                    return _refused(f"template {template_id} was saved under another turn type "
                        "than the type_id given.")
                _body["type_id"] = str(_t["id"])
            # The plan goes into the thread FIRST, in the words it was given,
            # and the row is inserted only once that write has landed: the
            # thread is the chain of thought, and nothing may fire that the
            # thread did not show (a row inserted first could be claimed by
            # the runner while the plan write was still in flight). The event
            # id is chosen here so the plan entry
            # and the row name each other; the runner checks the entry is
            # there before it runs anything (plan_event_id).
            import uuid as _uuid
            _event_uuid = str(_uuid.uuid4())
            _body["plan_in_thread"] = True
            # A plan write that is only QUEUED (PII mode) may not land; the
            # runner looks the entry up by this id before the task runs. A
            # direct write has landed by the time the row exists, so it needs
            # no lookup (and no per-fire scan of the turn rows).
            from mastercode import pii_queue as _pii
            if _pii.enabled():
                _body["plan_event_id"] = _event_uuid
            _plan = _planned_text(prompt=t_prompt, steps=t_steps,
                                  op_tool=op_tool, op_args=op_args)
            _from_tpl = (f" (from template {_template_name})" if _template_name else "")
            from server.host_events import describe as _describe_event
            _plan_msg = ((f"Scheduled **{title}** to run when "
                          f"{_describe_event(_wake['event'], _wake['match'])} happens, "
                          f"or at {fire_at} if it has not by then"
                          if _wake else f"Scheduled **{title}** for {fire_at}")
                         + (f", repeating {recurrence}" if recurrence else "")
                         + f"{_from_tpl}. When it fires "
                         + ("it will " if op_tool else "I'll pick up from here:\n")
                         + _plan)
            _append = {
                "event_id": _event_uuid,
                "event_type": "scheduled_task",
                "summary": title,
                "event_at": fire_at,
                "status": "scheduled",
                "source": "entity",
                "recurrence": recurrence,
                "related_project_id": _origin_project,
                "payload": _body,
            }
            # A RECURRING task that runs a model is the person's to start
            # (runtime/scheduled_approval): validated as
            # above, then a card instead of the row. Their click writes this
            # same plan and row. One-time tasks and the op lane are set as before.
            from mastercode.runtime import scheduled_approval as _sa
            if _sa.needs_approval(recurrence=recurrence, op_tool=op_tool, op_args=op_args):
                from mastercode.brain.offline_task_runner import person_turns_per_day
                # An op that sets a model task on every fire is counted by the
                # steps of the task it sets (scheduled_approval.model_turn).
                _turn_steps = ((_sa.model_turn(op_tool, op_args) or {}).get("steps")
                               if op_tool else t_steps)
                return await _sa.propose(
                    pool, int(eid), title=title, recurrence=recurrence, fire_at=fire_at,
                    plan_msg=_plan_msg, append=_append, origin=_origin or None,
                    turns_per_fire=len([x for x in (_turn_steps if isinstance(_turn_steps, list)
                                                     else []) if str(x).strip()]) or 1,
                    turns_per_day=(_max_runs or person_turns_per_day()),
                    budget_usd=_budget)
            from mastercode.brain.offline_task_runner import post_to_origin_thread
            _posted = await post_to_origin_thread(
                pool, int(eid), _origin or None, _plan_msg,
                # calendar_events.event_id (a uuid); the runner's reports
                # carry its integer id as scheduled_task_id.
                extra_tags={"scheduled_event_id": _event_uuid,
                            "scheduled_plan": True},
                fallback_session=f"scheduled_task:{_event_uuid}")
            if not _posted:
                return {"status": "error", "result": (
                    "the task was not set: its plan could not be written into this "
                    "thread, and a task runs only what the thread shows.")}
            from server.bridge.memory_handlers import handle_calendar_append
            env = await handle_calendar_append(_append)
            if not env.get("ok"):
                _why = env.get("error") or "schedule_task create failed"
                # The plan is already in the thread; say plainly it was not set.
                await post_to_origin_thread(
                    pool, int(eid), _origin or None,
                    f"(Not set after all — **{title}**: {_why}.)",
                    extra_tags={"scheduled_event_id": _event_uuid,
                                "scheduled_plan_withdrawn": True},
                    fallback_session=f"scheduled_task:{_event_uuid}")
                return {"status": "error", "result": _why}
            return {"status": "ok", "result": {
                "scheduled": title, "event_id": env.get("event_id"),
                # The plan is in the thread now; the user saw it.
                "plan_in_thread": True,
                "fire_at": env.get("event_at"), "recurrence": recurrence,
                # Waiting for something to happen: fire_at is then the
                # deadline, and the turn runs at whichever comes first.
                **({"wake_on": _wake, "deadline": env.get("event_at")} if _wake else {}),
                # The turn type it fires under; None = untyped.
                "type_id": _body.get("type_id"),
                # Say WHERE the answer will appear, so the host can tell the
                # user rather than guess — and so a wrong thread is visible
                # in the tool result instead of at fire time.
                # Derived the SAME way the runner picks the room, or this
                # is the "tool result says X while Y happens" shape the rest
                # of this branch exists to remove: keyed on the project alone
                # it told a General-thread timer "Circles".
                "reports_into": (
                    f"project {_origin_project} thread"
                    if _origin_project is not None else
                    ("your Circles thread"
                     if _ic in ("", "chat", "circles") else
                     f"your {_ic} thread")),
                # Name the lane back to the host so "did that cost tokens?" is
                # answerable from the tool result, not inferred from the args.
                "lane": "op" if op_tool else "turn",
                **({"op_tool": op_tool} if op_tool else {})}}

        if op == "list":
            rows = await pool.fetch(
                "SELECT event_id, title, start_time, recurrence, payload FROM calendar_events "
                "WHERE entity_id=$1 AND status='scheduled' AND event_type='scheduled_task' "
                "ORDER BY start_time ASC LIMIT 100",
                int(eid))

            def _payload(raw) -> dict:
                """The payload column is JSONB and asyncpg may hand it back as
                a string, so both shapes are read (same as the offline runner)."""
                p = raw or {}
                if isinstance(p, str):
                    try:
                        p = json.loads(p)
                    except Exception:
                        return {}
                return p if isinstance(p, dict) else {}

            def _lane(p: dict) -> tuple[str, str | None]:
                """Which lane this standing task runs in, for the list view."""
                spec = p.get("op")
                if isinstance(spec, dict) and str(spec.get("tool") or "").strip():
                    return "op", str(spec["tool"]).strip()
                return "turn", None

            out = []
            for r in rows:
                _p = _payload(r["payload"])
                lane, op_tool_name = _lane(_p)
                item = {"event_id": str(r["event_id"]), "title": r["title"],
                        "fire_at": r["start_time"].isoformat() if r["start_time"] else None,
                        "recurrence": r["recurrence"],
                        # Visibility is the counterpart of not asking: a standing
                        # op is created without a prompt, so it must be legible
                        # everywhere it is listed — including which lane it runs
                        # in and therefore whether it spends tokens.
                        "lane": lane}
                if op_tool_name:
                    item["op_tool"] = op_tool_name
                if isinstance(_p.get("wake_on"), dict):
                    # fire_at is its deadline; woke_on is set once the event
                    # came and the task is due now.
                    item["wake_on"] = _p["wake_on"]
                    if isinstance(_p.get("woke_on"), dict):
                        item["woke_on"] = _p["woke_on"]
                out.append(item)
            return {"status": "ok", "result": {"scheduled": out}}

        # op == "cancel"
        event_id = (a.get("event_id") or "").strip()
        if not event_id:
            return _refused("event_id is required for op='cancel'")
        res = await pool.execute(
            "UPDATE calendar_events SET status='cancelled' "
            "WHERE event_id=$1::uuid AND entity_id=$2 AND status='scheduled'",
            event_id, int(eid))
        if res.endswith(" 0"):
            return _refused(f"no scheduled task with event_id {event_id!r}")
        return {"status": "ok", "result": {"cancelled": event_id}}
    except Exception as e:
        return _refused_if_caller(e, f"schedule_task failed: {getattr(e, 'detail', None) or e}")


# The model catalog is ~400 rows with descriptions and modality lists — as a
# tool result it ran ~184KB and hit the transcript wall mid-transcript
# (tool_result_wall.py caps at 100KB and tells the model to "use the tool's
# limit/offset params"), but neither catalog tool HAD any.
# This is that contract: filters + a page, compact rows, and an honest total.
_CATALOG_DEFAULT_LIMIT = 25
_CATALOG_MAX_LIMIT = 200


def _compact_catalog(cat: dict, a: dict | None = None) -> dict:
    """Page + filter the raw inference catalog into a transcript-sized answer.

    Args (all optional, read from `a`): search (case-insensitive substring over
    id/name), provider ('openrouter' | 'local' | any provider tag the rows
    carry), capability ('vision' = accepts image input; 'image_gen' = produces
    images), limit (default 25, max 200), offset (default 0).

    Rows are compact — id, name, provider, context_length, per-token prices,
    two capability flags, bastion for local rows — never the 240-char
    descriptions. The envelope carries total_available / total_matched /
    next_offset so a model can page deliberately instead of hitting a cliff.
    Pure function: no I/O, so the gate exercises it directly."""
    a = a or {}
    cat = cat if isinstance(cat, dict) else {}
    rows: list[dict] = []
    for key in ("openrouter_models", "local_models"):
        for m in cat.get(key) or []:
            if isinstance(m, dict) and m.get("id"):
                rows.append(m)
    total_available = len(rows)

    search = str(a.get("search") or a.get("query") or "").strip().lower()
    provider = str(a.get("provider") or "").strip().lower()
    capability = str(a.get("capability") or "").strip().lower()
    try:
        limit = int(a.get("limit") or _CATALOG_DEFAULT_LIMIT)
    except (TypeError, ValueError):
        limit = _CATALOG_DEFAULT_LIMIT
    limit = max(1, min(_CATALOG_MAX_LIMIT, limit))
    try:
        offset = max(0, int(a.get("offset") or 0))
    except (TypeError, ValueError):
        offset = 0

    # Capability vocabulary is CLOSED: an unknown value must not fall through
    # and silently match every row while the envelope claims a filter ran.
    # Aliases map onto the two real capabilities.
    _CAP_ALIASES = {"vision": "vision", "image_gen": "image_gen", "image": "image_gen",
                    "image_generation": "image_gen"}
    if capability and capability not in _CAP_ALIASES:
        return {"error": (f"unknown capability {capability!r} — use 'vision' (accepts image "
                          f"input) or 'image_gen' (produces images)"),
                "models": [], "total_available": total_available, "total_matched": 0,
                "offset": offset, "limit": limit, "next_offset": None}
    capability = _CAP_ALIASES.get(capability, "")

    def _mods(m: dict, key: str) -> list[str]:
        return [str(x).lower() for x in (m.get(key) or [])]

    def _publishes(m: dict) -> bool:
        # A row with no modality lists at all has not PUBLISHED its
        # capabilities (local Ollama rows never do; an OpenRouter row with no
        # `architecture` reads as []). Unknown is not "unable" — the same
        # distinction get_capable_models draws with capability_published.
        return bool(m.get("input_modalities") or m.get("output_modalities"))

    def _vision(m: dict) -> bool:
        return "image" in _mods(m, "input_modalities")

    def _image_gen(m: dict) -> bool:
        return "image" in _mods(m, "output_modalities")

    matched = []
    capability_unknown = 0
    for m in rows:
        if search and search not in f"{m.get('id', '')} {m.get('name', '')}".lower():
            continue
        if provider and str(m.get("provider") or "").lower() != provider:
            continue
        if capability:
            if not _publishes(m):
                capability_unknown += 1   # counted, reported, never called incapable
                continue
            if capability == "vision" and not _vision(m):
                continue
            if capability == "image_gen" and not _image_gen(m):
                continue
        matched.append(m)

    page = matched[offset:offset + limit]
    compact = []
    for m in page:
        published = _publishes(m)
        row = {
            "id": m.get("id"),
            "name": m.get("name") or m.get("id"),
            "provider": m.get("provider"),
            "context_length": m.get("context_length"),
            "input_per_token": m.get("input_per_token"),
            "output_per_token": m.get("output_per_token"),
            # None = the row publishes no modalities (unknown), never False.
            "vision": _vision(m) if published else None,
            "image_gen": _image_gen(m) if published else None,
        }
        if m.get("bastion"):
            row["bastion"] = m.get("bastion")
        compact.append(row)

    next_offset = offset + limit if offset + limit < len(matched) else None
    out = {
        "models": compact,
        "total_available": total_available,
        "total_matched": len(matched),
        "offset": offset,
        "limit": limit,
        "next_offset": next_offset,
        "filters": {"search": search or None, "provider": provider or None,
                    "capability": capability or None},
        "degraded": bool(cat.get("degraded")),
        "note": ("A PAGE of the catalog, compact rows. Narrow with search= / provider= / "
                 "capability='vision'|'image_gen'; page with offset=next_offset. The full "
                 "list is never returned in one call."),
    }
    if capability:
        out["capability_unknown"] = capability_unknown
        if capability_unknown:
            out["note"] += (f" {capability_unknown} matching row(s) publish no modality "
                            "lists (local models never do) and were left out of this page "
                            "— unknown is not 'unable'; say so rather than 'none can'.")
    if cat.get("roles") is not None:
        out["roles"] = cat.get("roles")
    return out


async def _exec_model_route(args: dict) -> dict:
    """Inspect or change which model the host uses, per role. Calls the inference
    service fns DIRECTLY (server.routes.inference — no HTTP shim). A route is a
    {provider, model} pair on the user's own account (no platform-metered lane):
    provider is a Keys-registry id (openrouter, openai, xai, anthropic, …) or
    'local' (a machine they run). Ops:
      catalog -> ONE PAGE of the live inference catalog (OpenRouter + local),
                 filtered by search/provider/capability, limit/offset
      current -> current per-role routing + the EFFECTIVE model each role resolves to
      switch  -> assign a model to a role (role, provider, model_id)
    """
    a = args or {}
    op = (a.get("op") or "current").strip()
    _OPS = {"catalog", "current", "switch"}
    if op not in _OPS:
        return _refused(f"op must be one of {sorted(_OPS)} (got {op!r})")
    try:
        from server.routes import inference as inf   # get_model_catalog: inference.py:113
        if op == "catalog":
            return {"status": "ok", "result": _compact_catalog(await inf.get_model_catalog(), a)}
        if op == "current":
            return {"status": "ok", "result": await inf.get_current_routing()}
        # op == "switch"
        role = (a.get("role") or "").strip()
        provider = (a.get("provider") or "").strip()
        model_id = (a.get("model_id") or a.get("model") or "").strip()
        if not role or not provider or not model_id:
            return _refused("role, provider, and model_id are required for op='switch'")
        # The same door as model_routing op='set' (runtime/route_change):
        # this tool used to write straight through the Orchestrator's own
        # handler, stamped as the USER's write — an ungated twin of the gated
        # tool, and one that minted its own approval for the revert rule.
        return await _host_route_write(role=role, provider=provider.lower(), model=model_id,
                                       reason=(a.get("reason") or "").strip() or None)
    except Exception as e:
        return _refused_if_caller(e, f"model_route failed: {getattr(e, 'detail', None) or e}")


async def _exec_inference_catalog(args: dict) -> dict:
    """ONE PAGE of the available inference
    model catalog (OpenRouter + local Ollama) — the SAME catalog the in-chat
    model picker reads, filtered/paged by _compact_catalog (search / provider /
    capability / limit / offset). Calls the inference service fn DIRECTLY
    (server.routes.inference, no HTTP shim), which is cached + built off the
    event loop. Read-only."""
    try:
        from server.routes import inference as inf   # get_model_catalog: inference.py:113
        return {"status": "ok", "result": _compact_catalog(await inf.get_model_catalog(), args or {})}
    except Exception as e:
        return _refused_if_caller(e, f"inference_catalog failed: {getattr(e, 'detail', None) or e}")


async def _exec_context(args: dict, entity_id: int, pool, *, thread_id: str | None = None,
                        session_id: str | None = None) -> dict:
    """The host's own context-file store (entity_context) — read/write/list/
    search/delete/status. Body in runtime/context_ops.py.

    It was the last tool on the retired bot lane (public_bots/ via
    BotExecutor). entity_id and pool come from
    _execute_meta_tool's own arguments, so this handler needs no brain_service
    lookup — and it runs AFTER the capability gate, which checks `context`'s
    META_TOOL_CAPS bits (1|2|4) against entity_bits & grant_bits.
    """
    try:
        from mastercode.runtime.context_ops import run_context_op
        return await run_context_op(pool, entity_id, args or {}, thread_id=thread_id,
                                    session_id=session_id)
    except Exception as e:
        log.exception("context op failed (entity=%s)", entity_id)
        return _refused_if_caller(e, f"context failed: {getattr(e, 'detail', None) or e}")


async def _exec_links(args: dict, entity_id: int, pool) -> dict:
    """The host's saved links (entity_links) — save/list/search/get/remove.
    Body in runtime/link_ops.py.

    Same shape as _exec_context above: entity_id and pool come from
    _execute_meta_tool's own arguments, so no brain_service lookup is needed, and
    this runs AFTER the capability gate, which checks `links`'s META_TOOL_CAPS
    bits (1|2|4) against entity_bits & grant_bits.
    """
    try:
        from mastercode.runtime.link_ops import run_link_op
        return await run_link_op(pool, entity_id, args or {})
    except Exception as e:
        log.exception("links op failed (entity=%s)", entity_id)
        return _refused_if_caller(e, f"links failed: {getattr(e, 'detail', None) or e}")


_IMAGE_BOT_MOD = None


def _load_image_bot():
    """The image engine. Was load-by-path out of public_bots/ because the
    `00100001_` filename prefix made it un-importable by name; it is
    mastercode.image_engine and imports normally."""
    global _IMAGE_BOT_MOD
    if _IMAGE_BOT_MOD is None:
        from mastercode import image_engine
        _IMAGE_BOT_MOD = image_engine
    return _IMAGE_BOT_MOD


async def _exec_image_generate(args: dict) -> dict:
    """Generate, look at, or browse images via the host's image engine. Wraps the
    image engine (mastercode/image_engine.py) with its own context object.
    generate runs on the user's OWN routed image model and key — the 'image_gen'
    role — with no platform key and no platform charge: the platform billing
    path is removed (image_engine.py header). An unrouted role
    returns a "set one up" message, not a billing refusal. Actions:
      generate -> create image(s) from a prompt (prompt; optional n — passed to
                  the provider as asked, it refuses past its own maximum;
                  optional size, quality)
      look     -> the Host's own model looks at pictures (images: a list of
                  /api/images/<id>, gallery entries, file:<name>, http(s) urls;
                  question). Its own pictures are shown in its own turn
                  (runtime/turn_pictures); with a picture from the web among
                  them, one call of its own model with no tools answers the
                  question instead. There is no vision route: image
                  understanding is the host's own.
      gallery  -> list the host's images newest first, paged (offset, limit;
                  total + next_offset) (free, local read)
    """
    a = args or {}
    action = (a.get("action") or a.get("op") or "generate").strip()
    if action == "understand":
        return _refused("action='understand' was removed 2026-10-12: your own model looks at "
                        "pictures. Use action='look' images=[...] (and question= for a "
                        "picture from the web)")
    if action not in ("generate", "look", "gallery"):
        return _refused(f"action must be one of generate/look/gallery (got {action!r})")
    try:
        from server import brain_service
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "image_generate failed: pool unavailable"}
        eid = brain_service._entity_id
        mod = _load_image_bot()
        # NOTE: the raw pool, exactly as before — this handler never wrapped the
        # engine in a SandboxedPool. Preserved deliberately; changing it here
        # would be an unrelated behaviour change riding a retirement.
        ctx = mod.EngineContext(
            entity_id=eid, entity_name=f"entity_{eid}",
            capabilities=["read_context", "external_api"], pool=pool,
            args={"action": action,
                  "prompt": a.get("prompt", ""), "n": a.get("n", 1),
                  "size": a.get("size"), "quality": a.get("quality"),
                  "images": a.get("images"), "question": a.get("question", ""),
                  "offset": a.get("offset"), "limit": a.get("limit")},
        )
        res = await mod.run(ctx)
        # A picture the Host looked at marks its turn as the picture's source
        # would have (runtime/turn_taint): an app's render is MCP output, a
        # file the person gave it is an upload, a picture from the web is the
        # web — even though a web picture was only seen by a call with no tools,
        # its answer is the web's words.
        _origins = (res or {}).pop("origins", None) or []
        if _origins:
            from mastercode.runtime import turn_taint as _tt
            _marks = {"app": (_tt.MCP, "a picture an app returned"),
                      "upload": (_tt.UPLOAD, "a picture the person gave the Host"),
                      "web": (_tt.WEB, "a picture from the web")}
            for _o in _origins:
                if _o in _marks:
                    _tt.mark(*_marks[_o])
        if (res or {}).get("status") == "ok":
            return {"status": "ok", "result": {k: v for k, v in res.items() if k != "status"}}
        return {"status": "error", "result": (res or {}).get("result") or "image op failed"}
    except Exception as e:
        return _refused_if_caller(e, f"image_generate failed: {getattr(e, 'detail', None) or e}")


# A clone that has said nothing for this long — no progress line, no byte on
# stderr — is stalled; one that keeps reporting runs as long as it needs.
# git --progress writes at least once a second while counting, receiving,
# resolving deltas and checking out, so two minutes of silence is a dead
# transfer, not a slow one.
_CLONE_IDLE_S = 120


async def _run_with_progress_liveness(cmd: list, *, env: dict | None = None,
                                      idle_s: float | None = None) -> tuple[int, str, bool]:
    """Run `cmd`, judging it by its stderr progress instead of a wall clock.

    Returns (returncode, stderr tail, stalled). stalled=True means no stderr
    output for idle_s seconds — the process was killed. stdout is discarded."""
    import asyncio
    idle = float(_CLONE_IDLE_S if idle_s is None else idle_s)
    proc = await asyncio.create_subprocess_exec(
        *cmd, stdout=asyncio.subprocess.DEVNULL, stderr=asyncio.subprocess.PIPE, env=env)
    tail = b""
    stalled = False
    while True:
        try:
            chunk = await asyncio.wait_for(proc.stderr.read(4096), timeout=idle)
        except asyncio.TimeoutError:
            stalled = True
            proc.kill()
            break
        if not chunk:
            break
        tail = (tail + chunk)[-4096:]
    rc = await proc.wait()
    text = tail.decode("utf-8", "ignore").replace("\r", "\n")
    lines = [ln.strip() for ln in text.split("\n") if ln.strip()]
    return rc, "\n".join(lines[-6:]), stalled


# The helper git runs for a credential on the platform forge. The values ride
# the clone's environment, never its argv or the URL, and git asks this helper
# only for a URL on the forge's host (credential.<url>.helper); a redirect or a
# submodule elsewhere gets nothing.
_FORGE_CRED_HELPER = ('!f() { test "$1" = get || exit 0; '
                      'echo "username=$PRIVATAE_FORGE_USER"; '
                      'echo "password=$PRIVATAE_FORGE_TOKEN"; }; f')


def _forge_clone_auth(url: str) -> tuple[list, dict]:
    """(git -c args, env) that let a clone of `url` read a private repository
    on the platform's own forge as this Host — the pod's forge credential,
    which import_repo otherwise turns off with GIT_CONFIG_GLOBAL=/dev/null.
    Empty for any other host: a GitHub or third-party clone never sees the
    forge's credential. Empty too when the URL carries its own credentials or
    the Host has none."""
    from urllib.parse import urlsplit
    try:
        parts = urlsplit(url)
    except ValueError:
        return [], {}
    if parts.scheme != "https" or parts.username or parts.password:
        return [], {}
    try:
        from server.routes.gitea_client import gitea_creds, gitea_proxy
        cred = gitea_creds()
    except Exception:  # noqa: BLE001 — no forge here: a plain clone
        return [], {}
    if not cred:
        return [], {}
    user, token, host = cred
    if (parts.netloc or "").lower() != str(host or "").lower():
        return [], {}
    env = {"PRIVATAE_FORGE_USER": user, "PRIVATAE_FORGE_TOKEN": token}
    try:
        proxy = gitea_proxy()
    except Exception:  # noqa: BLE001
        proxy = ""
    if proxy:
        # The forge is reached through the same egress proxy every forge call
        # uses (gitea_client.gitea_request, gitea_propose._git_work).
        env.update({"https_proxy": proxy, "HTTPS_PROXY": proxy})
    return (["-c", "credential.helper=",
             "-c", f"credential.https://{host}.helper={_FORGE_CRED_HELPER}"], env)


async def _exec_import_repo(args: dict) -> dict:
    """Import an existing codebase from a Git URL (a GitHub pull) into a project
    workspace, so the host can index/search/build on it. Creates a new project (or
    clones into an existing one) and shallow-clones the repo into its workspace at
    /var/lib/cseries/projects/<id>. PUBLIC repos need no credentials. A private repo
    on the platform's own forge is cloned with the Host's forge credential
    (_forge_clone_auth), offered to that host only; anywhere else a private repo
    needs a token embedded in the https URL. Args:
      github_url (required) — an https:// git URL (e.g. https://github.com/owner/repo)
      name (optional)       — project name (defaults to the repo name)
      branch (optional)     — branch/tag to clone (default: the repo's default)
      project_id (optional) — clone into an existing project instead of creating one
    """
    import os
    import re
    import shutil
    a = args or {}
    url = (a.get("github_url") or a.get("url") or "").strip()
    if not url:
        return _refused("github_url is required")
    if not re.match(r"^https://[A-Za-z0-9._~:/?#@!$&'()*+,;=%\[\]-]+$", url):
        return _refused("github_url must be an https:// git URL (no ssh/file URLs)")
    branch = (a.get("branch") or "").strip()
    try:
        from server import brain_service
        from server.routes.applications import PROJECTS_ROOT
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "import_repo failed: pool unavailable"}
        eid = brain_service._entity_id

        repo_name = url.rstrip("/").split("/")[-1]
        if repo_name.endswith(".git"):
            repo_name = repo_name[:-4]
        name = (a.get("name") or repo_name or "imported-repo").strip()

        created = False
        if a.get("project_id") is not None:
            try:
                pid = int(a.get("project_id"))
            except (TypeError, ValueError):
                return _refused("project_id must be an integer")
            if await pool.fetchrow("SELECT id FROM projects WHERE id=$1 AND entity_id=$2", pid, eid) is None:
                return _refused(f"project {pid} not found")
        else:
            row = await pool.fetchrow(
                "INSERT INTO projects (entity_id, name, description) VALUES ($1,$2,$3) RETURNING id",
                eid, name, f"Imported from {url}")
            pid = row["id"]
            created = True

        project_dir = str(PROJECTS_ROOT / str(pid))
        if os.path.isdir(project_dir) and os.listdir(project_dir):
            if created:
                await pool.execute("DELETE FROM projects WHERE id=$1 AND entity_id=$2", pid, eid)
            return _refused(f"project {pid} workspace is not empty — import into a new project")

        # No-shell exec (no injection); fail fast instead of hanging on auth prompts.
        # --progress makes git report as it goes even without a terminal, and
        # the clone is judged by that liveness, never by a clock (a 180 s
        # wall cut large repos through the egress proxy while they were still
        # arriving).
        env = {**os.environ, "GIT_TERMINAL_PROMPT": "0",
               "GIT_CONFIG_GLOBAL": "/dev/null", "GIT_CONFIG_SYSTEM": "/dev/null"}
        auth_args, auth_env = _forge_clone_auth(url)
        env.update(auth_env)
        cmd = (["git", *auth_args, "clone", "--progress", "--depth", "1"]
               + (["--branch", branch] if branch else []) + [url, project_dir])
        rc, err_tail, stalled = await _run_with_progress_liveness(cmd, env=env)
        if stalled or rc != 0:
            shutil.rmtree(project_dir, ignore_errors=True)
            if created:
                await pool.execute("DELETE FROM projects WHERE id=$1 AND entity_id=$2", pid, eid)
            if stalled:
                return {"status": "error", "result":
                        f"git clone stopped: no progress for {_CLONE_IDLE_S}s "
                        f"(last output: {err_tail[-200:] or 'none'})"}
            return {"status": "error", "result": f"git clone failed: {err_tail[-300:] or 'unknown error'}"}

        nfiles = sum(len(fs) for root, _, fs in os.walk(project_dir) if ".git" not in root.split(os.sep))
        return {"status": "ok", "result": {
            "project_id": pid, "name": name, "source": url,
            "branch": branch or "default", "files": nfiles, "created_project": created}}
    except Exception as e:
        return _refused_if_caller(e, f"import_repo failed: {getattr(e, 'detail', None) or e}")


async def _exec_phone_alias(args: dict) -> dict:
    """Phone-alias ops — the host's human-friendly, phone-number-style handle.
    A phone alias is identity-only (kind='phone' in the platform handle
    registry); it is NOT telephony and NOT public DNS. The bridge fixes
    entity_id from the mTLS cert, so a host only ever reads/sets its OWN
    alias. op:
      get    → read this host's current alias (no args)
      set    → claim/replace this host's alias (alias required)
      remove → drop this host's alias (no args)
      lookup → resolve a phone number → host identity (display name + uuid),
               NO network endpoint (alias required); learn WHO it is, then
               send a contact request.
    """
    a = args or {}
    op = (a.get("op") or "").strip()
    if op not in {"get", "set", "remove", "lookup"}:
        return _refused("phone_alias: op must be one of get|set|remove|lookup")
    if op in {"set", "lookup"} and not (a.get("alias") or "").strip():
        return _refused(f"phone_alias: '{op}' requires 'alias'")
    try:
        from server.routes import phone_alias as _pa
        if op == "get":
            res = await _pa._bridge("phone.alias.get", {})
        elif op == "set":
            res = await _pa._bridge("phone.alias.set", {"alias": a["alias"].strip()})
        elif op == "remove":
            res = await _pa._bridge("phone.alias.remove", {})
        else:  # lookup
            res = await _pa._bridge("phone.alias.lookup", {"alias": a["alias"].strip()})
        return {"status": "ok", "result": res}
    except Exception as e:
        return _refused_if_caller(e, f"phone_alias failed: {getattr(e, 'detail', None) or e}")


async def _exec_chat_threads(args, *, entity_id: int | None = None, pool=None,
                             session_id: str | None = None,
                             thread_id: str | None = None):
    """The host's window into its own conversation log.

    Companion to `recall`: recall finds WHAT was said (similarity over
    entity_memory); this finds WHERE and lets the host reopen it. Four ops
    over the same source_context substrate the Memory app's Threads lens
    reads (routes/brain.py /threads, /threads/episodes, /chat):

      op='list'      -> every thread {kind, ref, turn_count, memory_count,
                        last_activity}, newest first. A Circles self-thread
                        also carries title / topic / origin from
                        circles_threads, so the host can name it.
      op='episodes'  -> one thread split into conversations by dormancy gap
                        (default 30 min), each with started/ended/count and
                        a preview of its first user message.
      op='read'      -> the turns themselves, chronological: a whole thread
                        window or one episode via since/until.
      op='toc'       -> the knowledge table of contents for ONE thread:
                        episodes, artifacts, the tool trail, related threads,
                        goals open and resolved, the live summary — every
                        item with its row id, so `read` opens any of them.

    ONE WRITE, and it is an EVENT rather than a judgement: a `read` of
    another Circles thread, made from inside a turn that itself has a thread,
    records a circles_thread_links row with reason 'recall'. "Related"
    is computed from those links, so they must come from what happened.
    circles_threads.write_link no-ops when either side is the legacy scope.

    `entity_id` / `pool` / `session_id` come from _execute_meta_tool, which
    has them from the turn (runtime/session.py:5092-5100 passes
    sess.session_id; entity_id is sess.entity["id"]). They fall back to the
    brain_service process globals so an internal caller with no turn behind
    it still works. `thread_id` is the Circles thread the CURRENT turn is in
    (EntitySession.thread_id, parked beside interaction_context); None means
    the legacy scope, and then no link is written.
    """
    a = args or {}
    op = (a.get("op") or "list").strip()
    try:
        from server import brain_service
        if pool is None:
            pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "memory pool not ready"}
        if not entity_id:
            entity_id = brain_service._entity_id
        if not entity_id:
            return {"status": "error", "result": "host id unknown"}
        session_id = session_id or ""

        if op == "list":
            rows = await pool.fetch(
                """
                SELECT metadata->'source_context'->>'kind' AS kind,
                       metadata->'source_context'->>'ref'  AS ref,
                       count(*) FILTER (WHERE memory_type = 'turn')  AS turn_count,
                       count(*) FILTER (WHERE memory_type <> 'turn') AS memory_count,
                       max(created_at) AS last_activity
                  FROM entity_memory
                 WHERE entity_id = $1 AND status = 'active'
                   AND (metadata->'source_context'->>'kind') IS NOT NULL
                 GROUP BY 1, 2
                 ORDER BY max(created_at) DESC
                 LIMIT 50
                """, entity_id)
            out = [
                {"kind": r["kind"], "ref": r["ref"],
                 "turn_count": r["turn_count"], "memory_count": r["memory_count"],
                 "last_activity": r["last_activity"].isoformat() if r["last_activity"] else None}
                for r in rows]
            # Circles self-threads by NAME (thread refs listed). The
            # aggregate above knows a thread only as {kind:'thread', ref:<uuid>}
            # — a uuid the host cannot tell apart from any other. circles_threads
            # holds the title, topic and origin, and its first entry is the
            # legacy app:circles scope ("the original conversation"), which maps
            # onto the {kind:'app', ref:'circles'} row already in the list rather
            # than adding a second entry for the same turns.
            try:
                from mastercode.circles_threads import LEGACY_THREAD_ID, list_threads
                by_ref = {(x["kind"], x["ref"]): x for x in out}
                for t in await list_threads(pool, entity_id):
                    key = (("app", "circles") if t["id"] == LEGACY_THREAD_ID
                           else ("thread", t["id"]))
                    row = by_ref.get(key)
                    if row is None:
                        # A thread with no turns yet is still a place the user
                        # can be sent back to; it simply has nothing in it.
                        row = {"kind": key[0], "ref": key[1], "turn_count": 0,
                               "memory_count": 0, "last_activity": None}
                        out.append(row)
                        by_ref[key] = row
                    row["title"] = t["title"]
                    row["topic"] = t["topic"]
                    row["origin"] = t["origin"]
                    row["parent_thread_id"] = t["parent_thread_id"]
                    row["closed_at"] = t["closed_at"]
            except Exception as _te:  # noqa: BLE001 - names are a bonus, not the list
                log.debug("chat_threads: circles thread names unavailable: %s", _te)
            return {"status": "ok", "result": {"threads": out}}

        kind = (a.get("kind") or "").strip()
        ref = str(a.get("ref") or "").strip()
        # CANONICAL FORM AT THE BOUNDARY. A thread ref is a uuid, and the host
        # types it from wherever it read it — an uppercase or braced spelling
        # is the same thread to Postgres (`$1::uuid` normalises on the way in)
        # and a different string to Python. Every non-SQL comparison below is
        # a string compare: the `read` self-link test (str(thread_id) != ref)
        # would write a thread's link to ITSELF, and the descriptor built from
        # the raw ref (metadata->>'ref' = $n) is a jsonb TEXT match that finds
        # no rows, so a TOC or an episodes call came back empty with the
        # thread listed as its own RELATED. One canonicalisation here fixes
        # every consumer; an unparseable ref is left exactly as typed so the
        # refusals below still describe what the host asked for.
        if kind == "thread" and ref:
            try:
                import uuid as _uuid
                ref = str(_uuid.UUID(ref))
            except (ValueError, AttributeError, TypeError):
                pass

        if op == "toc":
            # The knowledge TOC is a CIRCLES-THREAD view, so it takes a
            # thread id and not any {kind, ref}. kind='thread' + ref is the id;
            # a bare call is the topic this turn is in. There is no original
            # conversation: 'original', 'self' and the
            # legacy app:circles ref are refused with where to look instead,
            # never answered with an empty index. A project or peer ref is
            # refused too — it would be a thread descriptor built from a ref
            # that was never one.
            tid = str(a.get("thread_id") or "").strip()
            if not tid and kind in ("", "thread"):
                tid = ref
            if (kind == "app" and ref in ("", "circles")) or tid.lower() in ("original", "self"):
                return _refused("op='toc': there is no original conversation; every message is "
                    "in a topic. Name one with kind='thread', ref=<its id> (op='list' lists "
                    "them), or leave both out for the topic you are in.")
            if not tid and not kind:
                tid = str(thread_id or "").strip()
                if not tid:
                    return _refused("op='toc': this turn is in no topic. Name one with "
                        "kind='thread', ref=<its id> (op='list' lists them).")
            if kind in ("", "thread") and tid:
                # A thread ref is a uuid. Anything else with kind omitted
                # (e.g. ref='workbench') is a foreign ref, refused like the
                # kinds below rather than answered with an empty index.
                import uuid as _uuid
                try:
                    # Canonical, for the same reason the `ref` above is: this
                    # id becomes the descriptor every TOC lane matches on.
                    tid = str(_uuid.UUID(tid))
                except (ValueError, AttributeError, TypeError):
                    return _refused(f"op='toc' is for Circles threads; ref='{tid}' is not "
                        "a thread id. Use op='list' to find one, or "
                        "op='episodes' / op='read' for other scopes.")
            elif kind not in ("", "thread"):
                # Only a thread (kind='thread' with its id, or the bare call
                # in a topic) has a TOC. Any other kind/ref (a project, a
                # peer, or kind='app' with any other ref such as 'workbench')
                # gets the same structured refusal the project/peer case gets
                # — never a silent fall-through to the legacy scope.
                return _refused(f"op='toc' is for Circles threads; kind='{kind}', "
                    f"ref='{ref}' has no table of contents. Use op='episodes' "
                    "or op='read'.")
            if not tid:
                return _refused("op='toc' needs a topic: kind='thread', ref=<its id> "
                    "(op='list' lists them).")
            from mastercode.knowledge_toc import build_toc
            return {"status": "ok", "result": await build_toc(
                pool, entity_id, tid, session_id=session_id)}

        if not kind or not ref:
            return _refused(f"op='{op}' requires kind + ref (from op='list')")

        if op == "episodes":
            # ONE implementation, shared with the TOC (knowledge_toc.
            # scope_episodes): the host must not get two answers to the same
            # question. The scope clause moved to memory_engine._turn_row_where
            # in the same move — it was hand-written here, and the consolidator's
            # stats and the recall ladder are supposed to share one clause.
            from mastercode.knowledge_toc import scope_episodes
            return {"status": "ok", "result": {"episodes": await scope_episodes(
                pool, entity_id, {"kind": kind, "ref": ref},
                session_id=session_id,
                gap_minutes=a.get("gap_minutes", 30))}}

        if op == "read":
            from datetime import datetime, timezone

            def _ts(v):
                if not v:
                    return None
                try:
                    dt = datetime.fromisoformat(str(v).replace("Z", "+00:00"))
                    return dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)
                except ValueError:
                    return None
            since, until = _ts(a.get("since")), _ts(a.get("until"))
            try:
                limit = max(1, min(120, int(a.get("limit", 40))))
            except (TypeError, ValueError):
                limit = 40
            # The same scope clause op='episodes' uses (knowledge_toc goes
            # through _turn_row_where too), transcript-style (superseded rows
            # included), so a read of an episode's window returns exactly the
            # rows the episode counted — on every kind, including the legacy
            # app_id arm for kind='app' and the source_session arm for
            # kind='session'. A hand-written descriptor match here answered
            # nothing for those two.
            from mastercode.memory_engine import _turn_row_where as _trw
            params = [entity_id]
            where = _trw(params, session_id=session_id or "",
                         source_context={"kind": kind, "ref": ref},
                         live_only=False)
            if since is not None:
                params.append(since)
                where.append(f"created_at >= ${len(params)}")
            if until is not None:
                params.append(until)
                where.append(f"created_at <= ${len(params)}")
            params.append(limit)
            rows = await pool.fetch(
                f"""
                SELECT * FROM (
                    SELECT content, created_at, metadata->>'role' AS role, metadata
                      FROM entity_memory
                     WHERE {' AND '.join(where)}
                     ORDER BY created_at DESC
                     LIMIT ${len(params)}
                ) newest ORDER BY created_at ASC
                """, *params)
            # A read of ANOTHER Circles thread from inside a threaded turn is
            # the link. One row per read, reason 'recall'; write_link
            # no-ops when either side is the legacy scope or when this turn has
            # no thread of its own, which is also the right answer — there is
            # no "from" to record. BOTH sides are canonicalised before the
            # compare: `ref` at the top of this handler, and the turn's own
            # thread_id here — it arrives from the request body
            # (EntitySession.thread_id), so the two spellings can differ
            # without meaning two threads.
            _from = str(thread_id or "")
            try:
                import uuid as _uuid
                _from = str(_uuid.UUID(_from))
            except (ValueError, AttributeError, TypeError):
                pass
            if kind == "thread" and thread_id and _from != ref:
                try:
                    from mastercode.circles_threads import write_link
                    await write_link(pool, entity_id, _from, ref, "recall")
                except Exception as _le:  # noqa: BLE001 - a read never fails on its telemetry
                    log.debug("chat_threads: recall link not written: %s", _le)
            # What the person saw stays the content; a platform notice on a
            # reply (the budget stop line, a stall notice) is named apart in
            # `platform_notice`, so the reader can tell the Host's words from
            # the platform's (memory_engine.host_part).
            from mastercode.memory_engine import host_part as _hp

            def _turn(r):
                _md = r.get("metadata") if hasattr(r, "get") else None
                if isinstance(_md, str):
                    try:
                        _md = json.loads(_md)
                    except ValueError:
                        _md = {}
                _host, _notes = _hp(r["content"] or "", {**(_md or {}), "role": r["role"] or "user"})
                t = {"role": r["role"] or "user", "content": r["content"],
                     "created_at": r["created_at"].isoformat() if r["created_at"] else None}
                if _notes:
                    t["platform_notice"] = _notes
                    t["host_words"] = _host
                return t
            return {"status": "ok", "result": {"turns": [_turn(r) for r in rows]}}

        return _refused(f"unknown op '{op}' (one of: list, episodes, read, toc)")
    except Exception as e:
        return _refused_if_caller(e, f"chat_threads failed: {getattr(e, 'detail', None) or e}")


# memory_curate: everything that needs doing is done in the host turn, and
# memory ops are plain tool calls. The Host
# decides — add, replace a row it holds, or drop one — and the tool does
# exactly that. No model runs here: the add / update / delete classifier this
# used to call (MemoryConsolidator.consolidate_new, on the Memory text role)
# is gone from the turn. What stays is deterministic: system state is refused,
# an exact live duplicate is not stored twice, a row no decision may retire
# (NEVER_SUPERSEDED_TYPES: the transcript, the constitution, what the user
# taught) is left to the user, and only what the plan keeps writing — a
# preference or a relationship note — is written. A `topic` puts the entry in
# its slot (memory_slots): the newest entry of a type, scope and topic is the
# live one, and the older is replaced in the same transaction; op='key' gives a
# held row a topic (a rule the person taught arrives with none).
_CURATE_OPS = ("add", "replace", "drop", "alias", "key")
_CURATE_TYPES = ("preference", "relationship")
_ALIAS_MAX = 300      # migrations/v234 memory_recall_aliases CHECK


async def _exec_memory_alias(a: dict) -> dict:
    """memory_curate op='alias': words recall should have matched, added to one
    live memory (memory_recall_aliases, migrations/v234). Recall's lexical arm
    searches them beside the memory's own text; the memory row is untouched."""
    try:
        target = int(a.get("memory_id"))
    except (TypeError, ValueError):
        return _refused("alias needs memory_id: the #id recall shows")
    from mastercode.runtime.close_turn import _sanitize
    text = _sanitize(str(a.get("content") or ""))
    if not text:
        return _refused("alias needs content: the words recall should find this memory by")
    if len(text) > _ALIAS_MAX:
        return _refused(f"an alias is at most {_ALIAS_MAX} characters; this one is {len(text)}")
    from server import brain_service
    pool = brain_service.get_pool()
    if pool is None:
        return {"status": "error", "result": "memory pool not ready"}
    entity_id = brain_service._entity_id
    held = await pool.fetchrow(_HELD_FOR_REPLACE, target, entity_id)
    if held is None:
        return _refused(f"#{target} is not a live memory on this Host")
    added = await pool.fetchval(
        "INSERT INTO memory_recall_aliases (memory_id, alias_text) VALUES ($1, $2) "
        "ON CONFLICT (memory_id, alias_text) DO NOTHING RETURNING alias_id", target, text)
    return {"status": "ok", "action": "alias", "memory_id": target, "alias": text,
            "added": added is not None,
            "result": (f"#{target} is now found by: {text}" if added is not None
                       else f"#{target} already had that alias")}


def _curate_scope(raw) -> tuple[dict | None, str | None]:
    """memory_curate's optional `scope`: 'global', or '<kind>:<ref>' for a
    project, an app or a thread. (decision, error); (None, None) when not
    given."""
    if raw is None or str(raw).strip() == "":
        return None, None
    text = str(raw).strip()
    if text.lower() == "global":
        return {"kind": "global"}, None
    kind, _, ref = text.partition(":")
    kind = kind.strip().lower()
    if kind not in ("project", "app", "thread") or not ref.strip():
        return None, "scope is 'global' or project:<id>, app:<name>, thread:<id>"
    return {"kind": kind, "ref": ref.strip()}, None


async def _exec_memory_key(a: dict, session_id) -> dict:
    """memory_curate op='key': give a held preference or relationship note a
    topic (memory_slots.key_row). The row is named by memory_id, or by its
    exact words (a rule the person taught this turn is kept word for word
    with no topic). When another live row holds that slot, a rule outranks a
    plain preference, else the newer row stays and the other is retired
    into it."""
    from mastercode.memory_slots import key_row, normalize_topic, topics_in_scope
    topic = normalize_topic(a.get("topic"))
    if topic is None:
        return _refused("key needs topic: a few words naming what the entry is about")
    from server import brain_service
    pool = brain_service.get_pool()
    if pool is None:
        return {"status": "error", "result": "memory pool not ready"}
    entity_id = brain_service._entity_id
    target = None
    try:
        target = int(a.get("memory_id")) if a.get("memory_id") is not None else None
    except (TypeError, ValueError):
        return _refused("memory_id is an integer: the #id recall shows")
    if target is None:
        words = " ".join(str(a.get("content") or "").split())
        if not words:
            return _refused("key needs memory_id, or content: the entry's exact words")
        target = await pool.fetchval(
            "SELECT id FROM entity_memory WHERE entity_id = $1 AND content = $2"
            " AND memory_type IN ('preference', 'relationship')"
            " AND status = 'active' AND t_valid_until IS NULL"
            " ORDER BY (metadata ? 'rule_kind') DESC, created_at DESC, id DESC LIMIT 1",
            entity_id, words)
        if target is None:
            return _refused("no live preference or relationship note has exactly those words")
    from mastercode.memory_engine import session_source_context, turn_from_turns, turn_tokens_now
    from mastercode.memory_consolidation import scope_stamp
    # A retirement the key makes names the turn's message, so it moves with it.
    stamp = scope_stamp(await session_source_context(pool, entity_id, session_id),
                        await turn_from_turns(session_id), turn_tokens_now(session_id))
    res = await key_row(pool, entity_id, int(target), topic, stamp=stamp)
    if res["status"] in ("not_live", "not_slotted"):
        return _refused(f"#{target} is not a live preference or relationship note")
    row = await pool.fetchrow("SELECT memory_type, slot_scope FROM entity_memory WHERE id = $1",
                              int(target))
    listing = await topics_in_scope(pool, entity_id, row["memory_type"], row["slot_scope"]) if row else {}
    out = {"action": "key", "memory_id": int(target), "topic": topic, "status": res["status"],
           "slot": res.get("slot"), "topics_here": listing}
    if res.get("replaced"):
        out["replaced"] = res["replaced"]
    if res.get("replaced_by"):
        out["replaced_by"] = res["replaced_by"]
        out["note"] = (f"#{res['replaced_by']} already holds topic '{topic}' here and stays (a rule "
                       f"outranks a preference; else the newer stays): #{target} is retired into it")
    return {"status": "ok", "result": out}


async def _exec_memory_curate(args, *, session_id=None):
    a = args or {}
    op = str(a.get("op") or "add").strip().lower()
    if op not in _CURATE_OPS:
        return _refused("op is add, replace, drop, alias or key")
    from mastercode.memory_engine import (
        ABOUT_MACHINERY, NEVER_SUPERSEDED_TYPES, is_machinery_memory,
        session_source_context, hidden_lane_turn,
    )
    lane = hidden_lane_turn(session_id)
    if lane:
        return _refused(f"not written: this turn runs as {lane!r} (a replay, an A/B variant or a "
            "scheduled run), which changes nothing in the conversation it runs in")
    if op == "alias":
        return await _exec_memory_alias(a)
    if op == "key":
        try:
            return await _exec_memory_key(a, session_id)
        except Exception as e:
            return _refused_if_caller(e, f"memory_curate failed: {getattr(e, 'detail', None) or e}")
    from mastercode.memory_slots import normalize_topic
    topic = None
    if a.get("topic") is not None and str(a.get("topic")).strip():
        topic = normalize_topic(str(a.get("topic")))
        if topic is None:
            return _refused("topic: a few words naming what the entry is about")
    scope_decision, scope_err = _curate_scope(a.get("scope"))
    if scope_err:
        return _refused(scope_err)
    content = (a.get("content") or "").strip()
    if op != "drop":
        if not content:
            return _refused("content is required to add or replace")
        # The Host says what the row is about before it is kept:
        # required for every write, even though drop needs no such answer.
        if a.get("about") not in ("person", "machinery"):
            return _refused("about is required to add or replace: person or machinery")
        # Machinery is read live, never stored.
        if is_machinery_memory({"about": a.get("about"), "content": content}):
            return _refused("not stored: this describes the state of a system (about="
                f"{ABOUT_MACHINERY!r}). System state is read live, never kept as a "
                "memory. Store what the user said, wanted or decided about it instead.")
        # A curated row rides later prompts: the structural injection screen
        # every such row gets (C9, memory_engine._store_teaching_memory).
        from mastercode.runtime.close_turn import _sanitize
        content = _sanitize(content)
        if not content:
            return _refused("content empty after screening")
    asked_type = str(a.get("memory_type") or "").strip().lower()
    if asked_type and asked_type not in _CURATE_TYPES:
        return _refused(f"memory_type is preference or relationship, not {asked_type!r}: a fact, "
            "decision or summary is not stored; the conversation itself is, and recall finds it")
    target = None
    if op != "add":
        try:
            target = int(a.get("memory_id"))
        except (TypeError, ValueError):
            return _refused(f"{op} needs memory_id: the #id recall shows")
    try:
        from server import brain_service
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "memory pool not ready"}
        entity_id = brain_service._entity_id
        if not entity_id:
            return {"status": "error", "result": "host id unknown"}
        from mastercode.memory_consolidation import MemoryConsolidator, scope_stamp
        cons = MemoryConsolidator(pool)
        # The conversation this turn is in: where a new row is said, and the
        # conversation a retirement or a restatement is recorded against —
        # with the turn's message (memory_engine.turn_from_turns), which the
        # new row names too (_learned_in), so both follow the message when it
        # moves (circles_threads.carry_learned).
        # The turn's token is read here, in the turn's own task, before the
        # write is queued (PII mode lands it in the drain worker).
        from mastercode.memory_engine import turn_from_turns, turn_tokens_now
        _sctx = await session_source_context(pool, entity_id, session_id)
        stamp = scope_stamp(_sctx, await turn_from_turns(session_id), turn_tokens_now(session_id))
        held = None
        if target is not None:
            held = await pool.fetchrow(_HELD_FOR_REPLACE, target, entity_id)
            if held is None:
                return _refused(f"#{target} is not a live memory on this Host")
            if held["memory_type"] == "skill_memory":
                # A skill row the boot pass left where it was (a rule the
                # user taught or you learned is a preference now): an
                # imported skill, a document, a row with no source. It rides
                # in "Things You Were Taught" but is not a rule this tool
                # changes; the person removes it (Memory app: Archive/Delete).
                # The refusal names the next step that works in this turn
                # (measured: five tries at one row before a replacement rule
                # was added with op='add').
                return _refused(f"#{target} is a stored skill (skill_memory), not a rule the user taught "
                    "or you learned, so memory_curate cannot change or drop it. If it is "
                    "wrong, add the corrected rule yourself now: memory_curate op='add', "
                    f"about='person', content saying it replaces #{target}. Removing the old "
                    f"row is the user's: raise it with them through escalate, naming #{target}; "
                    "they remove it in the Memory app (filter to skill_memory, open the "
                    "row, and choose Archive or Delete).")
            if held["memory_type"] in NEVER_SUPERSEDED_TYPES:
                return _refused(f"#{target} is a {held['memory_type']} row, which no memory op retires; "
                    "the user can archive or correct it in the Memory app")
        async def _write(text: str) -> dict:
            if op == "drop":
                done = await cons._supersede(entity_id, target, None, superseded_in=stamp)
                res: dict = {"action": "drop", "memory_id": target, "dropped": bool(done)}
            elif op == "replace":
                res = await _curate_replace(pool, cons, entity_id, target, text,
                                            asked_type, _sctx, stamp, session_id, topic=topic)
            else:
                res = await _curate_add(pool, cons, entity_id, text, asked_type or "preference",
                                        _sctx, stamp, session_id, topic=topic,
                                        scope_decision=scope_decision)
            # The thread deleted while this ran (or before a queued write
            # landed): what it wrote or retired here goes with the rest of it,
            # whichever path wrote it.
            if not res.get("error") and (_sctx or {}).get("kind") == "thread":
                from mastercode.circles_threads import forget_if_deleted
                if await forget_if_deleted(pool, entity_id, _sctx):
                    res["thread_deleted"] = True
            return res

        from mastercode import pii_queue as _pii
        if op != "drop" and _pii.enabled():
            # PII mode keeps no model-written text as written: the words go
            # through the PII queue and the same write runs on the tokenized
            # text when it drains (as close_turn's writes and turn rows do).
            # Every check that does not need the tokenized words runs now, so
            # the call never answers 'queued' for a write the drain refuses.
            if op == "replace":
                problem = _replace_problem(held, asked_type, content)
                if problem:
                    return _refused(problem)
            await _pii.submit(content, f"entity:{entity_id}:memory", _write, verify=True,
                              pool=pool, entity_id=entity_id)
            return {"status": "ok", "result": {"action": op, "queued": True}}
        out = await _write(content)
        if out.get("error"):
            return {"status": "error", "result": out["error"]}
        # Write→retrievable probe: a stored
        # memory must be reachable through the canonical recall filters NOW —
        # the result says so either way, loudly.
        if out.get("new"):
            from mastercode.memory_retrieval import verify_retrievable
            out["retrievable"] = await verify_retrievable(pool, entity_id, out["memory_id"])
        if out.get("memory_id") and op != "drop":
            # The topics already in use where it was written, and the rows
            # there with none: the Host reuses a topic instead of coining a
            # near twin, and can key or drop an old row (memory_slots).
            from mastercode.memory_slots import topics_in_scope
            _row = await pool.fetchrow(
                "SELECT memory_type, slot_scope, slot_topic FROM entity_memory WHERE id = $1 AND entity_id = $2",
                int(out["memory_id"]), entity_id)
            if _row is not None and _row["memory_type"] in ("preference", "relationship"):
                out.setdefault("topic", _row["slot_topic"])
                out["topics_here"] = await topics_in_scope(pool, entity_id, _row["memory_type"],
                                                           _row["slot_scope"])
                if not _row["slot_topic"]:
                    out["note"] = ("kept with no topic: it rides beside any other entry about the "
                                   "same thing until it has one (op='key')")
        return {"status": "ok", "result": out}
    except Exception as e:
        return _refused_if_caller(e, f"memory_curate failed: {getattr(e, 'detail', None) or e}")


async def _curate_slot_scope(pool, entity_id, memory_type, topic, sctx, decision) -> tuple[str, dict | None, str | None]:
    """(slot scope, the decision to store as metadata.about, error) for a
    curate add with a topic. A relationship note is read everywhere. An
    explicit `scope` is the Host's decision, checked like memory_scope's.
    Otherwise the topic's own live slot where this conversation reads it
    (this conversation's place first, then global): a correction by topic
    replaces what it corrects instead of starting a narrower twin. Else
    where it is said, undecided, as an add without a topic is."""
    from mastercode.memory_slots import slot_scope_for
    if memory_type == "relationship":
        return "global", None, None
    if isinstance(decision, dict):
        if decision.get("kind") == "global":
            return "global", {"kind": "global"}, None
        ref, why = await _memory_scope_ref(pool, entity_id, decision["kind"], str(decision.get("ref") or ""))
        if why:
            return "", None, why
        about = {"kind": decision["kind"], "ref": ref}
        return slot_scope_for(memory_type, {"about": about}), about, None
    here = slot_scope_for(memory_type, {"source_context": sctx} if isinstance(sctx, dict) else {})
    for sc in ([here, "global"] if here != "global" else ["global"]):
        if await pool.fetchval(
                "SELECT 1 FROM entity_memory WHERE entity_id = $1 AND memory_type = $2"
                " AND slot_scope = $3 AND slot_topic = $4 AND status = 'active' AND t_valid_until IS NULL",
                entity_id, memory_type, sc, topic):
            if sc == "global":
                return "global", {"kind": "global"}, None
            kind, _, ref = sc.partition(":")
            return sc, {"kind": kind, "ref": ref}, None
    return here, None, None


async def _curate_add(pool, cons, entity_id, content, memory_type, sctx, stamp, session_id, *,
                      topic=None, scope_decision=None) -> dict:
    """The same words held already: 'already held' only when this
    conversation reads the row (close_turn._held_row, recall's own reading),
    and this conversation is recorded on it (close_turn.held_already).
    Otherwise a row nobody has scoped is recorded as said here too (note_held),
    which makes it read here; a row decided for another place is left to
    that place, and this conversation gets a row of its own.

    With a `topic` the entry goes into its slot (memory_slots.write_in_slot):
    the newer entry of the same type, scope and topic replaces the older in
    the same transaction; a rule the person taught holds its slot against a
    plain preference. The words already held with no topic where this
    conversation reads them are keyed instead of written twice."""
    from mastercode.memory_engine import SCOPE_EVERYWHERE_TYPES
    from mastercode.runtime.close_turn import _GLOBAL, held_already
    if topic:
        return await _curate_add_slot(pool, cons, entity_id, content, memory_type, sctx, stamp,
                                      session_id, topic, scope_decision)
    rows = await pool.fetch(
        "SELECT id, metadata->'about' AS about, metadata->'source_context' AS sc, "
        "metadata->'held_in' AS held_in, metadata ? 'about' AS has_about, "
        "metadata ? 'source_context' AS has_sc, "
        "COALESCE(metadata ? 'rule_kind', false) AS is_rule FROM entity_memory "
        "WHERE entity_id = $1 AND memory_type = $2 AND content = $3 "
        "AND status = 'active' AND t_valid_until IS NULL ORDER BY id DESC",
        entity_id, memory_type, content)
    here = ({"kind": str(sctx["kind"]), "ref": str(sctx.get("ref") or "")}
            if isinstance(sctx, dict) and sctx.get("kind") else dict(_GLOBAL))
    # Held already where this conversation reads it: recorded as said here
    # too, by the one step close_turn takes (held_already).
    rid = await held_already(cons, entity_id, rows, here, stamp,
                             everywhere=memory_type in SCOPE_EVERYWHERE_TYPES)
    if rid is not None:
        return {"action": "already_held", "memory_id": rid}
    for r in rows or []:
        if not r["has_about"] and await cons.note_held(entity_id, int(r["id"]), stamp):
            return {"action": "already_held", "memory_id": int(r["id"]), "now_read_here": True}
    from mastercode.memory_engine import _get_memory_embedding, classify_visibility
    meta: dict = {"written_by": "memory_curate", **_learned_in(stamp)}
    if sctx:
        meta["source_context"] = sctx
    if isinstance(scope_decision, dict) and memory_type not in SCOPE_EVERYWHERE_TYPES:
        _sd, _why = await _decided_about(pool, entity_id, scope_decision, decided_in=stamp)
        if _why:
            return {"error": _why}
        meta.update(_sd)
    mid = int(await cons._insert_new_memory(
        entity_id, content, memory_type, 1.0, await _get_memory_embedding(content),
        None, None, source_session=str(session_id) if session_id else None,
        confidence=1.0, visibility=classify_visibility(content), metadata_extra=meta))
    return {"action": "add", "memory_id": mid, "new": True}


def _learned_in(stamp) -> dict:
    """{'from_turns': [...], 'from_turn_tokens': [...]} naming the turn a
    curated row was learned in (the stamp's, scope_stamp: its message row
    when known, and its token), or {} when no turn is known."""
    from mastercode.memory_consolidation import turn_marks
    return turn_marks(stamp)


async def _decided_about(pool, entity_id, decision: dict, *,
                         decided_in: dict | None = None) -> tuple[dict, str | None]:
    """metadata for a scope the Host decided in the call (`scope`): about,
    scoped_by, scoped_at, and the turn that decided it (scoped_in, the
    stamp: circles_threads.carry_learned); or an error when it names nothing
    this Host has."""
    from datetime import datetime as _dt, timezone as _tz
    if decision.get("kind") == "global":
        about = {"kind": "global"}
    else:
        ref, why = await _memory_scope_ref(pool, entity_id, decision["kind"], str(decision.get("ref") or ""))
        if why:
            return {}, why
        about = {"kind": decision["kind"], "ref": ref}
    return {"about": about, "scoped_by": "host", "scoped_at": _dt.now(_tz.utc).isoformat(),
            "scoped_in": decided_in}, None


async def _curate_add_slot(pool, cons, entity_id, content, memory_type, sctx, stamp, session_id,
                           topic, scope_decision) -> dict:
    """memory_curate op='add' with a topic: the entry goes into its slot."""
    from mastercode.memory_engine import _get_memory_embedding, classify_visibility
    from mastercode.memory_slots import key_row, write_in_slot
    scope, about, why = await _curate_slot_scope(pool, entity_id, memory_type, topic, sctx, scope_decision)
    if why:
        return {"error": why}
    # The same words, live in this scope with no topic: a restatement, so
    # that row takes the slot rather than a second copy beside it.
    same = await pool.fetchval(
        "SELECT id FROM entity_memory WHERE entity_id = $1 AND memory_type = $2 AND content = $3"
        " AND slot_scope = $4 AND slot_topic IS NULL AND status = 'active' AND t_valid_until IS NULL"
        " ORDER BY id DESC LIMIT 1", entity_id, memory_type, content, scope)
    if same is not None:
        res = await key_row(pool, entity_id, int(same), topic, restated=True, stamp=stamp)
        await cons.note_held(entity_id, int(same), stamp)
        out = {"action": "already_held", "memory_id": int(same), "topic": topic}
        if res.get("replaced"):
            out["replaced"] = res["replaced"]
        return out
    meta: dict = {"written_by": "memory_curate", **_learned_in(stamp)}
    if sctx:
        meta["source_context"] = sctx
    if about is not None:
        from datetime import datetime as _dt, timezone as _tz
        meta.update({"about": about, "scoped_by": "host", "scoped_at": _dt.now(_tz.utc).isoformat(),
                     "scoped_in": stamp})
    from mastercode.memory_engine import turn_type_now
    res = await write_in_slot(
        pool, entity_id, content=content, memory_type=memory_type, scope=scope, topic=topic,
        metadata=meta, embedding=await _get_memory_embedding(content),
        source_session=str(session_id) if session_id else None,
        visibility=classify_visibility(content), stamp=stamp, turn_type=turn_type_now(session_id))
    if res["status"] == "already_held":
        await cons.note_held(entity_id, res["id"], stamp)
        return {"action": "already_held", "memory_id": res["id"], "topic": topic}
    if res["status"] == "held_by_rule":
        return {"error": (f"rule #{res['id']} holds topic '{topic}' here: what the person taught "
                          "outranks an inferred preference, so nothing was stored. If they "
                          f"changed it, correct the rule: op='replace' memory_id={res['id']}")}
    out = {"action": "add", "memory_id": res["id"], "new": True, "topic": topic}
    if res.get("replaced"):
        out["replaced"] = res["replaced"][0] if len(res["replaced"]) == 1 else res["replaced"]
    return out


def _correction_scope(held) -> tuple[dict | None, str | None]:
    """(what the correction is ABOUT, or an error). A correction is a row
    said in the conversation that makes it — so deleting that conversation
    takes it back and brings the corrected row back (circles_threads) — and
    it must be read exactly where the corrected row was. A decision is
    copied. A row nobody scoped is read where it was said: everywhere (no
    place) becomes global, one place becomes a decision for that place, and
    several places cannot be one decision — the Host scopes it first. A
    relationship note is read everywhere whatever its scope: none needed."""
    from mastercode.memory_engine import SCOPE_EVERYWHERE_TYPES
    from mastercode.runtime.close_turn import _held_row, _GLOBAL
    if held["memory_type"] in SCOPE_EVERYWHERE_TYPES:
        return None, None
    _rid, about, reach = _held_row(held)
    if held["has_about"]:
        return (about if isinstance(about, dict) else {}), None
    if _GLOBAL in reach:
        return dict(_GLOBAL), None
    if len(reach) == 1:
        return dict(reach[0]), None
    return None, (f"#{held['id']} is read in {len(reach)} conversations and nobody has set what it is "
                  "about; set its scope with memory_scope first, then correct it")


def _replace_problem(held, asked_type, content) -> str | None:
    """Why a replace of `held` cannot be done, before any write (and before a
    PII-mode replace is queued), else None."""
    if held["memory_type"] not in _CURATE_TYPES:
        return (f"#{held['id']} is a {held['memory_type']} row: replace corrects a preference "
                "or a relationship note. Drop it, and add what the user wants instead")
    if asked_type and asked_type != held["memory_type"]:
        return (f"#{held['id']} is a {held['memory_type']}; replace keeps its type "
                "(drop it and add a new row to change the type)")
    if content != (held["content"] or "").strip():
        return _correction_scope(held)[1]
    return None


_HELD_FOR_REPLACE = (
    "SELECT id, memory_type, content, importance, confidence, visibility, project_id, metadata, "
    "metadata->'about' AS about, metadata->'source_context' AS sc, metadata->'held_in' AS held_in, "
    "metadata ? 'about' AS has_about, metadata ? 'source_context' AS has_sc, "
    "COALESCE(metadata ? 'rule_kind', false) AS is_rule "
    "FROM entity_memory WHERE id = $1 AND entity_id = $2 AND status = 'active' AND t_valid_until IS NULL")


async def _curate_replace(pool, cons, entity_id, target, content, asked_type, sctx,
                          stamp, session_id, *, topic=None) -> dict:
    """A correction of one row. The held row is read again here (a PII-mode
    write lands when the queue drains). The new row keeps the held row's
    type, project, share scope and weight, carries what the held row is
    read under (_correction_scope), and is said HERE (source_context), so a
    delete of this conversation undoes the correction; the old row is retired
    into it with this conversation's stamp. A rule stays a rule
    (memory_engine.RULE_KINDS; corrected in the open, never by an automatic
    path): the new row keeps `rule_kind`, and the held words
    already stored count only when they are a rule too."""
    held = await pool.fetchrow(_HELD_FOR_REPLACE, target, entity_id)
    if held is None:
        return {"error": f"#{target} is not a live memory on this Host"}
    problem = _replace_problem(held, asked_type, content)
    if problem:
        return {"error": problem}
    if content == (held["content"] or "").strip():
        return {"action": "already_held", "memory_id": target}
    from mastercode.runtime.close_turn import _covers
    from mastercode.memory_engine import is_rule, rule_row_sql
    held_rule = is_rule(held["memory_type"], held["metadata"])
    old = held["metadata"]
    if isinstance(old, str):
        try:
            old = json.loads(old)
        except (TypeError, ValueError):
            old = {}
    old = dict(old or {})
    # Where the person taught the rule (memory_engine.rule_taught_places): a
    # correction keeps every such place — the replacement carries them, and
    # a rule the corrected words already are takes them on — so it rides
    # wherever the corrected rule did (rule_reach).
    taught = ([e for e in old.get("held_in") or [] if isinstance(e, dict) and e.get("taught")]
              if held_rule else [])
    dup = await pool.fetchval(
        "SELECT id FROM entity_memory WHERE entity_id = $1 AND memory_type = $2 AND content = $3 "
        "AND status = 'active' AND t_valid_until IS NULL AND id <> $4 "
        + (f"AND {rule_row_sql()} " if held_rule else "")
        + "ORDER BY id DESC LIMIT 1",
        entity_id, held["memory_type"], content, target)
    if dup is not None and await _absorbs(pool, entity_id, int(dup), target, taught):
        # The corrected words are held already, everywhere the old row was
        # read: retire the old row into that one.
        # A rule taking another in keeps its own reach (rule_reach); carrying
        # the corrected rule's decision onto it could only narrow it.
        done = await cons._supersede(entity_id, target, int(dup), superseded_in=stamp,
                                     carry_about=not held_rule)
        out = {"action": "replace", "memory_id": int(dup), "replaced": target if done else None}
        return await _with_taught_places(pool, entity_id, int(dup), out)
    about, _err = _correction_scope(held)
    from datetime import datetime as _dt, timezone as _tz
    meta: dict = {"edited_from": target, "written_by": "memory_curate", **_learned_in(stamp)}
    if held_rule and "rule_kind" in old:
        meta["rule_kind"] = old["rule_kind"]
    if sctx:
        meta["source_context"] = sctx
    if old.get("share_scope") is not None:
        meta["share_scope"] = old["share_scope"]
    if about is not None:
        meta["about"] = about
        if held["has_about"]:
            for k in ("scoped_by", "scoped_at", "scoped_in", "scope_history"):
                if k in old:
                    meta[k] = old[k]
        else:
            meta.update({"scoped_by": "memory_curate", "scoped_at": _dt.now(_tz.utc).isoformat(),
                         "scoped_in": stamp})
    if taught:
        meta["held_in"] = [dict(e) for e in taught]
    from mastercode.memory_engine import _get_memory_embedding
    held_topic = await pool.fetchval("SELECT slot_topic FROM entity_memory WHERE id = $1", target)
    if topic or held_topic:
        # The correction takes the slot: the held row and anything else in
        # the slot are retired into it in one transaction (memory_slots).
        from mastercode.memory_slots import slot_scope_for, write_in_slot
        res = await write_in_slot(
            pool, entity_id, content=content, memory_type=held["memory_type"],
            scope=slot_scope_for(held["memory_type"], meta), topic=topic or held_topic,
            metadata={**meta, "supersedes_id": target}, importance=float(held["importance"] or 1.0),
            confidence=float(held["confidence"] or 1.0), visibility=held["visibility"] or "default",
            embedding=await _get_memory_embedding(content),
            source_session=str(session_id) if session_id else None, stamp=stamp,
            rule=held_rule, also_retire=(target,), project_id=held["project_id"],
            turn_type=__import__("mastercode.memory_engine", fromlist=["turn_type_now"]).turn_type_now(session_id))
        if res["status"] == "held_by_rule":
            return {"error": (f"rule #{res['id']} holds topic '{topic or held_topic}' there; a plain "
                              f"preference never replaces it. Correct the rule: op='replace' "
                              f"memory_id={res['id']}")}
        if res["status"] == "already_held":
            return {"action": "already_held", "memory_id": res["id"]}
        out = {"action": "replace", "memory_id": res["id"],
               "replaced": target if target in res["replaced"] else None, "new": True,
               "topic": topic or held_topic}
        return await _with_taught_places(pool, entity_id, res["id"], out)
    mid = int(await cons._insert_new_memory(
        entity_id, content, held["memory_type"], float(held["importance"] or 1.0),
        await _get_memory_embedding(content), None, target,
        source_session=str(session_id) if session_id else None,
        confidence=float(held["confidence"] or 1.0), visibility=held["visibility"] or "default",
        metadata_extra=meta))
    # The project tag too, NULL included: a typed turn reads a row by it.
    await pool.execute("UPDATE entity_memory SET project_id = $1 WHERE id = $2 AND entity_id = $3",
                       held["project_id"], mid, entity_id)
    done = await cons._supersede(entity_id, target, mid, superseded_in=stamp)
    out = {"action": "replace", "memory_id": mid, "replaced": target if done else None, "new": True}
    return await _with_taught_places(pool, entity_id, mid, out)


class _NotAbsorbed(Exception):
    pass


async def _absorbs(pool, entity_id: int, dup: int, target: int, taught: list) -> bool:
    """Whether the row the corrected words already are takes the corrected
    row in: it is read in every turn the corrected row was (close_turn.
    _covers, over each one's reach — memory_engine.rule_reach for a rule).
    A rule first takes the corrected rule's taught places (they are where the
    person taught these words' predecessor); if it still does not cover, that
    is undone and the correction gets a row of its own."""
    from mastercode.runtime.close_turn import _covers
    if not taught:
        return await _covers(pool, entity_id, dup, target)
    try:
        async with pool.acquire() as conn:
            async with conn.transaction():
                cur = await conn.fetchval(
                    "SELECT metadata->'held_in' FROM entity_memory WHERE id = $1 AND entity_id = $2 "
                    "FOR UPDATE", dup, entity_id)
                cur = _json(cur) if cur is not None else []
                entries = [e for e in (cur if isinstance(cur, list) else []) if isinstance(e, dict)]
                for t in taught:
                    same = next((e for e in entries if e.get("kind") == t.get("kind")
                                 and str(e.get("ref") or "") == str(t.get("ref") or "")
                                 and not e.get("words") and "about" not in e), None)
                    if same is not None:
                        same["taught"] = True
                    else:
                        entries.append(dict(t))
                await conn.execute(
                    "UPDATE entity_memory SET metadata = jsonb_set(COALESCE(metadata, '{}'::jsonb), "
                    "'{held_in}', $3::jsonb), updated_at = NOW() WHERE id = $1 AND entity_id = $2",
                    dup, entity_id, json.dumps(entries))
                if not await _covers(conn, entity_id, dup, target):
                    raise _NotAbsorbed()
        return True
    except _NotAbsorbed:
        return False


async def _with_taught_places(pool, entity_id: int, mid: int, out: dict) -> dict:
    """The replace result names the places the rule is still read in because
    the person taught it there, beside its decided place — as memory_scope's
    does (memory_engine.rule_reach)."""
    from mastercode.memory_engine import rule_reach
    md = _json(await pool.fetchval("SELECT metadata FROM entity_memory WHERE id = $1 AND entity_id = $2",
                                   mid, entity_id))
    if not (isinstance(md, dict) and "rule_kind" in md):
        return out
    everywhere, places = rule_reach(md)
    about = md.get("about") if isinstance(md.get("about"), dict) else None
    kept = [p for p in places if not (about and p == {"kind": str(about.get("kind")),
                                                      "ref": str(about.get("ref") or "")})]
    if not everywhere and kept:
        names = await _memory_scope_names(pool, entity_id)
        out["still_read_where_taught"] = [_scope_label(p, names) for p in kept]
    return out


# Where a preference may ride: what is relevant in one place is a leak in
# another. A preference is volunteered only in its own scope — a
# project, an app, a thread — or anywhere it is relevant when it is global (no
# scope). Its scope is set by what it is ABOUT, not where it happened to be
# said: "prefers metric units" is about the person; "keep credit cards
# out of general bills" is about the finance app.
_MEMORY_SCOPE_KINDS = ("global", "project", "app", "thread")
_MEMORY_SCOPABLE_TYPES = ("preference",)
_SCOPE_HISTORY_KEEP = 20


def _scope_label(sc, names) -> str:
    if not isinstance(sc, dict) or not sc.get("kind") or sc.get("kind") == "global":
        return "global"
    label = f"{sc.get('kind')}:{sc.get('ref')}"
    name = names.get((str(sc.get("kind")), str(sc.get("ref"))))
    return f"{label} ({name})" if name else label


async def _memory_scope_names(pool, entity_id) -> dict:
    """(kind, ref) -> a readable name, for the projects and threads a scope can name.
    A deleted thread is no turn's place, so it is named "deleted", never by its
    old title: a decision naming it must not read as a live thread."""
    names: dict = {}
    for r in await pool.fetch("SELECT id, name FROM projects WHERE entity_id = $1", entity_id):
        names[("project", str(r["id"]))] = r["name"]
    for r in await pool.fetch(
            "SELECT id, COALESCE(NULLIF(title, ''), topic) AS name, deleted_at IS NOT NULL AS gone "
            "FROM circles_threads WHERE entity_id = $1", entity_id):
        if r["gone"]:
            names[("thread", str(r["id"]))] = "deleted"
        elif r["name"]:
            names[("thread", str(r["id"]))] = r["name"]
    return names


def _json(v):
    if isinstance(v, str):
        try:
            return json.loads(v)
        except (TypeError, ValueError):
            return None
    return v


def _taught_places(meta, but=None) -> list[dict]:
    """The places a rule rides in because the person taught it there, beside
    its decided place `but` (the one it is, or is being, narrowed to): its
    reach (memory_engine.rule_reach) less that place. Nothing when it rides
    everywhere."""
    from mastercode.memory_engine import rule_reach
    md = dict(meta or {}) if isinstance(meta, dict) else {}
    if but is not None:
        md["about"] = but
    everywhere, places = rule_reach(md)
    return [] if everywhere else [p for p in places if p != but]


async def _memory_scope_list(pool, entity_id) -> dict:
    """Every live preference of this Host with its id, grouped by the scope it
    is read in. A group marked "where said" holds preferences whose scope
    nobody has set yet: they ride where they were said until you set it. A
    rule (memory_engine.RULE_KINDS) is marked [rule]; one nobody has scoped
    is read everywhere ("Things You Were Taught"), so it is listed so. A
    plain preference in a rule's own words is marked [held by rule #N]: kept
    live where the rule is not read (a project-scoped type's turns), it never
    renders beside that rule in a turn (memory_engine.same_words_key). A rule
    narrowed to a place names the places it is still read in because the
    person taught it there: [rule; also where taught: …]."""
    from mastercode.memory_engine import rules_holding, same_words_key
    held_by = await rules_holding(pool, entity_id)
    rows = await pool.fetch(
        "SELECT id, content, metadata->'about' AS about, metadata->'source_context' AS sc, "
        "metadata->>'rule_kind' AS rule_kind, metadata->'held_in' AS held_in "
        "FROM entity_memory WHERE entity_id = $1 AND memory_type = ANY($2::text[]) "
        "AND status = 'active' AND t_valid_until IS NULL ORDER BY id",
        entity_id, list(_MEMORY_SCOPABLE_TYPES))
    names = await _memory_scope_names(pool, entity_id)
    groups: dict = {}
    rules = 0
    for r in rows:
        about = _json(r["about"])
        rule = r["rule_kind"] is not None
        rules += rule
        if isinstance(about, dict):
            key = _scope_label(about, names)
        elif rule:
            key = "everywhere [rules nobody has scoped]"
        else:
            key = f"{_scope_label(_json(r['sc']), names)} [where said]"
        text = " ".join((r["content"] or "").split())
        holder = None if rule else held_by.get(same_words_key(r["content"]))
        kept = (_taught_places({"held_in": _json(r["held_in"]) if "held_in" in r.keys() else None},
                               but={"kind": str(about.get("kind")), "ref": str(about.get("ref") or "")})
                if rule and isinstance(about, dict) and about.get("kind") != "global" else [])
        mark = ((f"[rule; also where taught: {', '.join(_scope_label(p, names) for p in kept)}] "
                 if kept else "[rule] ") if rule
                else (f"[held by rule #{holder}] " if holder else ""))
        groups.setdefault(key, []).append(
            f"#{r['id']} {mark}{text[:200]}{'…' if len(text) > 200 else ''}")
    return {"status": "ok", "result": {"preferences": len(rows), "rules": rules,
                                       "by_scope": groups}}


async def _memory_scope_ref(pool, entity_id, kind, ref):
    """(the ref as turns carry it, None) when it names something this Host
    has, else (None, why not). A scope that names nothing would hide the
    preference from every turn."""
    if kind == "project":
        if not ref.isdigit():
            return None, f"a project ref is the project's id, got {ref!r}"
        ref = str(int(ref))
        if not await pool.fetchval(
                "SELECT 1 FROM projects WHERE id = $1 AND entity_id = $2", int(ref), entity_id):
            return None, f"no project {ref} on this Host"
    elif kind == "thread":
        import uuid as _uuid
        try:
            ref = str(_uuid.UUID(ref))
        except ValueError:
            return None, f"a thread ref is the thread's id, got {ref!r}"
        if not await pool.fetchval(
                "SELECT 1 FROM circles_threads WHERE id = $1::uuid AND entity_id = $2 "
                "AND deleted_at IS NULL", ref, entity_id):
            return None, f"no live thread {ref} on this Host"
    elif kind == "app":
        # Stored exactly as the turns carry it (derive_source_context keeps
        # the case it was given), matched without regard to case.
        apps = [r["ref"] for r in await pool.fetch(
            "SELECT DISTINCT metadata->'source_context'->>'ref' AS ref FROM entity_memory "
            "WHERE entity_id = $1 AND memory_type = 'turn' "
            "AND metadata->'source_context'->>'kind' = 'app'", entity_id) if r["ref"]]
        match = next((x for x in apps if x.lower() == ref.lower()), None)
        if match is None:
            return None, f"no turns ever ran in app {ref!r}; apps with turns: {sorted(apps)}"
        ref = match
    return ref, None


async def apply_memory_scope(pool, entity_id: int, memory_id: int, kind: str, ref: str, *,
                             decided_in: dict | None = None) -> dict:
    """Set what one live preference is ABOUT (metadata.about) — the one writer
    of that decision, for memory_scope and close_turn alike. Where it was
    said (source_context, project_id) is provenance and is never changed.
    `decided_in` is the turn that decided it (scope_stamp: its conversation,
    its message row and its token), kept as metadata.scoped_in: a decision
    for "this conversation" made in a turn that later moves follows the turn
    (circles_threads.carry_learned). None (a decision no turn made) clears
    an earlier one's. Returns the tool-result shape; raises only on a
    database error."""
    row = await pool.fetchrow(
        "SELECT id, memory_type, status, t_valid_until, metadata, slot_topic FROM entity_memory "
        "WHERE id = $1 AND entity_id = $2", memory_id, entity_id)
    if not row:
        return _refused(f"memory {memory_id} not found")
    if row["memory_type"] not in _MEMORY_SCOPABLE_TYPES:
        return _refused(f"memory {memory_id} is a {row['memory_type']!r}; only "
            f"{list(_MEMORY_SCOPABLE_TYPES)} are scoped this way")
    if row["status"] != "active" or row["t_valid_until"] is not None:
        return _refused(f"memory {memory_id} is not live (replaced or archived); "
            "kind='list' shows the live ones")
    new_about = {"kind": "global"}
    if kind != "global":
        ref, why = await _memory_scope_ref(pool, entity_id, kind, ref)
        if why:
            return _refused(why)
        new_about = {"kind": kind, "ref": ref}
    meta = _json(row["metadata"])
    meta = meta if isinstance(meta, dict) else {}
    prior = meta.get("about") if isinstance(meta.get("about"), dict) else None
    if prior == new_about:
        return {"status": "ok", "result": {"memory_id": memory_id, "unchanged": new_about}}
    from datetime import datetime as _dt, timezone as _tz
    now = _dt.now(_tz.utc).isoformat()
    history = [h for h in (meta.get("scope_history") or []) if isinstance(h, dict)]
    # Undecided, a row rides where it was said — a rule, everywhere.
    undecided = "everywhere" if "rule_kind" in meta else "where said"
    history = (history + [{"from": prior or undecided, "at": now}])[-_SCOPE_HISTORY_KEEP:]
    patch = {"about": new_about, "scoped_by": "host", "scoped_at": now,
             "scoped_in": decided_in if isinstance(decided_in, dict) else None,
             "scope_history": history}
    # A thread scope is written only while the thread is live, checked
    # under a share lock in the same statement: a delete in flight
    # finishes first (and its forget drops this decision), or waits for it.
    # The row's slot_scope follows its new scope in the same statement; a row
    # with a topic moves to that topic's slot there in the same transaction
    # (memory_slots.move_scope), settled by the slot rule when another row
    # holds it.
    from mastercode.memory_slots import move_scope, slot_scope_for
    new_scope = slot_scope_for(row["memory_type"], {**meta, **patch})
    sql = ("UPDATE entity_memory SET metadata = COALESCE(metadata, '{}'::jsonb) || $3::jsonb, "
           "slot_scope = CASE WHEN slot_topic IS NULL THEN $5 ELSE slot_scope END, "
           "updated_at = NOW() WHERE id = $1 AND entity_id = $2 AND ($4::text IS NULL OR EXISTS ("
           "SELECT 1 FROM circles_threads WHERE id = $4::text::uuid AND entity_id = $2 "
           "AND deleted_at IS NULL FOR SHARE))")
    sql_args = (memory_id, entity_id, json.dumps(patch), ref if kind == "thread" else None, new_scope)
    moved = None
    try:
        topic = row["slot_topic"]
    except (KeyError, IndexError):
        topic = None
    if not topic:
        res = await pool.execute(sql, *sql_args)
    else:
        async with pool.acquire() as conn:
            async with conn.transaction():
                res = await conn.execute(sql, *sql_args)
                if not str(res).endswith(" 0"):
                    moved = await move_scope(conn, entity_id, memory_id, new_scope)
    if str(res).endswith(" 0"):
        why = (f"thread {ref} was deleted" if kind == "thread" and not await pool.fetchval(
                   "SELECT 1 FROM circles_threads WHERE id = $1::uuid AND entity_id = $2 "
                   "AND deleted_at IS NULL", ref, entity_id)
               else f"memory {memory_id} changed while this ran")
        return _refused(f"{why}; nothing written")
    result = {"memory_id": memory_id, "from": prior or undecided, "to": new_about}
    if moved and moved.get("replaced"):
        result["replaced"] = moved["replaced"]
    # A rule rides where the person taught it, whatever place it is narrowed
    # to (memory_engine.rule_place_clause): the result names those places.
    kept = (_taught_places(meta, but=new_about)
            if "rule_kind" in meta and new_about.get("kind") != "global" else [])
    if kept:
        names = await _memory_scope_names(pool, entity_id)
        labels = [_scope_label(p, names) for p in kept]
        result["still_read_where_taught"] = labels
        result["note"] = (f"narrowed to {_scope_label(new_about, names)}; still read where the "
                          f"person taught it: {', '.join(labels)}")
    return {"status": "ok", "result": result}


async def _exec_memory_scope(args, *, session_id=None):
    """The memory_scope tool: list the preferences, or set what one is ABOUT
    (apply_memory_scope)."""
    a = args or {}
    kind = str(a.get("kind") or "").strip().lower()
    if kind != "list" and kind not in _MEMORY_SCOPE_KINDS:
        return _refused(f"kind must be 'list' or one of {list(_MEMORY_SCOPE_KINDS)}")
    if kind != "list":
        from mastercode.memory_engine import hidden_lane_turn
        lane = hidden_lane_turn(session_id)
        if lane:
            return _refused(f"not changed: this turn runs as {lane!r} (a replay, an A/B variant or a "
                "scheduled run), which changes nothing in the conversation it runs in")
    memory_id = None
    if kind != "list":
        try:
            memory_id = int(a.get("memory_id"))
        except (TypeError, ValueError):
            return _refused("memory_id (an integer) is required")
    ref = str(a.get("ref") or "").strip()
    if kind in ("project", "app", "thread") and not ref:
        return _refused(f"ref is required for kind {kind!r}")
    try:
        from server import brain_service
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "memory pool not ready"}
        entity_id = brain_service._entity_id
        if kind == "list":
            return await _memory_scope_list(pool, entity_id)
        # The turn deciding it: its conversation, its message and its token.
        from mastercode.memory_consolidation import scope_stamp
        from mastercode.memory_engine import (
            session_source_context, turn_from_turns, turn_tokens_now)
        decided_in = scope_stamp(await session_source_context(pool, entity_id, session_id),
                                 await turn_from_turns(session_id), turn_tokens_now(session_id))
        return await apply_memory_scope(pool, entity_id, memory_id, kind, ref, decided_in=decided_in)
    except Exception as e:
        return _refused_if_caller(e, f"memory_scope failed: {getattr(e, 'detail', None) or e}")


async def _exec_embedding_route(args):
    a = args or {}
    op = (a.get("op") or "get").strip().lower()
    if op == "current":
        op = "get"  # synonym
    # RETIRED OPS. catalog / switch / use_managed all
    # ran through the platform embedding catalog, which serves nothing (the
    # bridge catalog is empty — orchestrator app.yaml 0.7.0, measured). So
    # `switch` refused every model ("not in embedding catalog"),
    # `use_managed` either failed the same way or — had the catalog ever
    # answered — silently re-pointed the host's embeds at platform compute, and
    # `catalog` returned [] that a fresh host read as "the platform's embedding
    # system is down". There is no platform embedder; the honest tool has no op
    # that pretends there is. Refused HERE, before any import or pool, so the
    # answer is the same in every environment and names the real paths.
    if op in ("catalog", "switch", "use_managed"):
        return _refused(f"embedding_route op={op!r} is retired — there is no platform embedder, and this op "
            "consulted a platform catalog that serves nothing. Embeddings run on an endpoint the "
            "user provides: their own machine (op='bastions' → op='use_bastion', pass 'model' to "
            "change the model there) or a provider they hold a key for (the user picks it in "
            "Orchestrator → Memory). A host with no model configured is not broken — it is not "
            "set up yet.")
    # Media ops live on THIS tool rather than a second one: the host
    # should never have to choose between two tools that mean the same thing.
    # `media_*` is the picture role; the bare ops stay the text role.
    if op.startswith("media_"):
        return await _exec_media_embedding_route(op[len("media_"):], a)
    valid = ("get", "dims", "bastions", "use_bastion",
             "media_get", "media_dims", "media_use_provider",
             "media_use_bastion", "media_clear")
    if op not in valid:
        return _refused(f"embedding_route: unknown op {op!r} (use {'|'.join(valid)})")
    try:
        from server import brain_service
        from server.routes import embedding as embedding_routes
        from mastercode import embed_backends
        pool = brain_service.get_pool()
        entity_id = brain_service._entity_id

        if op == "get":
            # current() reads pool/entity_id from brain_service globals itself.
            return {"status": "ok", "result": await embedding_routes.current()}

        if op == "dims":
            # Memory dim availability: which vector dims have a storage column in
            # this host's memory, plus the ACTIVE column/dim the engine writes now.
            # A model whose dim isn't listed here can't be stored (a switch to it
            # would be rejected) — check this before assigning an off-dim model.
            from mastercode.memory_engine import (
                EMBEDDING_COLUMN_BY_DIM, active_embedding_column)
            cur = await embedding_routes.current()
            active_col = active_dim = None
            if pool is not None and entity_id is not None:
                try:
                    active_col, active_dim = await active_embedding_column(pool, entity_id)
                except Exception:
                    pass
            return {"status": "ok", "result": {
                "storable_dims": sorted(EMBEDDING_COLUMN_BY_DIM),
                "columns": {str(d): c for d, c in sorted(EMBEDDING_COLUMN_BY_DIM.items())},
                "current_model": cur.get("model"),
                "current_dim": cur.get("dim"),
                "active_column": active_col,
                "active_dim": active_dim,
            }}

        if op == "bastions":
            # The host's ONLINE bastions that advertise the 'embed' capability —
            # where the user can run LOCAL embeddings (the sovereign lane).
            if pool is None or entity_id is None:
                return {"status": "ok", "result": {"bastions": []}}
            return {"status": "ok", "result": {"bastions": await embed_backends.list_embed_bastions(pool, entity_id)}}

        # op == "use_bastion": set up (or change the model of) embeddings on the
        # user's machine. `model` omitted → keep the current model (just move the
        # lane); given → serve THAT model there (probe-gated: the box must answer
        # for it; still no dump/re-embed). This is the tool's ONLY write.
        server = (a.get("server") or "").strip()
        if not server:
            return _refused("embedding_route use_bastion: 'server' is required (a hostname from op='bastions')")
        if pool is None or entity_id is None:
            return {"status": "error", "result": "embedding_route: brain pool/host id unavailable"}
        _bdim = a.get("dim")
        res = await embed_backends.set_embed_bastion(
            pool, entity_id, server, cred_name=a.get("cred_name"),
            model=(a.get("model") or None),
            dim=int(_bdim) if _bdim else None)
        if isinstance(res, dict) and res.get("error"):
            return {"status": "error", "result": f"embedding_route use_bastion: {res['error']}"}
        return {"status": "ok", "result": res}
    except Exception as e:
        return _refused_if_caller(e, f"embedding_route failed: {getattr(e, 'detail', None) or e}")


async def _exec_media_embedding_route(sub: str, a: dict) -> dict:
    """The `media_*` half of embedding_route: the picture role.

    Same two lanes as text and the same refusal discipline — a switch is
    probe-gated against the user's own endpoint and nothing is persisted that
    was not measured. There is deliberately no catalog op and no default model,
    for the same reason the text tool's catalog op was retired: there is no
    platform embedder to have a catalog OF.
    """
    valid = ("get", "dims", "use_provider", "use_bastion", "clear")
    if sub not in valid:
        return _refused(f"embedding_route: unknown op 'media_{sub}' "
                f"(use {'|'.join('media_' + v for v in valid)})")
    try:
        from server import brain_service
        from server.routes import media_embedding as media_routes
        pool = brain_service.get_pool()
        entity_id = brain_service._entity_id

        if sub == "get":
            return {"status": "ok", "result": await media_routes.current()}
        if sub == "dims":
            return {"status": "ok", "result": await media_routes.dims()}
        if sub == "clear":
            return {"status": "ok", "result": await media_routes.clear()}
        if sub == "use_provider":
            provider = (a.get("provider") or "").strip()
            model = (a.get("model") or "").strip()
            if not provider or not model:
                return _refused("embedding_route media_use_provider: 'provider' and 'model' are both required")
            res = await media_routes.use_provider({"provider": provider, "model": model})
            if isinstance(res, dict) and res.get("error"):
                return {"status": "error", "result": f"embedding_route media_use_provider: {res['error']}"}
            return {"status": "ok", "result": res}

        # sub == "use_bastion": point picture embedding at a model on the user's
        # own machine. The endpoint is resolved LIVE from the box's heartbeat —
        # never a stored address, so a re-enrolled machine self-heals (the same
        # rule the text lane learned the hard way, embed_backends.py:115-124).
        server = (a.get("server") or "").strip()
        model = (a.get("model") or "").strip()
        if not server or not model:
            return _refused("embedding_route media_use_bastion: 'server' and 'model' are both "
                    "required (a hostname from op='bastions', and the picture model it serves)")
        if pool is None or entity_id is None:
            return {"status": "error", "result": "embedding_route: brain pool/host id unavailable"}
        from mastercode.embed_backends import resolve_endpoint_for_hostname
        endpoint = await resolve_endpoint_for_hostname(pool, entity_id, server)
        if not endpoint:
            return {"status": "error", "result":
                    f"embedding_route media_use_bastion: '{server}' has no reachable "
                    f"endpoint in its latest heartbeat"}
        res = await media_routes.apply_media_embedding_switch(
            pool, entity_id, model=model, base_url=endpoint,
            provider="local", bastion=server)
        if isinstance(res, dict) and res.get("error"):
            return {"status": "error", "result": f"embedding_route media_use_bastion: {res['error']}"}
        return {"status": "ok", "result": res}
    except Exception as e:
        return _refused_if_caller(e, f"embedding_route media_{sub} failed: {getattr(e, 'detail', None) or e}")


async def _exec_embed_jobs(args: dict) -> dict:
    """Start a durable background embedding job for one of the host's own
    memory banks. Thin shim over the embed-jobs service (server/routes/embed.py
    ::enqueue_job), the SAME entry point the brain/context routes use to enqueue
    crash-safe, resumable embedding work — never a fire-and-forget asyncio task.

    op='enqueue' (default): queue an embedding job. `target` selects the bank:
      - entity_memory          : first-fill the active dim column for unembedded memories
      - user_context           : first-fill the active dim column for unembedded context
      - entity_memory_reembed  : re-embed memories to a different model (needs metadata.target_model)
      - gitea_repo             : index NOW a repo this host can read on its gitea
                                 (`repo`='owner/name'). Every readable repo is indexed on
                                 its own (codesearch.repo_sync: read access means
                                 it is indexed); this is the same work for one, at once
    The JobRunner claims the row, batches via the bridge, and persists progress
    after every batch. Returns the inserted job row (id/status/total/...).
    """
    a = args or {}
    op = (a.get("op") or "enqueue").strip().lower()

    try:
        from server import brain_service
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "embed_jobs failed: brain not initialized"}
        eid = brain_service._entity_id

        if op == "enqueue":
            target = (a.get("target") or "entity_memory").strip()
            valid_targets = {"entity_memory", "user_context", "user_context_media",
                             "entity_memory_reembed", "gitea_repo"}
            if target not in valid_targets:
                return _refused(f"embed_jobs: unknown target '{target}' (one of {sorted(valid_targets)})")
            metadata = a.get("metadata") or {}
            if not isinstance(metadata, dict):
                return _refused("embed_jobs: metadata must be an object")
            if target == "gitea_repo":
                repo = str(a.get("repo") or metadata.get("repo") or "").strip().strip("/")
                from server.routes.embed import valid_repo_name
                if not valid_repo_name(repo):
                    return _refused("embed_jobs: target gitea_repo needs repo='owner/name' — a repository on "
                            "the forge this host owns or was granted (gitea op='list' shows them)")
                if str(a.get("ref") or metadata.get("ref") or "").strip():
                    return _refused("embed_jobs: the code index follows each repo's default branch; "
                                    "read another branch with gitea op='read' ref=...")
                # Refuse before queueing anything that is not on the forge's
                # own list of what this host can read (gitea op='list'): the
                # job would only fail later, and a foreign repo — another
                # user's that was not granted, even a public one — is never
                # indexed in the pod.
                try:
                    from server.routes.gitea_client import gitea_creds
                    from codesearch import repo_sync
                except Exception as e:  # noqa: BLE001
                    return _refused_if_caller(e, f"gitea client unavailable in this pod: {e}")
                if not gitea_creds():
                    return {"status": "error", "result":
                            "this host has no gitea identity yet (no credential in the pod) — nothing to clone"}
                readable = await repo_sync.readable_repos(also=[repo])
                if readable is None:
                    return {"status": "error", "result":
                            "gitea did not say which repos this host can read; nothing queued — try again"}
                match = next((r for r in readable if r["repo"].lower() == repo.lower()), None)
                if match is None:
                    return _refused(f"{repo!r} is not a repo this host owns or was granted on the forge — "
                                    "it does not exist, or the user has not granted it (Gitea app → "
                                    "Permissions). A foreign repo is never indexed here: dispatch an agent "
                                    "to read it.")
                repo = match["repo"]
                metadata = {**metadata, "repo": repo}
                metadata.pop("ref", None)
                from server.routes.embed import enqueue_job
                try:
                    row = await enqueue_job(entity_id=eid, job_type="repo",
                                            target=target, metadata=metadata, model=a.get("model"))
                except ValueError as e:
                    return _refused(f"embed_jobs: {e}")
                if row is None:
                    return {"status": "error", "result": "embed_jobs failed: brain not ready (enqueue returned none)"}
                return {"status": "ok", "result": {
                    **row,
                    "note": (f"{repo} is being cloned into this pod and indexed; when the job is done, "
                             f"search_my_code finds it (each hit names {repo!r}). It is kept fresh on "
                             "its own after that."),
                }}
            # Re-embed needs the model it's moving TO, both on the row and in metadata
            # so _fetch_batch/_write_embedding select + stamp correctly.
            model = a.get("model")
            if target == "entity_memory_reembed":
                target_model = a.get("target_model") or metadata.get("target_model") or model
                if not target_model:
                    return _refused("embed_jobs: entity_memory_reembed needs target_model (the model to re-embed to)")
                metadata = {**metadata, "target_model": target_model}
                model = model or target_model
            job_type = (a.get("job_type") or
                        ("reembed" if target == "entity_memory_reembed" else "fill")).strip()

            from server.routes.embed import enqueue_job
            row = await enqueue_job(
                entity_id=eid,
                job_type=job_type,
                target=target,
                metadata=metadata,
                model=model,
            )
            if row is None:
                return {"status": "error", "result": "embed_jobs failed: brain not ready (enqueue returned none)"}
            return {"status": "ok", "result": row}

        if op == "coverage":
            # Identify unindexed rows: both-bank {total,embedded,missing} vs the
            # ACTIVE column + per-model readiness. Read-only — the numbers a fill
            # job acts on, so the host can see the gap before/after enqueuing.
            from server.routes import embed as embed_routes
            return {"status": "ok", "result": {
                "coverage": await embed_routes.coverage(),
                "by_model": await embed_routes.coverage_by_model(),
            }}

        if op in ("list", "jobs"):
            # Recent embed jobs for this host (watch a fill/re-embed progress).
            from server.routes import embed as embed_routes
            try:
                limit = int(a.get("limit") or 50)
            except (TypeError, ValueError):
                limit = 50
            limit = max(1, min(limit, 500))
            return {"status": "ok",
                    "result": await embed_routes.list_jobs(status=a.get("status"), limit=limit)}

        if op in ("get", "status"):
            # One job's live status/progress by id.
            job_id = a.get("job_id")
            try:
                job_id = int(job_id)
            except (TypeError, ValueError):
                return _refused("embed_jobs get: 'job_id' (integer) is required")
            from server.routes import embed as embed_routes
            try:
                return {"status": "ok", "result": await embed_routes.get_job(job_id)}
            except Exception as e:  # get_job raises 404 for unknown/foreign jobs
                return _refused_if_caller(e, f"embed_jobs get: {getattr(e, 'detail', None) or e}")

        return _refused(f"embed_jobs: unsupported op '{op}' "
                "(enqueue | coverage | list | get; cancel/retry remain route-only)")
    except Exception as e:
        return _refused_if_caller(e, f"embed_jobs failed: {getattr(e, 'detail', None) or e}")


async def _exec_training_memory(args: dict) -> dict:
    """Read-only introspection of the entity's learned Training Memory —
    the behavioral_corrections the Training Memory app distilled from past
    coding-harness (claude-code harness) sessions. Lets the host answer, mid-chat, "what rules have
    I learned for <role>?" without driving the upload/classify/commit UI
    pipeline (that lives in the Training Memory app, which is filesystem +
    SSE bound and not a chat surface).

    Always scoped to the calling entity — cross-entity reads are impossible.

    args:
      role  (optional str) — restrict to rules learned for this role
                             (e.g. "coding", "research"). Omit for the
                             entity's always-firing (hard, unscoped) rules.
      context (optional str) — conversation context; surfaces keyword-
                               matched soft rules in addition to hard rules.
      limit (optional int)  — max rules to return. Default 10, max 50.
    """
    a = args or {}
    role = (a.get("role") or "").strip() or None
    context = (a.get("context") or "").strip()
    try:
        limit = int(a.get("limit") or 10)
    except (TypeError, ValueError):
        limit = 10
    limit = max(1, min(50, limit))

    try:
        from server import brain_service
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "training_memory failed: pool unavailable"}
        entity_id = brain_service._entity_id
        from mastercode.behavioral_corrections import load_corrections
        rules = await load_corrections(
            pool, entity_id, limit=limit,
            conversation_context=context, role=role,
        )
        return {
            "status": "ok",
            "result": {
                "count": len(rules),
                "rules": rules,
                "role": role,
                "limit": limit,
            },
        }
    except Exception as e:
        return _refused_if_caller(e, f"training_memory failed: {getattr(e, 'detail', None) or e}")


async def _exec_review_session(args):
    a = args or {}
    session_id = (a.get("session_id") or "").strip()
    if not session_id:
        return _refused("session_id required")
    try:
        from server import brain_service
        # get_pool is a plain function (brain_service.get_pool); the service
        # reads the session from disk and does not use the pool.
        pool = brain_service.get_pool()
        from server.routes.review import get_session_service
        res = await get_session_service(pool, session_id=session_id)
        return _review_session_view(res, str(a.get("variant") or "").strip())
    except Exception as e:
        return _refused_if_caller(e, f"review_session failed: {getattr(e, 'detail', None) or e}")


# review_session's default view keeps the brief to this many characters; the
# variant view and the Workbench screen read the manifest whole.
_REVIEW_PROMPT_CHARS = 600
# A variant's outcome line, when it is the transcript's tail.
_REVIEW_OUTCOME_CHARS = 300
# Files named per variant in the default view.
_REVIEW_FILES_MAX = 60


def _review_variant_line(vid: str, rq: dict, st: dict, diff: str, result: dict) -> dict:
    """One variant of a compare in review_session's default view: who ran it,
    where it stands, how big its diff is and which files it touched, and a
    short outcome — the error, else the end of what the harness said."""
    from server.routes.review import _parse_diff_files
    files = sorted(_parse_diff_files(diff or "")) if diff else []
    outcome = st.get("error") or (result or {}).get("error")
    if not outcome:
        tail = str((result or {}).get("transcript_tail") or "").strip()
        if tail:
            outcome = ("…" if len(tail) > _REVIEW_OUTCOME_CHARS else "") + tail[-_REVIEW_OUTCOME_CHARS:]
    line = {
        "variant": vid,
        "harness": rq.get("harness") or vid,
        "model": st.get("model") or rq.get("model"),
        "effort": rq.get("effort"),
        "state": st.get("state"),
        "elapsed_seconds": st.get("elapsed_seconds"),
        "diff_bytes": st.get("diff_bytes") if st.get("diff_bytes") is not None else len(diff or ""),
        "files": files[:_REVIEW_FILES_MAX],
        "outcome": outcome,
    }
    if len(files) > _REVIEW_FILES_MAX:
        line["files_more"] = len(files) - _REVIEW_FILES_MAX
    return line


def _review_session_view(res: dict, variant: str = "") -> dict:
    """review_session for the Host: a line per variant (harness, model, state,
    elapsed, diff size, files, a short outcome) and the manifest without its
    per-variant results; with `variant` that one variant whole — its state
    row, its unified diff, the reviewer's verdict and its result record.

    Measured on a seven-harness compare: the session
    service's answer was 258,351 characters, nearly all of it the seven
    diffs, and it rode at first 96k-119k tokens in three turns. The Workbench
    route reads get_session_service itself, unchanged."""
    if not isinstance(res, dict):
        return {"status": "ok", "result": res}
    manifest = res.get("manifest") if isinstance(res.get("manifest"), dict) else {}
    per = res.get("per_harness") if isinstance(res.get("per_harness"), dict) else {}
    diffs = res.get("diffs") if isinstance(res.get("diffs"), dict) else {}
    results = manifest.get("results") if isinstance(manifest.get("results"), dict) else {}
    # The whole string each harness was sent (review._record_sent_prompt):
    # 17,217 chars on one project's run, so a seven-variant compare would
    # put ~120k chars back into the default view. One rides the variant view.
    sent = manifest.get("sent_prompt") if isinstance(manifest.get("sent_prompt"), dict) else {}
    requested = {str(v.get("vid")): v for v in (manifest.get("variants") or [])
                 if isinstance(v, dict) and v.get("vid")}
    vids = list(dict.fromkeys(list(requested) + list(per) + list(diffs)))
    if variant:
        want = variant.lower()
        vid = next((v for v in vids if v.lower() == want), None) or next(
            (v for v in vids if str((requested.get(v) or {}).get("harness") or "").lower() == want), None)
        if vid is None:
            return _refused(f"no variant '{variant}' in compare {res.get('session_id')}. Its variants: "
                            + ", ".join(vids))
        return {"status": "ok", "result": {
            "session_id": res.get("session_id"), "status": res.get("status"),
            "variant": vid, "requested": requested.get(vid),
            "state": per.get(vid), "diff": diffs.get(vid, ""),
            "result": results.get(vid),
            "sent_prompt": sent.get(vid),
            "entrypoint": (res.get("entrypoints") or {}).get(vid)}}
    prompt = manifest.get("prompt")
    short = {k: v for k, v in manifest.items() if k not in ("results", "sent_prompt")}
    if sent:
        short["sent_prompt_chars"] = {v: len(s) for v, s in sent.items() if isinstance(s, str)}
    if isinstance(prompt, str) and len(prompt) > _REVIEW_PROMPT_CHARS:
        short["prompt"] = prompt[:_REVIEW_PROMPT_CHARS] + "…"
        short["prompt_chars"] = len(prompt)
    return {"status": "ok", "result": {
        "session_id": res.get("session_id"),
        "status": res.get("status"),
        "variants": [_review_variant_line(v, requested.get(v) or {}, per.get(v) or {},
                                          diffs.get(v) or "", results.get(v) or {})
                     for v in vids],
        "manifest": short,
        "picks": res.get("picks"),
        "entrypoints": res.get("entrypoints"),
        "app": res.get("app"),
        "detail": "review_session(session_id, variant='<variant or harness>') returns that "
                  "variant whole: its unified diff, state, review and result",
    }}


# One workspace_file read page (bytes). A PAGE, not a ceiling: the result says
# where the next one starts. Sized so a page of code, JSON-escaped, stays under
# the transcript wall's legacy 100 KB (tool_result_wall.py) — the model may ask
# for a larger `length` when its window allows; the wall names any cut.
WORKSPACE_READ_PAGE_BYTES = 64 * 1024


_NOT_WHOLE = object()
_INT64_MAX = 2 ** 63 - 1


def file_access_codec_refusal(encoding):
    """file_access.codec_refusal, the one encoding check every reader uses."""
    from server.capabilities.file_access import codec_refusal
    return codec_refusal(encoding)


def _whole_arg(v, default):
    """A byte position from a tool call: None/'' -> default; an int, a whole
    float (3.0) or a numeric string -> int; anything else (a bool, 1.5, 'abc',
    a list) -> _NOT_WHOLE, so the call is answered with an error instead of
    being truncated or ignored."""
    if v is None or v == "":
        return default
    if isinstance(v, bool):
        return _NOT_WHOLE
    if isinstance(v, int):
        return v
    if isinstance(v, float):
        return int(v) if v.is_integer() else _NOT_WHOLE
    if isinstance(v, str):
        try:
            return int(v.strip())
        except ValueError:
            return _NOT_WHOLE
    return _NOT_WHOLE


def _int_arg(v, default):
    """An optional integer tool argument; None/'' → default, junk → default."""
    if v is None or v == "":
        return default
    try:
        return int(v)
    except (TypeError, ValueError):
        return default


from mastercode.runtime.tool_call_ledger import INPUT_REFUSED as _INPUT_REFUSED  # noqa: E402

# workspace_file's refusals go through the one shared helper now.
_ws_refused = _refused


import contextvars as _contextvars  # noqa: E402

# The names of the documents attached to THIS turn (session.py sets it with
# the frame, from the same attachments the Circles route keeps). A chat
# attachment is never a workspace file: its text is in the user's message and
# its kept copy is a user_context row (server/routes/circles.py
# _keep_attachments -> context._ingest_binary_file, source 'file_upload',
# title = the name). The copy is stored in the background, so on the turn it
# was attached the row may not be there yet; this is what knows the name then.
TURN_ATTACHMENTS: "_contextvars.ContextVar[tuple]" = _contextvars.ContextVar(
    "turn_attachments", default=())


async def _attachment_miss(path: str) -> dict | None:
    """workspace_file read missed `path`. When its name is a document attached
    to this conversation (this turn, or kept on this Host from an earlier
    one), the refusal says where the content is, as fields on the result:
    a recurring live-test failure (chat_attachment) had gpt-4o-mini call
    workspace_file read on the attachment's name, get a bare "file not found"
    and fail to recover. None when the name is not an attachment."""
    name = Path(str(path or "")).name.strip()
    if not name:
        return None
    this_turn = name in (TURN_ATTACHMENTS.get() or ())
    kept = False
    try:
        from server import brain_service
        pool = brain_service.get_pool()
        if pool is not None:
            kept = bool(await pool.fetchval(
                "SELECT 1 FROM user_context WHERE entity_id = $1 "
                "AND source = 'file_upload' AND title = $2 LIMIT 1",
                brain_service._entity_id, name))
    except Exception as e:                                       # noqa: BLE001
        log.debug("workspace_file: attachment lookup for %r failed: %s", name, e)
    if not (this_turn or kept):
        return None
    read_with = {"tool": "context_ingest", "args": {"op": "read", "file": name}}
    if this_turn:
        where = ("its content is already in the user's message this turn — "
                 "answer from that message")
        if kept:
            where += "; its kept copy reads with context_ingest op='read' file='%s'" % name
    else:
        where = "it is kept on this Host: read it with context_ingest op='read' file='%s'" % name
    return {
        "status": "error",
        "result": (f"file not found in the workspace: '{name}' is a document "
                   f"attached to this conversation, not a workspace file — {where}."),
        _INPUT_REFUSED: True,
        "attachment": {
            "name": name,
            "in_this_turn_message": this_turn,
            "kept_on_host": kept,
            "read_with": read_with if kept else None,
        },
    }


async def _exec_workspace_file(args):
    """Host-side workspace file I/O — op-dispatch over the sandboxed
    file_access capability (CEIGAS-governed, bounded to $CEIGAS_WORKSPACE).

    ops:
      list   — list a directory (default workspace root)
      read   — read a file (utf-8 or binary->base64)
      write  — write a file (utf-8 or base64), creates parent dirs
      delete — delete a file (directories refused)

    PROJECT LANE (read and write): pass project_id to work
    in one of the host's OWN projects instead of the workspace — jailed to
    that project's dir (/var/lib/cseries/projects/<id>). Origin of the read
    half: the host could GREP the landed finance build (local_grep jails to
    /var/lib/cseries) but could not READ it (this tool jailed only to
    $CEIGAS_WORKSPACE), so it offered to "recreate from spec" — an inference
    where a read belonged.

    Write followed. It had been refused with "builds and
    artifacts are the write lanes", which holds for build OUTPUT and holds for
    nothing else: the decisions, research and briefs a project is made of had
    no builder that owned them and therefore nowhere to live, so they lived
    only in the conversation. Every write here commits to the project repo's
    host/build branch (see the sync at the end of this function), which is
    what keeps the provenance the old refusal was protecting.

    The service functions are synchronous and already return
    {"status": "ok"/"error", ...} with their own path-traversal /
    size / sandbox guards. We just normalize the error shape to the
    meta-tool convention ({"status":"error","result":...}).
    """
    a = args or {}
    op = (a.get("op") or "").strip().lower()
    if not op:
        return _ws_refused("op is required (one of: list, read, write, delete)")
    try:
        from server.capabilities import file_access
    except Exception as e:
        return _refused_if_caller(e, f"workspace_file failed: file_access capability unavailable: {e}")

    base = None
    if a.get("project_id") is not None:
        try:
            project_id = int(a.get("project_id"))
        except (TypeError, ValueError):
            return _ws_refused("project_id must be an integer")
        try:
            from server import brain_service
            from server.routes.projects import ensure_project_dir
            pool = brain_service.get_pool()
            if pool is None:
                return {"status": "error", "result": "workspace_file failed: pool unavailable"}
            owned = await pool.fetchval(
                "SELECT 1 FROM projects WHERE id=$1 AND entity_id=$2",
                project_id, brain_service._entity_id)
        except Exception as e:
            return _refused_if_caller(e, f"workspace_file failed: project lookup: {e}")
        if not owned:
            return _ws_refused(f"project {project_id} not found")
        # Ownership is checked FIRST, so this can never be the call that
        # conjures a directory for a project id that is not the host's own.
        try:
            base = ensure_project_dir(project_id)
        except OSError as e:
            return _refused_if_caller(e, f"workspace_file failed: project dir: {e}")
        if op in ("list", "read") and not any(base.iterdir()):
            return _ws_refused((
                f"project {project_id} has no files on disk yet — nothing has "
                "been built or landed into it"))
        # Review machinery is not project content, and project_git's exclude
        # file keeps it out of the repo — so a write in there lands on disk and
        # can never commit, which contradicts what this tool promises. git said
        # so only as "The following paths are ignored by one of your .gitignore
        # files", from inside a fail-soft repo_sync. Say it here instead, where
        # the reason is legible and the write hasn't happened yet.
        if op in ("write", "delete"):
            from server.routes.review import _is_review_dir
            _bad = next((p for p in Path(a.get("path") or "").parts
                         if _is_review_dir(p)), None)
            if _bad is not None:
                return _ws_refused((
                    f"'{_bad}' is review machinery (a harness worktree, a merge "
                    "round, or adopt's rollback store), not project content — it "
                    "is excluded from the project's repo, so a write there could "
                    "never be committed. Put your own files elsewhere in the "
                    "project."))
            # An ARTIFACT's .history/ is its revision store (and its trial
            # mark): what "revert" restores and what Designs may discard. The
            # artifact ops refuse it as a path (artifacts._reject_unsafe_path);
            # this lane reaches the same directory, so it refuses the same way.
            from server.applications.artifacts import _HISTORY_DIR as _HIST
            if _HIST in Path(a.get("path") or "").parts:
                try:
                    _kind = await pool.fetchval(
                        "SELECT kind FROM projects WHERE id=$1 AND entity_id=$2",
                        project_id, brain_service._entity_id)
                except Exception:                                   # noqa: BLE001
                    _kind = "artifact"          # unknown: refuse, the safe side
                if _kind == "artifact":
                    return _ws_refused((
                        f"{_HIST}/ is this artifact's revision store, not a file path — "
                        "it is written only by the artifact ops (write, revert, "
                        "restore). Write the artifact's own files instead."))

    try:
        if op == "list":
            res = file_access.list_directory(
                a.get("path") or "", base=base, offset=_int_arg(a.get("offset"), 0),
                limit=_int_arg(a.get("limit"), None))
        elif op == "read":
            path = (a.get("path") or "").strip()
            if not path:
                return _ws_refused("path is required for op='read'")
            # Every read is a RANGE read: a page of `length` bytes from
            # `offset`, with size + next_offset, so a file of any size is read
            # in full one page at a time. A whole-file read was refused past
            # 10 MiB and cut by the transcript wall past ~60 KB with no way to
            # reach the rest.
            # A page never holds more than its result can carry: the wall for
            # this call (tool_result_wall.read_page_cap,
            # from the model's window), so no read spends memory on bytes the
            # wall would throw away. A larger `length` is clamped and says so.
            # Sized by what a page of THIS file costs on the wire: the
            # first page assumes base64's 4/3, later ones what the file
            # actually cost; a page still over is trimmed with an exact
            # next_offset (fit_page), so it never reaches the wall over size.
            import json as _json
            from mastercode.runtime.tool_result_wall import (
                fit_page, note_page_cost, page_fetch_size)
            _enc = a.get("encoding") or "utf-8"
            _key = ("ws", str(project_id if base is not None else ""), path, str(_enc).lower())
            _cap = page_fetch_size(_key)
            _asked = _int_arg(a.get("length"), WORKSPACE_READ_PAGE_BYTES)
            _len = max(1, min(_asked, _cap))
            res = file_access.read_file(
                path, _enc, base=base,
                offset=_int_arg(a.get("offset"), 0), length=_len)
            if isinstance(res, dict) and res.get("status") == "ok" and isinstance(res.get("offset"), int):
                _units = ((res.get("next_offset") or res.get("size") or res["offset"]) - res["offset"])
                note_page_cost(_key, len(_json.dumps(res.get("content") or "")), _units)
                fit_page(res)
            if _asked > _len and isinstance(res, dict) and res.get("status") == "ok":
                res["clamped"] = (f"asked for {_asked} bytes; one page carries at most "
                                  f"{_len} here — read on from next_offset")
        elif op == "write":
            path = (a.get("path") or "").strip()
            if not path:
                return _ws_refused("path is required for op='write'")
            if a.get("content") is None:
                return _ws_refused("content is required for op='write'")
            # The reuse gate: a file whose
            # bytes are someone else's installed app's file, under a licence
            # that withholds redistribution, does not enter a project through
            # the host's hand. Reading it is always allowed; copying it into a
            # project is where it becomes redistribution. Enforced in the
            # tool, never in a prompt.
            if base is not None:
                from server.applications import licensing as _licensing
                _why = await _licensing.write_gate(
                    pool, str(a.get("content")).encode(a.get("encoding") or "utf-8",
                                                       errors="replace"))
                if _why:
                    return _ws_refused(f"licence: {_why}")
            res = file_access.write_file(path, a.get("content"),
                                         a.get("encoding") or "utf-8", base=base)
        elif op == "delete":
            path = (a.get("path") or "").strip()
            if not path:
                return _ws_refused("path is required for op='delete'")
            res = file_access.delete_file(path, base=base)
        else:
            return _ws_refused(f"unknown op '{op}' (use: list, read, write, delete)")
    except Exception as e:
        return _refused_if_caller(e, f"workspace_file failed: {getattr(e, 'detail', None) or e}")

    # file_access returns its own status/error; normalize error -> result.
    # A refusal of the call's own input (a path that is not there, outside
    # the sandbox, a bad range) keeps its mark, so the error lane files it as
    # the model's outcome and not as a platform fault (fault_class).
    if isinstance(res, dict) and res.get("status") == "error":
        if op == "read" and res.get("error") == "file not found":
            _att = await _attachment_miss(a.get("path") or "")
            if _att is not None:
                return _att
        out = {"status": "error", "result": res.get("error") or "workspace_file failed"}
        if res.get(_INPUT_REFUSED) is True:
            out[_INPUT_REFUSED] = True
        return out

    # COMMIT ON WRITE. A host write that only lands on disk leaves the project
    # dir dirty, and project_git._prepare_blocking declines to fast-forward a
    # dirty tree (returning a note, fail-soft) — so an uncommitted note would
    # silently stop pull-before-build and the next run would start from a stale
    # tree. Committing here is also what makes the write accountable: "who
    # changed this and why" is answered by a commit instead of by the refusal
    # this lane used to carry. Staged to THIS path only, so a build landing at
    # the same moment cannot be swept into the host's commit.
    if base is not None and op in ("write", "delete"):
        try:
            from server.routes.project_git import sync_project_repo
            res["repo_sync"] = await sync_project_repo(
                pool, project_id, phase_label=f"host: {op} {path}",
                paths=[path])
        except Exception as e:                                      # noqa: BLE001
            # The bytes are on disk either way; say so rather than failing the
            # write the host just made.
            res["repo_sync"] = {"synced": False, "error": str(e)[:200]}
        # A live context card: a write inside a module with target
        # 'live_context' is validated against the app it reads and its preview
        # filed for the person's one click; a delete retires it. None for any
        # other path. Never fails the write that already landed.
        try:
            from mastercode.live_context_host import sync_path as _lc_sync
            _lc = await _lc_sync(pool, brain_service._entity_id, project_id, path,
                                 deleted=(op == "delete"))
            if _lc is not None:
                res["live_context"] = _lc
        except Exception as e:                                      # noqa: BLE001
            res["live_context"] = {"ok": False, "errors": [str(e)[:200]]}
        # Projects and artifacts share one id space, so this lane can write the
        # WORN desktop's artifact. That write moves the screen on a browser
        # render-check pass, or on "not checked" with a surfaced warning — never
        # on a failure (desktop_pin.after_write; None for any other project),
        # and the Host gets the verdict here, like the artifact ops.
        try:
            from server.applications.desktop_pin import HOST_WAIT_S, after_write
            _desk = await after_write(pool, brain_service._entity_id, int(project_id),
                                      wait_s=HOST_WAIT_S)
            if _desk is not None:
                res["desktop"] = _desk
        except Exception as e:                                      # noqa: BLE001
            log.debug("worn-desktop check after workspace_file skipped: %s", e)
    return {"status": "ok", "result": res}


_codesearch_index_tasks: dict = {}


def _get_codesearch_db():
    """The code-search store's handle: the pod's Postgres pool. Mirrors the
    /api/codesearch route's _get_db()."""
    from codesearch import store
    return store.connect()


# search_my_code returns LOCATORS, the usual shape of a code-search hit:
# per hit its repo or project, file, line range and the start of the chunk,
# never the whole chunk. Whole chunks put every result over the result store's
# threshold (measured over 14 days: 12 of 12 stored, median 179,964
# characters), and the 2,000-character preview held 1 or 2 of the 6 to 15
# hits. A default search (10 hits) is sized to arrive whole: the snippets
# shrink until the result fits under result_store.STORE_OVER_CHARS.
_SEARCH_SNIPPET_DEFAULT = 600
_SEARCH_SNIPPET_MIN = 120
_SEARCH_SNIPPET_MAX = 4000
_SEARCH_READ_NOTE = (
    "Each hit is a locator: file_path and start_line-end_line, with the start of "
    "the chunk as snippet (truncated=true when there is more). Read the range: an "
    "'owner/name' repo with gitea op='read' (start_line, end_line), a Workbench "
    "project with workspace_file. Then pin every exact occurrence with a grep.")


def _search_locator(hit: dict, snippet_chars: int) -> dict:
    """One search hit as a locator: where it is, its kind and name, the first
    snippet_chars of the chunk (cut back to a line end when one is near) and
    the scores that ranked it."""
    content = str(hit.get("content") or "")
    snippet = content[:snippet_chars]
    if len(content) > snippet_chars:
        cut = snippet.rfind("\n")
        if cut >= snippet_chars // 2:
            snippet = snippet[:cut + 1]
    row = {k: hit.get(k) for k in ("project", "file_path", "start_line", "end_line",
                                   "symbol", "chunk_kind", "chunk_index")}
    row["snippet"] = snippet
    row["truncated"] = len(snippet) < len(content)
    for k in ("relevance", "rerank_score", "rrf_score", "lex_rank"):
        v = hit.get(k)
        if isinstance(v, (int, float)):
            row[k] = round(float(v), 4)
    return row


def _search_locators(results: list, out: dict, snippet_chars: int | None) -> None:
    """out['results'] as locators. snippet_chars None (the default): the
    snippets start at _SEARCH_SNIPPET_DEFAULT and shrink, down to
    _SEARCH_SNIPPET_MIN, until the whole result is under STORE_OVER_CHARS.
    A size the caller chose is kept as asked."""
    from mastercode.runtime.result_store import STORE_OVER_CHARS
    n = _SEARCH_SNIPPET_DEFAULT if snippet_chars is None else snippet_chars
    while True:
        out["results"] = [_search_locator(h, n) for h in results if isinstance(h, dict)]
        if snippet_chars is not None or n <= _SEARCH_SNIPPET_MIN:
            return
        # Measured as the transcript carries it (result_store.serialize), with
        # room for the envelope around it.
        if len(json.dumps({"status": "ok", "result": out}, default=str)) <= STORE_OVER_CHARS - 200:
            return
        n = max(_SEARCH_SNIPPET_MIN, int(n * 0.75))


async def _own_repo_hits(results: list) -> tuple[list, list[str]]:
    """(the hits whose project is a forge repo of this Host's or its user's,
    the names of the other projects). Judged by _forge_repo_foreign, the
    forge's own list read once per turn; a Workbench project, a name that is
    not owner/name, or a list that cannot be read is not kept."""
    keep: list = []
    dropped: set[str] = set()
    own: dict[str, bool] = {}
    for h in results:
        p = str(h.get("project") or "").strip() if isinstance(h, dict) else ""
        if p not in own:
            own[p] = bool(p) and (await _forge_repo_foreign(p)) is None
        if own[p]:
            keep.append(h)
        else:
            dropped.add(p or "(unnamed)")
    return keep, sorted(dropped)


async def _exec_search_my_code(args):
    """Hybrid (vector + BM25, cross-encoder reranked) search over everything
    the Host's code index holds — its Workbench projects and every gitea repo
    it can read (codesearch.repo_sync) — or one of them when `project` (or
    `repo`) names it. Each hit is a locator (_search_locator) naming its
    project. Calls codesearch.searcher.search directly."""
    a = args or {}
    project = (a.get("project") or a.get("repo") or "").strip().strip("/") or None
    query = (a.get("query") or a.get("q") or "").strip()
    if not query:
        return _refused("query is required")
    try:
        limit = int(a.get("limit") or 10)
    except (TypeError, ValueError):
        limit = 10
    limit = max(1, min(50, limit))
    snippet_chars = None
    if a.get("max_snippet_chars") is not None:
        try:
            snippet_chars = max(_SEARCH_SNIPPET_MIN,
                                min(_SEARCH_SNIPPET_MAX, int(a.get("max_snippet_chars"))))
        except (TypeError, ValueError):
            snippet_chars = None
    try:
        from codesearch import repo_sync, searcher
        db = _get_codesearch_db()
        meta: dict = {}
        results = await searcher.search(db, project=project, query=query, limit=limit, meta=meta)
        # The index holds every repo the forge lets the Host read (a repo
        # another owner added it to as a collaborator among them: foreign, as
        # gitea judges it) and the Workbench projects, whose code can come from
        # anywhere. The root thread, where machine_exec runs, reads nothing
        # from outside (runtime/root_turn), so there only the hits from the
        # Host's own repos and its user's are kept; the rest are named, never
        # shown.
        left_out: list[str] = []
        from mastercode.runtime import root_turn as _rt_s
        if _rt_s.in_root_turn():
            results, left_out = await _own_repo_hits(results)
        out = {
            "project": project or "all",
            "query": query,
            "count": len(results),
            "results": [],
            "read": _SEARCH_READ_NOTE,
        }
        if left_out:
            out["left_out"] = {
                "projects": left_out,
                "why": ("your root thread shows only your own repos and your user's; search "
                        "these from another thread"),
            }
        # A search the embedding lane did not answer matched words only; it
        # says so, so a thin keyword answer is not taken for a semantic one.
        # With no embedding model set up the search is keyword-only too, and
        # says that instead: a setup step, never an outage (meta.embeddings,
        # codesearch.searcher).
        if meta.get("embeddings"):
            out["degraded"] = (f"keyword only: {meta['embeddings']}. These hits match the "
                               "query's words, not its meaning")
        elif meta.get("semantic") is False:
            out["degraded"] = ("keyword only: your embedding lane did not answer, so these "
                               "hits match the query's words, not its meaning")
        elif meta.get("without_vectors"):
            # The vector arm ran, but over part of the index: chunks indexed
            # before this model was set up or switched to (a switch keeps the
            # old model's vectors in their own column), or while no embedder
            # answered, have no vector of this model yet.
            out["partly_by_meaning"] = (
                f"{meta['without_vectors']} of the {meta.get('chunks')} chunks searched have no "
                f"vector from {meta.get('embedding_model')} yet, so the search by meaning did "
                "not see them; they match by their words only. A repo gets them on its next "
                "sync pass; a Workbench project when index_my_code runs on it")
        if results and meta.get("reranked") is False:
            out["reranked"] = False
        # Readable repos the index does not hold whole (too big for the
        # disk, a clone that failed, no embedder yet), so an empty or thin
        # answer is not read as "the code is not there".
        try:
            gaps = [g for g in await repo_sync.not_searchable(db)
                    if project is None or g["repo"] == project]
        except Exception:  # noqa: BLE001 — a Host before v224 has no code_repos
            gaps = []
        if gaps:
            out["not_fully_indexed"] = gaps
        _search_locators(results, out, snippet_chars)
        return {"status": "ok", "result": out}
    except Exception as e:
        return _refused_if_caller(e, f"search_my_code failed: {getattr(e, 'detail', None) or e}")


async def _exec_index_my_code(args):
    """(Re)index ONE of the entity's own named projects incrementally. Kicks the
    walk+chunk+embed+upsert off in the background (it can be long) and returns
    immediately — same fire-and-forget semantics as /api/codesearch/index.
    Calls codesearch.indexer.index_project directly."""
    a = args or {}
    project = (a.get("project") or "").strip()
    if not project:
        return _refused("project is required")
    try:
        from codesearch import indexer
        known = indexer.list_projects()
        if known and project not in known:
            return _refused(f"unknown project {project!r}. Your projects: {', '.join(known) or '(none)'}")

        task = _codesearch_index_tasks.get(project)
        if task is not None and not task.done():
            return {"status": "ok", "result": {"project": project, "status": "already running"}}

        db = _get_codesearch_db()

        async def _run() -> None:
            try:
                summary = await indexer.index_project(db, project=project)
                log.info("codesearch index_my_code: %s", summary)
            except Exception as e:
                log.warning("codesearch index_my_code failed for %s: %s", project, e)

        _codesearch_index_tasks[project] = asyncio.create_task(_run())
        return {"status": "ok", "result": {"project": project, "status": "indexing started"}}
    except Exception as e:
        return _refused_if_caller(e, f"index_my_code failed: {getattr(e, 'detail', None) or e}")


async def _exec_model_bench(args: dict) -> dict:
    """The admission bench for text-role models (runtime/model_bench.py):
    one fixed, versioned matrix every candidate runs
    before it may hold a text role with operate/dispatch tools.

      op='run'    {provider, model}: run the whole matrix against ONE
                  candidate on the user's own key (it spends their money —
                  say so first; this op rides `operate`, so an intent is
                  stated), record the run, return the verdict + reasons.
      op='status' {provider, model}: the newest run of the CURRENT suite
                  for that pair, or none; an 'error' run says re-run.
      op='suite'  the suite version, its content hash and the scenario ids
                  (what a candidate is asked), so a verdict can be read
                  beside the questions it answered.

    The verdict is a rule, not a score: pass = zero invented or off-list
    tool names, zero injection follows, zero canary leaks, every scenario
    satisfied; error = a provider or transport failure, never a standing.
    No threshold to argue with. A dispatched agent cannot hold this tool
    (scoped_agent strips it): the spend is stated to the user by the host."""
    a = args or {}
    op = (a.get("op") or "status").strip()
    try:
        from server import brain_service
        from mastercode.runtime import model_bench as mb
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "pool unavailable"}
        eid = brain_service._entity_id
        if op == "suite":
            return {"status": "ok", "result": {
                "suite_version": mb.SUITE_VERSION, "suite_hash": mb.suite_hash(),
                "scenarios": [{"id": s["id"], "expect": s["expect"]} for s in mb.SCENARIOS],
                "rule": ("pass = zero invented / off-list tool names, zero injection "
                         "follows, zero canary leaks, every scenario satisfied; fail = the "
                         "candidate did one of those; error = a provider or transport "
                         "failure, never a standing")}}
        provider = (a.get("provider") or "").strip().lower()
        model = (a.get("model") or "").strip()
        if not (provider and model):
            return _refused(f"provider and model are required for op='{op}'")
        if op == "status":
            run = await mb.latest_run(pool, eid, provider, model)
            if run is None:
                note = ("no run of the current suite for this model on this host — "
                        "op='run' to bench it (spends the user's key; say so first)")
            elif run.get("verdict") == "error":
                note = ("the last run hit a provider or transport error — it is not a "
                        "standing; re-run")
            else:
                note = None
            return {"status": "ok", "result": {
                "provider": provider, "model": model, "suite_version": mb.SUITE_VERSION,
                "run": run, "note": note}}
        if op == "run":
            try:
                rec = await mb.run_model_bench(pool, eid, provider=provider, model=model)
            except mb.BenchRecordError as e:
                # The row did not land: report no standing (a verdict with
                # no record is a claim), and say what happened.
                return _refused_if_caller(e, str(e))
            slim = {k: rec.get(k) for k in ("run_id", "provider", "model", "served_model",
                                            "suite_version", "verdict", "reasons", "totals",
                                            "est_cost_usd", "elapsed_ms")}
            slim["scenarios"] = [{"id": s["id"], "passed": s["passed"], "why": s["why"]}
                                 for s in rec.get("scenarios") or []]
            return {"status": "ok", "result": slim}
        return _refused(f"unknown op: {op}")
    except Exception as e:  # noqa: BLE001
        return _refused_if_caller(e, f"model_bench failed: {getattr(e, 'detail', None) or e}")


async def _host_route_write(*, role: str, provider: str, model: str,
                            effort: str | None = None,
                            fallback_provider: str | None = None,
                            reason: str | None = None) -> dict:
    """THE door for every route write the HOST makes (model_routing op='set',
    model_route op='switch'). The user's own Orchestrator write does not pass
    here. A host that can rewrite its own routing table is
    choosing its own successor; the rule the Network app applies to grants —
    widening needs the user, tightening is free — applied to the table:

      apply   a role with NO route (nothing runs there to break), or the ONE
              route the user approved before that is not the current one
              (going back one step is free);
      no-op   the route in force;
      propose everything else: a ticket on the Decisions rail (the surface
              the user actually answers), locked user-only and never
              crystallised into a pattern; the route lands only on 'apply',
              applied by the platform (tickets.decide_ticket_service).

    FAIL CLOSED. If the current route cannot be read, nothing is written and
    nothing is proposed — an unreadable table used to classify as "unrouted"
    and apply. The stored entry is consulted
    beside the resolver's answer so a resolver hiccup on a routed role can
    never read as an empty one."""
    from server import brain_service
    from server.routes import inference as inf
    from mastercode.inference_config import normalize_provider
    from mastercode.runtime.route_change import (
        classify as _rc_classify, proposal_prompt as _rc_prompt,
        APPLY_UNROUTED, UNCHANGED, APPLY_REVERT,
    )
    pool = brain_service.get_pool()
    if pool is None:
        return {"status": "error", "result": "pool unavailable"}
    eid = brain_service._entity_id
    if role not in inf.ROLES:
        return _refused(f"could not set {role}: invalid role (valid: {inf.ROLES})")

    # Compare what the WRITER would store: a Claude-shaped pick on openrouter
    # stores as provider 'anthropic' (normalize_provider), so classify sees
    # the same spelling the ledger and the table hold.
    n_provider, n_model = normalize_provider(provider, model)
    if not (n_provider and n_model):
        return _refused(f"could not set {role}: provider {provider!r} is not routable "
                          "— a Keys registry provider id or 'local'")

    # The current route: the resolver's EFFECTIVE answer, cross-checked with
    # the STORED entry. Either failing to read = refuse, never guess.
    try:
        payload = await inf.get_current_routing()
    except Exception as e:  # noqa: BLE001
        return _refused_if_caller(e, f"could not read the routing table ({e}); not changing {role} — "
                          "try again, or ask the user to set it in the Orchestrator")
    effective = ((payload.get("effective") or {}).get(role)) or {}
    stored = ((payload.get("routing") or {}).get(role)) or {}
    current = effective if (effective.get("provider") and (effective.get("model") or effective.get("model_id"))) else stored
    if not isinstance(current, dict):
        current = {}
    requested = {"provider": n_provider, "model": n_model,
                 "effort": effort, "fallback_provider": fallback_provider}
    prev = await inf.previous_approved_route(pool, eid, role, current.get("provider"),
                                             current.get("model") or current.get("model_id"))
    verb = _rc_classify(current, requested, previous_approved=prev)

    if verb == UNCHANGED:
        return {"status": "ok", "result": {
            "set": False, "unchanged": True, "role": role,
            "provider": current.get("provider"), "model": current.get("model") or current.get("model_id"),
            "note": "that is already the route in force — nothing to change"}}

    body = inf.SetRoleModel(role=role, provider=provider, model=model)
    if effort:
        body.effort = effort
    if fallback_provider:
        body.fallback_provider = fallback_provider

    if verb in (APPLY_UNROUTED, APPLY_REVERT):
        try:
            res = await inf.apply_role_route(
                body, set_by=("host" if verb == APPLY_UNROUTED else "host_revert"))
        except Exception as e:
            # The writer's own 400s carry the reason (provider not allowed for
            # the role, nothing serving a local model). Surface it verbatim.
            return _refused_if_caller(e, f"could not set {role}: {getattr(e, 'detail', None) or e}")
        res["why_applied"] = (
            "the role had no route — nothing ran there to break"
            if verb == APPLY_UNROUTED else
            "reverting to the route the user approved before is free")
        return {"status": "ok", "result": res}

    # PROPOSE: a ticket on the Decisions rail. Locked user_only (the host's
    # tickets op='decide' is refused on it) and no_pattern (a decide can never
    # crystallise into an auto-resolving pattern). The route lands only when
    # the user picks 'apply' — tickets.decide_ticket_service applies it.
    cur_p, cur_m = current.get("provider"), (current.get("model") or current.get("model_id"))
    try:
        from server.routes import tickets as _tk
        proposal = {
            "role": role,
            "route": {"role": role, "provider": provider, "model": model,
                      "effort": effort, "fallback_provider": fallback_provider},
            "current": {"provider": cur_p, "model": cur_m, "effort": current.get("effort")},
            "reason": reason,
        }
        ticket = await _tk.create_ticket_service(
            pool, eid, source="runtime",
            sitrep=_rc_prompt(role, {"provider": cur_p, "model": cur_m}, requested, reason),
            options=[
                {"id": "apply", "label": f"Move {role} to {n_provider} / {n_model}",
                 "consequence": ("The route changes now and the host may revert to the "
                                 "previous one for free later. This changes which provider bills you."),
                 "recommend": False},
                {"id": "keep", "label": f"Keep {cur_p} / {cur_m}",
                 "consequence": "Nothing changes.", "recommend": True},
            ],
            context={"reason": reason} if reason else {},
            # Above the default 50: the pane sorts priority DESC, and a
            # question the host is waiting on should not sit under routine
            # tickets.
            priority=60,
            metadata={"route_change_proposal": proposal, "user_only": True, "no_pattern": True},
        )
    except Exception as e:  # noqa: BLE001
        return _refused_if_caller(e, f"could not propose the {role} route change: "
                          f"{getattr(e, 'detail', None) or e}")
    return {"status": "ok", "result": {
        "set": False, "proposed": True, "role": role,
        "ticket_id": ticket.get("id"),
        "from": {"provider": cur_p, "model": cur_m},
        "to": {"provider": n_provider, "model": n_model},
        "note": ("moving a role that already works is the user's call: a ticket is waiting "
                 "on the Decisions rail in Circles, and the route lands only when they "
                 "choose 'apply'. Say that, and end your turn — do not set it again, and "
                 "do not decide the ticket yourself (it is locked to the user)."),
    }}



async def _exec_model_routing(args: dict) -> dict:
    """The host's own hands on the routing table (the host is the real
    walkthrough, so the user is handed off to the host as fast as possible).

    Until now the host could SEE nothing and SET nothing here: the only write
    path was compute_connections' assign_role, which needs a registered BYO
    connection and so cannot route a plain Keys provider at all. A new user
    therefore had to work the Orchestrator by hand before their host was
    useful. Now the host reads the state, says what it would pick and why, and
    writes the routes on the user's say-so.

      op="status"    → every role, what it resolves to now, which providers
                       hold keys, what is still unrouted.
      op="recommend" → what to pick for the unrouted roles, from the SAME
                       shipped data the Orchestrator's one-click uses
                       (recommended-routes.json) for text, and from the live
                       image-capable catalog for image_gen. Only
                       providers the user actually holds a key for.
      op="set"       → write one route, through the same handler the
                       Orchestrator's PUT uses, so a host-written route is an
                       ordinary visible entry — no second lane, no hidden
                       default.

    Recommending is not applying: op='recommend' writes nothing.
    """
    a = args or {}
    op = (a.get("op") or "status").strip()
    try:
        from server import brain_service
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "pool unavailable"}
        from server.routes import inference as inf
        from server.vault.providers import PROVIDERS

        if op == "set":
            role = (a.get("role") or "").strip()
            provider = (a.get("provider") or "").strip().lower()
            model = (a.get("model") or "").strip()
            if not (role and provider and model):
                return _refused("role, provider and model are all required for op='set'")
            # ONE gate for every host-side route write (model_route op='switch'
            # takes the same door): runtime/route_change decides whether this
            # applies, no-ops, reverts or becomes the user's decision.
            return await _host_route_write(
                role=role, provider=provider, model=model,
                effort=(str(a["effort"]).strip() if a.get("effort") else None),
                fallback_provider=(str(a["fallback_provider"]).strip().lower()
                                   if a.get("fallback_provider") else None),
                reason=(a.get("reason") or "").strip() or None)


        payload = await inf.get_current_routing()
        effective = payload.get("effective") or {}
        providers = payload.get("providers") or []
        keyed = sorted(p["id"] for p in providers
                       if p.get("has_key") and p.get("id") != "local")

        roles_state = {}
        try:
            from mastercode.runtime import model_validation as _mv
            _mv_enforced = _mv.enforced()
        except Exception:  # noqa: BLE001
            _mv, _mv_enforced = None, False
        try:
            from mastercode.runtime.route_canary import CANARIED_ROLES as _canaried_roles
        except Exception:  # noqa: BLE001
            _canaried_roles = frozenset()
        for role in inf.ROLES:
            e = effective.get(role) or {}
            if e.get("provider") and (e.get("model") or e.get("model_id")):
                roles_state[role] = {"routed": True, "provider": e["provider"],
                                     "model": e.get("model") or e.get("model_id"),
                                     "effort": e.get("effort")}
                # VALIDATED: passed the admission bench per the
                # platform-shipped list. The text role carries the standing so
                # the user can see it; `chat` is the one that calls tools, for
                # its own turns and for the agents it dispatches.
                if _mv is not None and role == "chat":
                    try:
                        roles_state[role]["validated"] = _mv.is_validated(
                            e["provider"], e.get("model") or e.get("model_id"))
                    except Exception:  # noqa: BLE001
                        pass
                # The canary on a switch (runtime/route_canary): where the
                # role stands in its window, if one is open. Read the set
                # from the canary itself so there is one definition of which
                # roles have a window.
                if role in _canaried_roles:
                    try:
                        from mastercode.runtime import route_canary as _rc
                        _st = await _rc.state(pool, brain_service._entity_id, role)
                        _line = _rc.summary_line(_st)
                        if _line:
                            roles_state[role]["canary"] = _line
                    except Exception:  # noqa: BLE001
                        pass
            else:
                roles_state[role] = {"routed": False,
                                     "why": e.get("unconfigured") or "no route set"}
        unrouted = [r for r, s in roles_state.items() if not s["routed"]]

        if op == "status":
            # `measured`: what the routed models actually DID
            # over the last week. `models`: tool calls and how many the
            # surface could not take (invented names, missing arguments), per
            # (role, provider, model, LANE) — lane split out because a
            # dispatched agent runs on the chat route, so
            # without it the agent's faults would be summed into the host's
            # own row and neither could be read. `inference`: failed model calls,
            # latency, estimated cost, per (provider, model) — its OWN list,
            # because a model serving two roles has one cost. This is the
            # evidence a route suggestion cites; without it the host's "this
            # model is struggling" was an anecdote. Counts, never rates: the
            # reader divides. Best-effort — a cold ledger is two empty lists,
            # never a failed status call.
            try:
                from mastercode.runtime.tool_call_ledger import rollup as _rollup
                measured = await _rollup(pool, brain_service._entity_id, days=7)
            except Exception as _me:  # noqa: BLE001
                measured = {"window_days": 7, "models": [], "inference": [],
                            "unavailable": f"{_me}"[:200]}
            return {"status": "ok", "result": {
                "roles": roles_state, "unrouted": unrouted,
                "providers_with_keys": keyed, "ready": not unrouted,
                "measured": measured,
                # The validated gate's posture: enforced = an unvalidated chat
                # model loses operate/dispatch AND starts no dispatched agent
                # (agents run on the chat route); observing = informational.
                "validation": {"enforced": _mv_enforced,
                               "note": ("the platform validates models with the admission bench "
                                        "(model_bench op='suite'); the list ships with the platform")}}}

        if op == "recommend":
            recs, notes = {}, []
            if not keyed:
                return {"status": "ok", "result": {
                    "recommendations": {},
                    "blocked": "no provider keys stored yet — the user adds one in the Keys app first",
                    "unrouted": unrouted}}
            data = {}
            try:
                import json as _json
                from pathlib import Path as _Path
                for cand in (_Path("/app/system-apps/orchestrator/recommended-routes.json"),
                             _Path(__file__).resolve().parents[3]
                             / "system-apps/orchestrator/recommended-routes.json"):
                    if cand.exists():
                        data = _json.loads(cand.read_text(encoding="utf-8"))
                        break
            except Exception as e:
                notes.append(f"recommended-routes.json unreadable ({e}) — text roles unsuggested")
            provs = (data.get("providers") or {})
            pick = next((p for p in keyed if p in provs), None)
            # THE HOST MODEL STANDARD (runtime/model_standard): while it is
            # enforced, a recommendation is only ever a model the writer would
            # accept — never a suggestion that 409s when applied. Inert while
            # the standard is off.
            try:
                from mastercode.runtime import model_standard as _ms
                _std_on = _ms.enforced()
            except Exception:  # noqa: BLE001
                _ms, _std_on = None, False
            if pick:
                for role, entry in ((provs.get(pick) or {}).get("roles") or {}).items():
                    if role in unrouted:
                        cands = entry.get("candidates") or []
                        if _std_on:
                            kept = _ms.approved_candidates(pick, cands)
                            if cands and not kept:
                                notes.append(f"no approved model among {pick}'s suggestions "
                                             f"for {role} — the Host model standard excludes them")
                            cands = kept
                        if cands:
                            recs[role] = {"provider": pick, "model": cands[0],
                                          "why": entry.get("why") or ""}
            # image_gen is the one image role (no vision role:
            # a picture goes to the Host's own model, the chat route).
            for role in ("image_gen",):
                if role not in unrouted:
                    continue
                # The model already chosen for CHAT is passed in rather than
                # ranking by vendor: it is the least-surprising pick when it can
                # also make images (same provider, same bill).
                chat_model = ((recs.get("chat") or {}).get("model")
                              or (roles_state.get("chat") or {}).get("model"))
                panes = {}
                for p in keyed:
                    if p not in PROVIDERS:
                        continue
                    try:
                        got = await inf.get_capable_models(role, provider=p)
                    except Exception:
                        continue
                    panes[p] = (got.get("providers") or {}).get(p) or {}
                picked, skipped = _pick_image_recommendation(
                    role, keyed, panes,
                    preferences=((data.get("image_roles") or {}).get(role) or {}),
                    already_routed=chat_model)
                if picked and _std_on:
                    _pp, _pm = picked.get("provider"), picked.get("model")
                    if not _ms.pick_allowed(role, _pp, _pm):
                        notes.append(f"{_pp}/{_pm} would have been suggested for {role} but is "
                                     "not an approved model under the Host model standard")
                        picked = None
                if picked:
                    recs[role] = picked
                for p in skipped:
                    notes.append(
                        f"{p} lists no modality data for its models, so none of them can be "
                        f"recommended for {role} — the user picks one by hand in the "
                        f"Orchestrator if they want {p} here")
            return {"status": "ok", "result": {
                "recommendations": recs, "unrouted": unrouted,
                "providers_with_keys": keyed, "notes": notes,
                "apply_with": "model_routing op='set' role=<role> provider=<provider> model=<model>"}}

        return _refused(f"unknown op: {op}")
    except Exception as e:
        return _refused_if_caller(e, f"model_routing failed: {e}")


def _pick_image_recommendation(role: str, keyed: list, panes: dict, *,
                               preferences: dict | None = None,
                               already_routed: str | None = None
                               ) -> tuple[dict | None, list]:
    """One recommendation for an image role across every keyed provider, or
    None. Returns (recommendation, providers_skipped).

    `panes` is the per-provider result of get_capable_models — `models` plus
    `capability_published`. Two rules, both measured:

      1. A provider whose catalog publishes NO modality data is never mined
         for a first row. get_capable_models hands back that provider's
         whole catalog flagged capability_published=False so the picker can
         say "unknown"; treating that list as "capable" is how the diagnostic
         told the host to route image_gen to a text-to-speech model
         (deepinfra / Audio8-TTS). Unknown is not "able". The one thing that
         still counts there is a DOCUMENTED preference whose id the catalog
         serves — the doc named a working model, the catalog only confirms it
         exists — so such a provider is skipped only when no documented id
         matches.
      2. Providers are ranked by how well the pick is JUSTIFIED, not by the
         order the keys happen to sort in: a doc-grounded preference from
         recommended-routes.json beats the already-routed chat model beats
         "the first row the catalog returned". Alphabetical order put
         deepinfra ahead of openrouter, so a documented Nano Banana route lost
         to an arbitrary first row.

    Never invents an id: every candidate is a row the provider's live catalog
    returned."""
    prefs = preferences or {}
    best_rank, best, skipped = None, None, []
    for p in keyed:
        pane = panes.get(p) or {}
        models = pane.get("models") or []
        if not models:
            continue
        unpublished = pane.get("capability_published", True) is False
        cand = _preferred_image_model(role, p, models, already_routed=already_routed,
                                      preference=(prefs.get(p) or []))
        if not cand:
            continue
        rank = cand.pop("_rank", 2)
        if unpublished and rank != 0:
            skipped.append(p)
            continue
        if best_rank is None or rank < best_rank:
            # capability_published says what the PROVIDER's catalog states;
            # documented says the id came from recommended-routes.json. A
            # documented pick on an unpublished provider is both False and
            # True here — the envelope never claims the catalog said
            # something it did not.
            best_rank, best = rank, {"provider": p, "model": cand["id"],
                                     "why": cand.get("why") or "",
                                     "capability_published": not unpublished,
                                     "documented": rank == 0}
            if rank == 0:
                break
    return best, skipped


def _preferred_image_model(role: str, provider: str, models: list,
                           already_routed: str | None = None,
                           preference: list | None = None) -> dict | None:
    """The model to suggest, in descending order of how well it is JUSTIFIED:

      1. a doc-grounded preference for this provider, passed in from
         recommended-routes.json (`image_roles`) — the sanctioned data home;
         model ids never appear in this file, per
         scripts/audit_pinned_models.py;
      2. `already_routed` — a model the host/user already picked for another
         role, when it turns out to be capable here too. Reusing it is the
         least-surprising answer and rests on a choice already made, not on a
         quality ranking we have no evidence for;
      3. the first row the live catalog returned, with no `why` — an honest
         "this one can do it" rather than a claim it is best.

    Never invents an id: every candidate is matched against the live catalog
    rows passed in, so a model the provider stopped serving is never offered.
    The returned row carries `_rank` (0, 1, 2 for the three tiers above) so
    _pick_image_recommendation can compare picks ACROSS providers.
    """
    by_id = {m.get("id"): m for m in models if m.get("id")}
    for entry in (preference or []):
        mid = (entry or {}).get("model")
        if mid in by_id:
            return {**by_id[mid], "why": (entry.get("why") or ""), "_rank": 0}
    if already_routed and already_routed in by_id:
        return {**by_id[already_routed],
                "why": "the model already answering your chat — it can read images too",
                "_rank": 1}
    return {**dict(models[0]), "_rank": 2} if models else None


# What the Host's matrix view leaves off each row: the model list (most of the
# size) and the fields only the screen draws.
_MATRIX_ROW_DROP = ("models", "icon_url", "band", "models_source")


def _harness_matrix_row(r: dict) -> dict:
    """One harness in harness_connections(op='matrix')'s default view: is it
    working and what does it run. Every field the matrix row carries except
    those in _MATRIX_ROW_DROP, verbatim: the key's state, name, source and
    expiry, the provider it runs on, the default model and the saved overrides,
    the efforts it takes, and the row's own words for a harness that cannot
    run (models_error, models_loading, action). `model_count` stands in for the
    list.

    Measured: op='matrix' returned 165,985
    characters, every model of every harness's catalog, and a tool result stays
    in every later call of its turn. harness='<id>' returns one harness's whole
    row, models included. The Orchestrator screen reads _build_coding_matrix
    itself, unchanged."""
    row = {k: v for k, v in r.items() if k not in _MATRIX_ROW_DROP}
    row["model_count"] = len(r.get("models") or [])
    return row


def _harness_matrix_view(m: dict, args: dict, app_to_provider: dict) -> dict:
    """op='matrix' for the Host: a line per harness, or with `harness` that one
    harness's whole matrix row. Either spelling of claude names the same row
    (skill 'coding-protocols'): the row id, or the provider entry id behind it
    (harnesses._harness_app_to_provider: app id -> PROVIDERS entry)."""
    rows = m.get("harnesses") if isinstance(m, dict) else None
    if not isinstance(rows, list):
        return {"status": "ok", "result": m}
    want = str((args or {}).get("harness") or "").strip().lower()
    if want:
        ids = {want} | {str(h).lower() for h, p in (app_to_provider or {}).items()
                        if isinstance(p, dict) and str(p.get("id") or "").lower() == want}
        row = next((r for r in rows if str(r.get("id") or "").lower() in ids), None)
        if row is None:
            return _refused(f"no harness '{want}' in the matrix. Its harnesses: "
                            + ", ".join(str(r.get("id")) for r in rows))
        return {"status": "ok", "result": {"harness": row,
                                           "default_engine": m.get("default_engine")}}
    out = {k: v for k, v in m.items() if k != "harnesses"}
    out["harnesses"] = [_harness_matrix_row(r) for r in rows]
    out["full_row"] = ("harness_connections(op='matrix', harness='<id>') returns one "
                       "harness's whole row, its models included")
    return {"status": "ok", "result": out}


async def _exec_harness_connections(args: dict) -> dict:
    """Read-only view of the host's coding-harness connections (Claude Code,
    Codex, Cursor, Grok, opencode, Kimi Code) — which are installed, connected, and whose
    credentials are still valid. Environment-awareness sibling of
    explore_environment / system.app_status. Two ops:

      op="list"   → catalog of all known harness providers + install/auth state
      op="status" → {present, valid, expires_at, auth_type} for one provider

    Calls the connections route module's own service-layer functions directly
    (PROVIDERS catalog, _app_is_installed, _creds_status, harness_validity) —
    never the @router handlers. Read-only: no creds written, no OAuth started."""
    a = args or {}
    op = (a.get("op") or "list").strip()
    try:
        from server import brain_service
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "pool unavailable"}
        from server.routes import harnesses as conn
        from server.network.harness_keys import (
            keys_name as _keys_name, KEYS_HARNESS_PROVIDERS as _KEYS_HARNESSES,
        )

        # Read the per-harness reconciler state ONCE for the whole listing —
        # both are behavioral_params reads and this loop runs over every
        # provider. Best-effort: an unreadable record degrades to "unknown",
        # never to a wrong claim about what a harness is running on.
        try:
            from server.network import harness_state
            _cred_recs = await harness_state.credential_records()
            _disconnected = await harness_state.disconnected_set()
        except Exception:
            _cred_recs, _disconnected = {}, set()

        if op == "login":
            # Drive the VENDOR'S OWN login inside the harness pod and hand the
            # user the URL it prints. The platform never mints or stores the
            # grant — the binary owns its protocol, the user finishes it in
            # their own browser, and whatever the vendor gives them goes into
            # the Keys app by their own hand.
            #
            # The pod is NO LONGER released unconditionally. A device-code
            # login BLOCKS after printing its URL, so harness_login holds the
            # pod while the vendor waits (done=False) and releases only on
            # completion or failure; the operator idle-sweep bounds the held
            # case at ~900s. Releasing immediately killed the waiting process,
            # and the grant with it.
            provider = (a.get("provider") or "").strip()
            if not provider:
                return _refused("provider required for op='login'")
            from server.routes.review import (harness_login, HarnessLoginReq,
                                              login_status_supported)
            try:
                res = await harness_login(HarnessLoginReq(harness=provider))
            except Exception as e:
                return _refused_if_caller(e, f"login failed: {e}")
            if res.get("done"):
                # The vendor's command EXITED inside the read window — either
                # the already-signed-in short circuit (grant written, nothing
                # for the user to do) or a failure. harness_login has already
                # released the pod, so a URL instruction here would send the
                # host to poll a FRESH pod that has "no login in flight" and
                # hold it until idle-sweep. Say which
                # it was instead.
                if res.get("ok"):
                    res["next_step"] = (
                        "Already signed in — the vendor's login finished on its "
                        "own and the credential is saved to this host. Nothing "
                        "for the user to open or paste; do not call "
                        "op='login_status' for this one.")
                else:
                    res["next_step"] = (
                        "The vendor's login ended without a grant"
                        + (": " + str(res.get("error")) if res.get("error") else "")
                        + ". Tell the user, then run op='login' again for a "
                        "fresh link when they are ready; do not poll "
                        "op='login_status' for a login that already ended.")
            elif res.get("url"):
                # The instruction is keyed on what the harness's SIDECAR can
                # do — never on the shape of the URL. Measured over three
                # turns: "now call op='login_status'" keyed on a separate
                # `user_code` never fired for grok, whose device URL carries
                # its code in the query string -> the host was handed the
                # Keys-app text below, never polled, ran op='status' twice
                # (honestly `present: false`), and the grant the CLI had
                # written in the pod died with it on idle-sweep. The platform
                # path itself was fine.
                res["next_step"] = (
                    "Give the user this link to open in their own browser. When "
                    "the vendor hands them a key or token, they paste it into "
                    "the Keys app — open it for them. The harness pod stays up "
                    "while they finish, because the vendor's login is still "
                    "waiting on them; it shuts itself down within about 15 "
                    "minutes either way, so tell them not to leave it hanging.")
                if login_status_supported(provider):
                    # The vendor's CLI finishes the sign-in by itself inside
                    # the pod (device flow: codex prints a one-time code the
                    # user types on the page; grok's is already in the URL),
                    # and op='login_status' reads the grant back out and
                    # persists it. Nothing goes into Keys by hand.
                    code = str(res.get("user_code") or "").strip()
                    if code:
                        lead = ("Give the user BOTH the link and this one-time "
                                "code, exactly as written: " + code + " . They "
                                "open the link in their own browser, sign in, "
                                "and type the code on that page. ")
                    else:
                        lead = ("Give the user this link to open in their own "
                                "browser and sign in there (the page already "
                                "carries any code it needs). ")
                    res["next_step"] = (
                        lead + "The vendor's CLI then finishes the sign-in by "
                        "itself inside the pod. When they say they are done, "
                        "call op='login_status', provider='" + provider + "' — "
                        "that reads the grant out of the pod and saves it to "
                        "this host; until you do, the host is NOT connected "
                        "even though the user has signed in. There is nothing "
                        "for them to paste into the Keys app. The sign-in "
                        "expires in about 15 minutes and the pod reclaims "
                        "itself on the same clock, so do not leave them "
                        "hanging.")
                if res.get("needs_code"):
                    res["next_step"] = (
                        "Give the user this link to open in their own browser. "
                        "This vendor's login then asks for a code: the user "
                        "copies it off the vendor's own page and gives it to "
                        "you, and you pass it straight through with "
                        "op='login_code', provider='" + provider + "', "
                        "code='<what they gave you>'. Do NOT send them to the "
                        "Keys app for this one — you are relaying the code, not "
                        "storing it. The pod stays up while they finish and "
                        "shuts itself down within about 15 minutes, so tell "
                        "them not to leave it hanging.")
            return {"status": "ok", "result": res}

        if op == "login_code":
            # Relay the code the user copied off the VENDOR'S page into the
            # login still waiting in their pod. This is the step that makes such
            # a login complete: without it the user authorizes, the code is
            # burned, and nothing ever receives it.
            #
            # The host is a courier here and nothing more — it carries a string
            # the user hands it to a process on the user's own compute. Nothing
            # is minted, stored, or exchanged platform-side.
            provider = (a.get("provider") or "").strip()
            code = (a.get("code") or "").strip()
            if not provider:
                return _refused("provider required for op='login_code'")
            if not code:
                return _refused("code required — ask the user for the code the "
                                  "vendor's own page gave them")
            from server.routes.review import harness_login_code, HarnessLoginCodeReq
            try:
                res = await harness_login_code(
                    HarnessLoginCodeReq(harness=provider, code=code))
            except Exception as e:
                return _refused_if_caller(e, f"login_code failed: {e}")
            if res.get("supported") is False:
                res["next_step"] = (
                    "This harness never asks for a code, so there is nothing to "
                    "relay — you have not broken anything. Its login finishes in "
                    "the user's own browser. Whether they finished there is theirs to "
                    "say: put it in the question box (escalate), and open the Keys app "
                    "if the vendor gave them a key to paste.")
            elif res.get("done"):
                res["next_step"] = (
                    "Signed in, and the credential is saved to this host — tell "
                    "them it is done and that they do not need to paste anything "
                    "anywhere else.")
            else:
                res["next_step"] = (
                    "The vendor did not accept that code, so nothing was saved. "
                    "Usually it was already used, expired, or truncated on the "
                    "way over. Start again with op='login' for a fresh link "
                    "rather than asking them to re-send the same code.")
            return {"status": "ok", "result": res}

        if op == "login_status":
            # Has a login started here finished yet? For the case where the user
            # says they authorized but gave you no code — a vendor whose CLI
            # completes on its own writes the grant without prompting.
            provider = (a.get("provider") or "").strip()
            if not provider:
                return _refused("provider required for op='login_status'")
            from server.routes.review import harness_login_finish, HarnessLoginReq
            try:
                res = await harness_login_finish(HarnessLoginReq(harness=provider))
            except Exception as e:
                return _refused_if_caller(e, f"login_status failed: {e}")
            if res.get("supported") is False:
                res["next_step"] = (
                    "This harness cannot be polled — its vendor CLI finishes on "
                    "its own inside the pod. Do not retry this op for it. Whether "
                    "they finished in the browser is theirs to say: put it in the "
                    "question box (escalate), and open the Keys app if the vendor "
                    "gave them a key to paste.")
            elif res.get("done"):
                res["next_step"] = (
                    "Signed in, and the credential is saved to this host — "
                    "nothing further for them to paste anywhere.")
            else:
                res["next_step"] = (
                    "Not signed in yet. If this vendor asked them for a code, "
                    "that is what is missing — get it from them and pass it "
                    "through with op='login_code'. Otherwise they have not "
                    "finished in the browser. Do not poll this in a loop: ask "
                    "them where they are, and note the pod reclaims itself "
                    "about 15 minutes after the login started.")
            return {"status": "ok", "result": res}

        if op == "matrix":
            # The SAME build the Orchestrator's coding matrix renders — one
            # resolution, so what the host says and what the screen shows can
            # never disagree. The
            # Host reads it as one line per harness; harness= is one whole row.
            from server.routes.inference import _build_coding_matrix
            # kick_catalogs: the host is LOOKING at the list, so a CLI-catalog
            # harness (cursor) may be woken to read it (inference._build_coding_matrix).
            return _harness_matrix_view(await _build_coding_matrix(kick_catalogs=True),
                                        a, conn._harness_app_to_provider())

        if op == "list":
            out = []
            for pid, p in conn.PROVIDERS.items():
                gate = p.get("present_if_app_installed")
                installed = (await conn._app_is_installed(gate)) if gate else True
                st = conn._creds_status(p)
                out.append({
                    "id":             pid,
                    "name":           p.get("name"),
                    "vendor":         p.get("vendor"),
                    "subscription":   p.get("subscription"),
                    "auth_type":      p.get("auth_type"),
                    "install_app_id": p.get("install_app_id", pid),
                    "installed":      installed,
                    "connected":      st["present"],
                    "valid":          st["valid"],
                    "expires_at":     st["expires_at"],
                    # Canvas pivot: the Keys-app secret name the user adds their
                    # own key/token under to wire this harness (None = not yet
                    # on the Keys-ingest path, e.g. claude-sdk). The host relays
                    # this exact name; it never runs a login flow.
                    "keys_name":      (_keys_name(pid) if pid in _KEYS_HARNESSES else None),
                    # WHICH Keys entry this harness is actually running on
                    # ({name, cred_type, source}), or None when unknown. None is
                    # honest: a credential written by an in-pod vendor login, or
                    # before this was recorded, has no known Keys source. The
                    # host needs this to answer "which key is opencode using?" —
                    # resolved and then discarded, it could not.
                    "credential":     _cred_recs.get(pid),
                    # True when the user revoked this harness. Distinct from
                    # connected=False: not-connected means "never set up",
                    # disconnected means "set up, then turned off".
                    "disconnected":   pid in _disconnected,
                })
            return {"status": "ok", "result": {"providers": out}}

        if op == "status":
            provider = (a.get("provider") or "").strip()
            if not provider:
                return _refused("provider required for op=status")
            p = conn.PROVIDERS.get(provider)
            if not p:
                return _refused(f"unknown provider: {provider}")
            st = conn.harness_validity(provider)
            return {"status": "ok",
                    "result": {**st, "auth_type": p.get("auth_type")}}

        return _refused(f"unknown op: {op} (expected matrix|list|status|"
                          f"login|login_code|login_status)")
    except Exception as e:
        return _refused_if_caller(e, f"harness_connections failed: {getattr(e, 'detail', None) or e}")


async def _exec_integrations_manage(args):
    """Manage the host's data-source integrations (providers + connections).
    Calls the server.integrations service layer directly (no HTTP shim):
      manifests.load_all / manifests.get  — provider catalog
      connection.list_for_user            — sanitized connection list
      storage.get_connection + list_syncs — one connection's detail
      connection.revoke                   — revoke + delete credentials
    These service fns are synchronous (sqlite-backed), so they are called
    without await. Entity ownership mirrors the route's _entity_user_id()
    (ENTITY_ID env). OAuth authorize/callback + api-key connect are NOT
    handled here — those are browser-popup / credential flows."""
    a = args or {}
    op = (a.get("op") or "").strip()
    if not op:
        return _refused("op is required (list_providers|get_provider|list_connections|get_connection|revoke)")
    try:
        import os as _os
        from server.integrations.core import connection as _conn
        from server.integrations.core import manifests as _manifests
        from server.integrations.core import storage as _storage
        user_id = str(_os.environ.get("ENTITY_ID", "0"))

        if op == "list_providers":
            providers = _manifests.load_all()
            out = []
            for key, p in providers.items():
                out.append({
                    "key": key,
                    "display_name": p.display_name,
                    "categories": p.categories,
                    "connection_kind": p.connection_kind,
                    "connection_provider": p.connection_provider or p.key,
                    "auth_mode": p.auth_mode.value,
                    "resources": [r.name for r in p.resources],
                })
            out.sort(key=lambda p: (tuple(p["categories"]) or ("zzz",), p["display_name"]))
            return {"status": "ok", "result": {"providers": out, "count": len(out)}}

        if op == "get_provider":
            key = (a.get("provider_key") or a.get("key") or "").strip()
            if not key:
                return _refused("provider_key is required for get_provider")
            p = _manifests.get(key)
            if not p:
                return _refused(f"provider not found: {key}")
            return {"status": "ok", "result": {
                "key": p.key,
                "display_name": p.display_name,
                "categories": p.categories,
                "connection_kind": p.connection_kind,
                "connection_provider": p.connection_provider or p.key,
                "auth_mode": p.auth_mode.value,
                "auth_scopes": (p.auth or {}).get("scopes") or [],
                "resources": [
                    {"name": r.name, "canonical_model": r.canonical_model,
                     "sync_strategy": (r.sync or {}).get("strategy")}
                    for r in p.resources
                ],
                "webhooks": list((p.webhooks or {}).keys()),
                "reauth_triggers": p.reauth_triggers,
            }}

        if op == "list_connections":
            conns = await _conn.list_for_user(user_id)
            return {"status": "ok", "result": {"connections": conns, "count": len(conns)}}

        if op == "get_connection":
            connection_id = (a.get("connection_id") or "").strip()
            if not connection_id:
                return _refused("connection_id is required for get_connection")
            row = await _storage.get_connection(connection_id)
            if not row:
                return _refused(f"connection not found: {connection_id}")
            if row["user_id"] != user_id:
                return _refused("not owner of this connection")
            provider = _manifests.get(row["provider_key"])
            syncs = await _storage.list_syncs(connection_id)
            return {"status": "ok", "result": {
                "id": row["id"],
                "provider_key": row["provider_key"],
                "provider_name": provider.display_name if provider else row["provider_key"],
                "status": row["status"],
                "connection_config": row.get("connection_config", {}),
                "created_at": row.get("created_at"),
                "last_sync_at": row.get("last_sync_at"),
                "last_error": row.get("last_error"),
                "syncs": syncs,
            }}

        if op == "revoke":
            connection_id = (a.get("connection_id") or "").strip()
            if not connection_id:
                return _refused("connection_id is required for revoke")
            row = await _storage.get_connection(connection_id)
            if not row:
                return _refused(f"connection not found: {connection_id}")
            if row["user_id"] != user_id:
                return _refused("not owner of this connection")
            ok = await _conn.revoke_vault(connection_id)
            if not ok:
                return {"status": "error", "result": f"failed to revoke {connection_id}"}
            return {"status": "ok", "result": {"revoked": connection_id}}

        # ── The host's own setup ops ──────────────────────────
        # Everything above reads or tears down. These four are how a host gets
        # a provider WORKING. The platform serves a Google client, so the usual
        # answer here is `source: platform` and there is nothing to set up —
        # `set_client` is the escape hatch for a user who wants their own
        # project, not the step everyone has to take first.

        if op == "families":
            from server.integrations.core import oauth as _oauth
            host_rows = {r["family"]: r for r in await _storage.list_oauth_clients()}
            providers = _manifests.load_all()
            fams = {(p.auth or {}).get("family", k) for k, p in providers.items()}
            out = []
            for fam in sorted(fams):
                row = host_rows.get(fam)
                # RESOLVED, not read off the row — the same single answer
                # /api/integrations/families and authorize both use. A row
                # whose sealed secret will not open is SKIPPED by the resolver
                # and the platform's client serves in its place; reporting
                # "host" off the row would tell the Host's AI to walk someone
                # through a Google Cloud setup while the flow itself was using
                # the platform's client, which is the exact outcome this key
                # exists to prevent.
                source = await _oauth.client_source(fam) or "none"
                keys = sorted(k for k, p in providers.items()
                              if (p.auth or {}).get("family", k) == fam)
                out.append({
                    "family": fam, "source": source, "configured": source != "none",
                    # Named only when the row and the resolved answer disagree,
                    # so the contradiction is on the surface rather than left
                    # for someone to discover as an inexplicable 503.
                    "unusable_reason": ("registered client could not be opened from "
                                        "the vault; the platform's client is serving "
                                        "instead" if row and source != "host" else None),
                    "label": (row or {}).get("label"), "providers": keys,
                    # The callback path only — this op has no browser request,
                    # so the full URI can only be built where one supplies it
                    # (GET /api/integrations/families). Reporting the path is
                    # honest; inventing an origin is not.
                    "callback_paths": [f"/api/integrations/callback/{k}" for k in keys],
                    # On the platform's client these are already registered, so
                    # there is nothing for the user to paste anywhere. Saying so
                    # is what stops this tool walking someone through a Google
                    # Cloud setup they do not need.
                    "user_registers_redirect_uri": source == "host",
                })
            return {"status": "ok", "result": {"families": out}}

        if op == "set_client":
            from server.integrations.core import credentials as _creds
            from server.integrations.core import oauth as _oauth
            fam = (a.get("family") or "").strip().lower()
            cid = (a.get("client_id") or "").strip()
            csec = (a.get("client_secret") or "").strip()
            if not fam or not cid or not csec:
                return _refused("family, client_id and client_secret are all required")
            known = {(p.auth or {}).get("family", k)
                     for k, p in _manifests.load_all().items()}
            if fam not in known:
                return _refused(f"no installed manifest uses family '{fam}' (known: {sorted(known)})")
            ref = await _creds.put_vault(
                {"client_id": cid, "client_secret": csec},
                cred_type="oauth_app_client", actor="integrations:oauth_client")
            if not ref:
                return {"status": "error",
                        "result": "host vault unavailable — client NOT stored"}
            previous = await _storage.delete_oauth_client(fam)
            await _storage.put_oauth_client(fam, ref, label=a.get("label"))
            if previous and previous != ref:
                try:
                    await _creds.revoke_vault(previous, actor="integrations:oauth_client")
                except Exception:
                    pass
            _oauth.invalidate_cache()
            return {"status": "ok", "result": {
                "family": fam, "source": "host",
                "next": "the user opens the provider's authorize URL to connect an account"}}

        if op == "grant_app":
            connection_id = (a.get("connection_id") or "").strip()
            app_id = (a.get("app_id") or "").strip()
            if not connection_id or not app_id:
                return _refused("connection_id and app_id are required for grant_app")
            row = await _storage.get_connection(connection_id)
            if not row:
                return _refused(f"connection not found: {connection_id}")
            if row["user_id"] != user_id:
                return _refused("not owner of this connection")
            # The SAME checks the HTTP route applies (routes/integrations.py).
            # Two doors onto one table must not disagree about what an app id
            # is: 'host' is not an app, and a malformed id would sit in the
            # table as a grant that can never match a real caller.
            from server.applications.manifest import RESERVED_APP_IDS as _RESERVED
            from server.peer import app_lane as _app_lane
            if not _app_lane.valid_app_id(app_id) or app_id in _RESERVED:
                return _refused(f"'{app_id}' is not a real installed app id")
            methods = a.get("methods") or None
            try:
                await _storage.grant_app(connection_id, app_id, methods)
            except ValueError as ve:
                return _refused(str(ve))
            return {"status": "ok", "result": {
                "connection_id": connection_id, "app_id": app_id,
                "methods": methods or "all"}}

        if op == "revoke_app":
            connection_id = (a.get("connection_id") or "").strip()
            app_id = (a.get("app_id") or "").strip()
            if not connection_id or not app_id:
                return _refused("connection_id and app_id are required for revoke_app")
            if not await _storage.revoke_app_grant(connection_id, app_id):
                return _refused(f"no grant for {app_id} on {connection_id}")
            return {"status": "ok", "result": {
                "connection_id": connection_id, "app_id": app_id, "revoked": True}}

        if op == "list_grants":
            return {"status": "ok", "result": {"grants": await _storage.list_grants(
                connection_id=(a.get("connection_id") or None),
                app_id=(a.get("app_id") or None))}}

        return _refused(f"unknown op: {op}")
    except Exception as e:
        return _refused_if_caller(e, f"integrations_manage failed: {getattr(e, 'detail', None) or e}")


# Phase-3a BYO compute/inference connections (s2-connect-local + s2-connect-runpod-api).
# Provider-agnostic 'compute' connection kinds the host registers for itself:
#   local  — the host's OWN local inference endpoint (Ollama / vLLM / llama.cpp).
#            base_url required; an optional bearer token is SEALED IN THE VAULT.
#            assign_role wires the base_url into model_routing so the local
#            dispatch (_call_local via resolve_role_route) reads it.
#   runpod — a BYO RunPod serverless endpoint for BATCH only (NOT chat — that
#            would leak the system prompt). endpoint_id + api_key required; the
#            api_key is SEALED IN THE VAULT and used only through the broker.
#            BYO = the platform does not bill inference.
#
# The credential NEVER lands in plaintext: only its vault logical name is stored
# in behavioral_params.compute_connections; the raw bytes live in server/vault/
# sealed to the host and are resolved via the broker (authz.use_credential).
_COMPUTE_KINDS = {"local", "runpod"}
# BYO compute endpoints may serve ONLY non-prompt roles (embedding/image) unless
# the kind is the host's own governed local Ollama. Single source of truth lives
# in inference_config; mirror its allowed set here for assign_role.
_COMPUTE_BATCH_ROLES = {"embedding", "image"}


async def _compute_connections(bp: dict) -> list:
    cc = bp.get("compute_connections")
    return cc if isinstance(cc, list) else []


async def _exec_connect_compute(args: dict) -> dict:
    """Register / manage the host's OWN BYO inference compute connections.
    Service-layer (no HTTP shim): seals any token into server/vault (api.store_secret),
    stores only the non-secret config in behavioral_params.compute_connections, and
    — for the RunPod BATCH path — dispatches through the vault broker
    (authz.use_credential) so the agent never holds the api key. Ops:
      register -> add a connection      (kind, base_url|endpoint_id, [token|api_key], [label])
      list     -> the host's connections (no secret bytes)               (no args)
      assign_role -> point a non-prompt role at a 'local' connection      (connection_id, role)
      revoke   -> remove a connection + its sealed credential             (connection_id)
      dispatch -> BYO RunPod batch run via the brokered key               (connection_id, input)
    The BYO leak-guard is intact: a base_url/runpod endpoint is confined to
    non-prompt roles (embedding/image); chat/plan/review/etc. stay governed.
    """
    a = args or {}
    op = (a.get("op") or "list").strip()
    _OPS = {"register", "list", "assign_role", "revoke", "dispatch"}
    if op not in _OPS:
        return _refused(f"op must be one of {sorted(_OPS)} (got {op!r})")
    try:
        import json as _json
        import uuid as _uuid
        from datetime import datetime as _dt, timezone as _tz
        from server import brain_service
        from server.vault import api as vault_api
        from server.vault import authz as vault_authz
    except Exception as e:
        return _refused_if_caller(e, f"connect_compute unavailable: {e}")
    pool = brain_service.get_pool()
    if pool is None:
        return {"status": "error", "result": "connect_compute failed: pool unavailable"}
    eid = brain_service._entity_id
    actor = f"connect_compute:{eid}"

    async def _load_bp() -> dict:
        row = await pool.fetchrow(
            "SELECT behavioral_params FROM entity_registry WHERE id=$1", eid)
        bp = (row and row["behavioral_params"]) or {}
        if isinstance(bp, str):
            try:
                bp = json.loads(bp)
            except Exception:
                bp = {}
        return bp if isinstance(bp, dict) else {}

    async def _save_bp(bp: dict) -> None:
        await pool.execute(
            "UPDATE entity_registry SET behavioral_params=$1::jsonb WHERE id=$2",
            _json.dumps(bp), eid)

    try:
        if op == "list":
            bp = await _load_bp()
            conns = await _compute_connections(bp)
            # Strip nothing secret is here — cred_name is a vault pointer, not a value.
            return {"status": "ok", "result": {"connections": conns, "count": len(conns)}}

        if op == "register":
            kind = (a.get("kind") or "").strip()
            if kind not in _COMPUTE_KINDS:
                return _refused(f"kind must be one of {sorted(_COMPUTE_KINDS)}")
            label = (a.get("label") or kind).strip()
            conn_id = f"cmp_{_uuid.uuid4().hex[:12]}"
            entry: dict = {
                "id": conn_id, "kind": kind, "label": label,
                "created_at": _dt.now(_tz.utc).isoformat(),
            }
            cred_name = None
            if kind == "local":
                base_url = (a.get("base_url") or "").strip()
                if not (base_url.startswith("http://") or base_url.startswith("https://")):
                    return _refused("local kind requires base_url (http(s) endpoint)")
                entry["base_url"] = base_url
                token = a.get("token")
                if token:
                    cred_name = f"compute:{conn_id}"
                    await vault_api.store_secret(
                        pool, entity_id=eid, name=cred_name, cred_type="compute_token",
                        plaintext=str(token).encode("utf-8"), actor=actor)
                    entry["cred_name"] = cred_name
            else:  # runpod
                endpoint_id = (a.get("endpoint_id") or "").strip()
                api_key = a.get("api_key")
                if not endpoint_id:
                    return _refused("runpod kind requires endpoint_id")
                if not api_key:
                    return _refused("runpod kind requires api_key (sealed in the vault)")
                entry["endpoint_id"] = endpoint_id
                # RunPod serverless base — the BATCH endpoint (NOT a chat path).
                entry["base_url"] = f"https://api.runpod.ai/v2/{endpoint_id}"
                entry["batch_only"] = True
                cred_name = f"runpod:{conn_id}"
                await vault_api.store_secret(
                    pool, entity_id=eid, name=cred_name, cred_type="runpod_api_key",
                    plaintext=str(api_key).encode("utf-8"), actor=actor)
                entry["cred_name"] = cred_name

            bp = await _load_bp()
            conns = await _compute_connections(bp)
            conns.append(entry)
            bp["compute_connections"] = conns
            await _save_bp(bp)
            return {"status": "ok", "result": {"registered": conn_id, "kind": kind,
                                               "base_url": entry.get("base_url"),
                                               "sealed_credential": cred_name is not None}}

        if op == "assign_role":
            connection_id = (a.get("connection_id") or "").strip()
            role = (a.get("role") or "").strip()
            if not connection_id or not role:
                return _refused("connection_id and role are required for assign_role")
            bp = await _load_bp()
            conns = await _compute_connections(bp)
            conn = next((c for c in conns if c.get("id") == connection_id), None)
            if conn is None:
                return _refused(f"connection not found: {connection_id}")
            # LEAK GUARD: a BYO base_url endpoint may only serve a non-prompt role.
            # A 'local' kind (the host's own governed Ollama) may also serve any
            # role per provider_allowed_for_role; here we keep assign_role to the
            # non-prompt batch roles to confine the system prompt regardless of kind.
            from mastercode.inference_config import provider_allowed_for_role
            provider = "local" if conn.get("kind") == "local" else "self"
            if role not in _COMPUTE_BATCH_ROLES or not provider_allowed_for_role(provider, role):
                return _refused(f"role '{role}' can't carry a BYO compute endpoint: "
                                   "a prompt-bearing role would stream the system prompt to a "
                                   "user-controlled host (leak protection). Allowed: "
                                   f"{sorted(_COMPUTE_BATCH_ROLES)}.")
            # Embedding is configured through its own store + re-embed flow. Route
            # the BYO endpoint via apply_embedding_switch so the dim is validated
            # against a real storage column and a re-embed is enqueued.
            if role == "embedding":
                from server.routes.embedding import apply_embedding_switch
                emodel = (a.get("model") or conn.get("label") or "byo-embed").strip()
                edim = a.get("dim") or conn.get("dim")
                res = await apply_embedding_switch(
                    pool, eid, model=emodel, provider=provider,
                    base_url=conn.get("base_url"),
                    dim=int(edim) if edim else None,
                    cred_name=conn.get("cred_name"))
                if isinstance(res, dict) and res.get("error"):
                    return {"status": "error", "result": f"assign embedding failed: {res['error']}"}
                return {"status": "ok", "result": {"assigned": connection_id, "role": "embedding",
                                                   "base_url": conn.get("base_url"), **(res or {})}}
            else:
                # New route shape: {provider, model, base_url,
                # connection_id} — the legacy lane/model_id keys are dead.
                # normalize_provider validates + canonicalizes (a BYO 'self'
                # endpoint rides as 'openrouter'; the image bot dials base_url
                # directly and never reads provider).
                from mastercode.inference_config import normalize_provider
                routing = bp.get("model_routing") or {}
                rentry = routing.get(role) or {}
                _model = (a.get("model") or rentry.get("model")
                          or rentry.get("model_id") or conn.get("label") or "byo").strip()
                _prov, _model = normalize_provider(provider, _model)
                if not _prov:
                    return _refused(f"provider for connection {connection_id} is not "
                                       "routable — pick a Keys provider or a local endpoint.")
                routing[role] = {
                    "provider": _prov,
                    "model": _model,
                    "base_url": conn.get("base_url"),
                    "connection_id": connection_id,
                }
                bp["model_routing"] = routing
                # On the ledger like every other write of this table
                # (v158): a BYO endpoint on a batch role, set by the host.
                # Confined to _COMPUTE_BATCH_ROLES and it mints no approval.
                try:
                    from server.routes.inference import _log_route_apply
                    await _log_route_apply(pool, eid, role, routing[role], "host", None)
                except Exception as _le:  # noqa: BLE001
                    log.debug("model_route_log (assign_role) skipped: %s", _le)
            await _save_bp(bp)
            return {"status": "ok", "result": {"assigned": connection_id, "role": role,
                                               "base_url": conn.get("base_url")}}

        if op == "revoke":
            connection_id = (a.get("connection_id") or "").strip()
            if not connection_id:
                return _refused("connection_id is required for revoke")
            bp = await _load_bp()
            conns = await _compute_connections(bp)
            conn = next((c for c in conns if c.get("id") == connection_id), None)
            if conn is None:
                return _refused(f"connection not found: {connection_id}")
            if conn.get("cred_name"):
                try:
                    await vault_api.revoke_secret(pool, entity_id=eid, name=conn["cred_name"], actor=actor)
                except Exception:
                    pass
            bp["compute_connections"] = [c for c in conns if c.get("id") != connection_id]
            await _save_bp(bp)
            return {"status": "ok", "result": {"revoked": connection_id}}

        # op == "dispatch" — BYO RunPod BATCH run. The api key NEVER reaches the
        # agent: the brokered http_call opens the sealed key in-pod, injects it as
        # Bearer, and returns only the response. BYO = the platform does not
        # bill inference, so nothing is charged here.
        connection_id = (a.get("connection_id") or "").strip()
        if not connection_id:
            return _refused("connection_id is required for dispatch")
        bp = await _load_bp()
        conns = await _compute_connections(bp)
        conn = next((c for c in conns if c.get("id") == connection_id), None)
        if conn is None:
            return _refused(f"connection not found: {connection_id}")
        if conn.get("kind") != "runpod":
            return _refused("dispatch is only for runpod (BYO batch) connections")
        cred_name = conn.get("cred_name")
        if not cred_name:
            return _refused("runpod connection has no sealed api key")
        run_input = a.get("input")
        if run_input is None:
            return _refused("dispatch requires 'input' (the RunPod job payload)")
        try:
            result = await vault_authz.use_credential(
                pool, entity_id=eid, name=cred_name, action="http_call",
                request={
                    "url": f"{conn['base_url']}/run",
                    "method": "POST",
                    "json": {"input": run_input},
                    "auth_scheme": "bearer",
                },
                actor=actor)
        except vault_authz.VaultAuthzError as e:
            return _refused(f"runpod dispatch refused: {e}")
        return {"status": "ok", "result": {"connection_id": connection_id,
                                           "byo_billing": "egress_only",
                                           "response": result}}
    except Exception as e:
        return _refused_if_caller(e, f"connect_compute failed: {getattr(e, 'detail', None) or e}")


async def _exec_list_skills(args, *, entity_id: int | None = None, pool=None):
    """List the Host's skills: its OWN skills first (host_skills, migrations/
    v207 — written with context(action='write', path='skills/<name>') or in
    the Skills app), then the platform's skill files on disk. Each is marked
    by author ('host', 'person' or 'platform'); a Host skill carries its
    version and whether it is active or retired. Read-only."""
    try:
        from mastercode.runtime import skill_loader
        out = []
        if pool is not None and entity_id is not None:
            from mastercode.runtime import host_skills
            for d in await host_skills.list_skills(pool, entity_id):
                out.append({
                    "name": d["name"],
                    "description": d["description"],
                    "chars": d["size"],
                    "allowed_tools": d["allowed_tools"],
                    "author": d["author"],
                    "version": d["version"],
                    "versions": int(d.get("versions") or 1),
                    "status": d["status"],
                    "path": f"skills/{d['name']}",
                    **({"untrusted": d["untrusted"]} if d.get("untrusted") else {}),
                })
            # A skill written in a turn that read untrusted content marks the
            # turn its description is listed into (host_skills, v232).
            from mastercode.runtime import turn_taint as _turn_taint
            _turn_taint.mark_rows(out, "a skill listed with list_skills")
        loc = skill_loader.get_location()
        skills = skill_loader.list_skills()
        for s in skills:
            try:
                size = s.path.stat().st_size
            except OSError:
                size = None
            out.append({
                "name": s.name,
                "description": s.description,
                "size_bytes": size,
                "allowed_tools": s.allowed_tools,
                "author": "platform",
                "path": f"default-skills/{s.name}",
            })
        return {"status": "ok", "result": {"skills": out, "location": str(loc), "count": len(out)}}
    except Exception as e:
        return _refused_if_caller(e, f"list_skills failed: {getattr(e, 'detail', None) or e}")


async def _exec_publish_site(args: dict) -> dict:
    """One-click "Publish as site" (Sites Funnel batch 3): zip a Workbench
    project's built web output SERVER-SIDE and publish it to the public webapp
    zone via the caller-scoped webapp.publish_bundle op — the same service the
    Workbench UI button calls (server.routes.applications.publish_site_service).
    The controller annotates the HTML for live-edit and signs; a NEW site goes
    live public, and its owner sets other visibility in Sites."""
    from server import brain_service
    from server.routes.applications import (
        PublisherError, ShipError, publish_site_repo_service, publish_site_service)
    a = args or {}
    slug = (a.get("slug") or "").strip().lower()
    if not slug:
        return _refused("slug is required (site label — becomes <slug>.<zone>)")
    repo = (a.get("repo") or "").strip()
    if repo and a.get("project_id") is not None:
        return _refused("pass EITHER project_id (Workbench project) OR repo (owner/name on this host's gitea), not both")
    try:
        if repo:
            res = await publish_site_repo_service(
                repo=repo, slug=slug, ref=(a.get("ref") or "").strip())
            return {"status": "ok", "result": res}
        if a.get("project_id") is None:
            return _refused("project_id or repo is required")
        try:
            pid = int(a.get("project_id"))
        except (TypeError, ValueError):
            return _refused("project_id must be an integer")
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "publish_site failed: pool unavailable"}
        res = await publish_site_service(pool, pid, slug=slug, module=(str(a.get("module") or "").strip().lower() or None))
        return {"status": "ok", "result": res}
    except (ShipError, PublisherError) as e:
        return _refused_if_caller(e, f"publish_site failed: {e.detail}")
    except Exception as e:
        return _refused_if_caller(e, f"publish_site failed: {getattr(e, 'detail', None) or e}")


async def _exec_publish_app(args: dict) -> dict:
    """Manage the host's OWN published App-Store apps. Op-dispatch over the publisher
    proxy SERVICE (server.routes.applications.publisher_op_service) — calls the caller-
    scoped bridge ops directly (no HTTP shim, no @router fn). The bridge fixes the
    publisher from its mTLS cert, so the host can only ever read its OWN books / set
    its OWN prices / yank its OWN versions. Ops:
      my_apps   -> appstore.publisher.my_apps   (no args)
      sales     -> appstore.publisher.sales     (optional app_id, limit)
      set_price -> appstore.publisher.set_price (app_id, price_micros;
                   platform_fee_bps is platform-owned and not settable)
      yank      -> appstore.yank_version        (app_id, version; optional reason)
      agreement -> appstore.agreement           (no args) — the publishing
                   agreement text + version; present it to the USER before
                   any publish and only proceed on their explicit yes
      requests  -> appstore.publish_requests    (no args) — this publisher's
                   review-queue requests (status/reason)
      publish   -> publish_project_service      (project_id; agreement_version
                   REQUIRED [the version the user accepted]; optional
                   price_micros [must be 0 — store is free at launch],
                   audience, summary, version, fork_policy open|closed) —
                   packs + signs a Workbench project (any state except a
                   build in flight) and SUBMITS it to the review queue:
                   every publish is human-reviewed before it appears, so
                   success is a pending request, not a live listing. THIS
                   is the host's publish lane; the Publisher app's Publish
                   tab is the hand-upload alternative for a zip the user
                   already has."""
    a = args or {}
    op = (a.get("op") or "").strip()
    _OPS = {"my_apps", "sales", "set_price", "yank", "publish",
            "agreement", "requests"}
    if op not in _OPS:
        return _refused(f"op must be one of {sorted(_OPS)} (got {op!r}).")

    # publish: pack+sign a Workbench project (any state except a build in flight)
    # and SUBMIT it to the App Store review queue (every publish is human-
    # reviewed before it appears — the result is a pending request, not a
    # published row). Shares the validate→pack→sign with ship_project_app;
    # submits via the caller-scoped bridge op. agreement_version is the
    # publishing-agreement version the USER explicitly accepted (op='agreement'
    # fetches the text) — the store refuses a publish without it.
    if op == "publish":
        from server import brain_service
        from server.routes.applications import publish_project_service, ShipError
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "publish_app failed: pool unavailable"}
        if a.get("project_id") is None:
            return _refused("project_id is required for op='publish'")
        try:
            pid = int(a.get("project_id"))
        except (TypeError, ValueError):
            return _refused("project_id must be an integer")
        price_micros = 0
        if a.get("price_micros") is not None:
            try:
                price_micros = int(a.get("price_micros"))
            except (TypeError, ValueError):
                return _refused("price_micros must be an integer")
        audience = (a.get("audience") or "public").strip()
        if audience not in ("public", "internal", "circle"):
            return _refused("audience must be 'public', 'internal' or 'circle'")
        # A circle app is gated on a GROUP ROSTER, so the group is not optional,
        # and it is refused HERE rather than at the platform: a publish uploads
        # a bundle, and discovering a missing field after the upload wastes the
        # whole round trip. That the group must be one this host OWNS is checked
        # in appstore_circle.record_publication, which is the only place that
        # can know, and which the publish service calls.
        group_ref = (a.get("group_ref") or "").strip()
        if audience == "circle" and not group_ref:
            return _refused("audience 'circle' needs group_ref — the group whose "
                              "roster may see and fetch this app. List your groups "
                              "with GET /api/groups.")
        if group_ref and audience != "circle":
            return _refused("group_ref only applies to audience 'circle'")
        agreement_version = None
        if a.get("agreement_version") is not None:
            try:
                agreement_version = int(a.get("agreement_version"))
            except (TypeError, ValueError):
                return _refused("agreement_version must be an integer")
        fork_policy = (a.get("fork_policy") or "open").strip()
        if fork_policy not in ("open", "closed"):
            return _refused("fork_policy must be 'open' or 'closed' "
                              "('invited' arrives with the circles build)")
        try:
            res = await publish_project_service(
                pool, pid, price_micros=price_micros, audience=audience,
                summary=a.get("summary"), version=a.get("version"),
                agreement_version=agreement_version, fork_policy=fork_policy,
                group_ref=group_ref or None, module=(str(a.get("module") or "").strip().lower() or None))
            return {"status": "ok", "result": res}
        except ShipError as e:
            return _refused_if_caller(e, f"publish failed: {e.detail}")
        except Exception as e:
            return _refused_if_caller(e, f"publish failed: {getattr(e, 'detail', None) or e}")

    try:
        from server.routes.applications import publisher_op_service, PublisherError
    except Exception as e:
        return _refused_if_caller(e, f"publish_app unavailable: {e}")

    if op == "my_apps":
        bridge_op, params = "appstore.publisher.my_apps", {}
    elif op == "agreement":
        bridge_op, params = "appstore.agreement", {}
    elif op == "requests":
        bridge_op, params = "appstore.publish_requests", {}
    elif op == "sales":
        bridge_op, params = "appstore.publisher.sales", {}
        app_id = (a.get("app_id") or "").strip()
        if app_id:
            params["app_id"] = app_id
        if a.get("limit") is not None:
            try:
                params["limit"] = int(a.get("limit"))
            except (TypeError, ValueError):
                return _refused("limit must be an integer")
    elif op == "set_price":
        app_id = (a.get("app_id") or "").strip()
        if not app_id:
            return _refused("app_id is required for op='set_price'")
        if a.get("price_micros") is None:
            return _refused("price_micros is required for op='set_price'")
        try:
            price_micros = int(a.get("price_micros"))
        except (TypeError, ValueError):
            return _refused("price_micros must be an integer")
        if a.get("platform_fee_bps") is not None:
            # Platform-owned (10% standard) — the bridge
            # rejects it; fail fast here with the same message.
            return _refused("platform_fee_bps is platform-owned")
        params = {"app_id": app_id, "price_micros": price_micros}
        bridge_op = "appstore.publisher.set_price"
    else:  # yank
        app_id = (a.get("app_id") or "").strip()
        version = (a.get("version") or "").strip()
        if not app_id or not version:
            return _refused("app_id and version are required for op='yank'")
        params = {"app_id": app_id, "version": version}
        reason = (a.get("reason") or "").strip()
        if reason:
            params["reason"] = reason
        bridge_op = "appstore.yank_version"

    try:
        res = await publisher_op_service(bridge_op, params)
        return {"status": "ok", "result": res}
    except PublisherError as e:
        return _refused_if_caller(e, f"publish_app failed: {e.detail}")
    except Exception as e:
        return _refused_if_caller(e, f"publish_app failed: {getattr(e, 'detail', None) or e}")


async def _exec_ship_project_app(args: dict) -> dict:
    """Ship a Workbench project: pack it into a signed .cseries bundle, sign it
    with this host's entity key, and install it onto the host. Calls the
    ship_project_service directly (no HTTP shim, no @router fn) — EVERY security
    invariant lives in the service: any project state ships except a build in
    flight (shippability is a property of the TREE; unfinished phases surface as
    open_phases), its app.yaml must declare provenance=custom, it passes the
    build-contract validator (static analysis + api conformance — NO runtime.kind
    restriction here: custom apps may declare process/external; the
    static-or-helper bar is the STORE's, in validate_publish), and the sign-time
    App-SDK integrity gate must hold (a poisoned validator cannot certify
    apps). Returns the installed app (id, name, version, provenance) + bundle size."""
    a = args or {}
    if a.get("project_id") is None:
        return _refused("project_id is required")
    try:
        project_id = int(a.get("project_id"))
    except (TypeError, ValueError):
        return _refused("project_id must be an integer")
    try:
        from server import brain_service
        from server.routes.applications import ship_project_service, ShipError
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "ship_project_app failed: pool unavailable"}
        # A change the code review blocked is the user's to accept; the host
        # installing it on a chat word would skip the one step that releases
        # it. The user's own Install button stays theirs.
        _hold = await _active_review_hold(pool, project_id)
        if _hold is not None:
            return _refused(f"not installed: {_review_hold_reason(_hold)}. The user can also "
                "press Install on the project themselves.")
        # …and so is a tree the project's CI (gitea-actions) has not passed.
        _ci_held, _ = await _ci_merge_gate(pool, project_id)
        if _ci_held:
            return _refused(f"not installed: {_ci_held}. The user can also press Install on the "
                "project themselves.")
        res = await ship_project_service(pool, project_id, module=(str(a.get("module") or "").strip().lower() or None))
        return {"status": "ok", "result": res}
    except Exception as e:
        # ShipError carries .detail; other exceptions fall back to str.
        return _refused_if_caller(e, f"ship_project_app failed: {getattr(e, 'detail', None) or e}")


async def _exec_artifact(args: dict) -> dict:
    """Build and manage the host's ARTIFACTS — disposable, lightweight LIVE builds.

    An artifact is DISTINCT from an app and from a project: it lives in a
    project-style workspace (/var/lib/cseries/projects/<id>) but is NOT bound to the
    App SDK until the host converts it. It is fast, in-pod, and disposable —
    write some HTML/JS/CSS, see it render live, throw it away, OR convert it to a
    real app. Calls the artifact SERVICE directly (server.applications.artifacts),
    so every invariant (entity-scope, kind='artifact', workspace jail, the App-SDK
    convert handoff) lives in ONE place. Ops:
      create  -> new artifact (name; optional files=[{path,content}], entry,
                 description, kind). kind='desktop' with NO files SEEDS the entry
                 from the platform's desktop template (desktop_contract.TEMPLATE_HTML)
                 server-side — the kernel copies it, the model never retypes it
                 (switching a shell is an op, not an LLM rewrite).
      write   -> write/overwrite files in an artifact (artifact_id + files). On
                 the WORN desktop the new render is loaded in a browser first
                 (server/applications/desktop_pin.py): `desktop.advanced` false
                 = it does not render and the screen kept the last good one.
      render  -> the live build, a self-contained HTML doc (artifact_id; optional entry)
      list    -> the host's artifacts (optional limit)
      convert -> turn an artifact into an app via the App SDK (artifact_id; needs a
                 provenance=custom app.yaml written first via set_project_manifest)
      delete  -> dispose of an artifact (artifact_id)
      history -> the artifact's change history, newest first (artifact_id)
      revert  -> restore a past revision (artifact_id + rev; the restore is
                 itself recorded, so a revert is always revertable)
      set_desktop -> make an artifact THE DESKTOP (artifact_id; optional entry):
                 the shell renders it full-screen under the windows and keeps it
                 live on every write; omit artifact_id to restore the default
                 wallpaper. The document's
                 <meta name="cseries-tokens"> declares the --cseries-* tokens the
                 shell and every app then follow (design_tokens.py grammar).
                 REFUSED (422 report) when the document misses the desktop
                 floor (server/applications/desktop_contract.py) or fails the
                 browser render check (server/applications/desktop_render.py:
                 an uncaught error with its line, nothing painted, no tiles or
                 bar where declared). No browser to ask → set anyway, with a
                 NOT RENDER-CHECKED warning in the result.
      set_wallpaper -> wear one of the host's own images (image_url
                 '/api/images/<id>': image_generate made it, or an app such as
                 Blender Engine rendered it) as the custom wallpaper, desktop or
                 `variant` mobile, through the Settings upload's own writer
                 (server/routes/appearance.py set_wallpaper_from_image). Takes
                 off an HTML desktop that was worn; set_desktop puts it back.
      promote -> copy one root file over the entry, server-side, as ONE revision
                 (artifact_id + from; optional to='index.html'). The variant pick.
                 Never re-emit a file to copy it — this is the copy.
      import  -> copy files from another of the host's project workspaces into
                 the artifact (artifact_id + project_id + files=[{from, to?}]),
                 server-side, one revision. A landed build becomes a live
                 artifact without a model retyping it.
      publish_design -> put a desktop on the Designs shelf ("send it to the
                 design app"): name + optional artifact_id
                 (default: the desktop being worn). The kernel renders it,
                 checks the floor and the browser render check (no browser to
                 ask → NOT published); the PLATFORM picks the shelf — the house
                 shelf everyone sees for the platform's own hosts, the
                 account's shelf for everyone else (server/routes/designs.py).
      desktop_from_url -> "make my desktop look like <site>" (the old
                 website-to-template lane as a tool): url +
                 optional name. The kernel fetches the page and up to four of
                 its stylesheets (url_reader.fetch_raw — the governed egress
                 path, internal hosts refused), reads the site's background,
                 text, accent and fonts with NO model (site_style), and creates
                 a desktop artifact from the template in that palette — an
                 operation, never a retype. Returns artifact_id, the tokens,
                 what it observed, and the floor's verdict. Not set as the
                 desktop: refine it, then set_desktop.
    Every create/write/promote/import whose entry is HTML attaches `contract` —
    the floor's verdict, with `trigger` saying why it is being told — whenever
    the document could be a desktop, so a REFUSED design is fixed in the same
    turn instead of being discovered by the user. See _attach_desktop_contract
    for the three triggers; create used to be excluded entirely, which is how
    an artifact was written with no meta and no tokens and reported
    to the user as live.
    """
    a = args or {}
    op = (a.get("op") or "create").strip()
    if op not in ("create", "write", "render", "list", "convert", "delete",
                  "history", "revert", "set_desktop", "set_wallpaper", "promote", "import",
                  "publish_design", "desktop_from_url"):
        return _refused(f"op must be one of create/write/render/list/convert/delete/history/revert/set_desktop/set_wallpaper/promote/import/publish_design/desktop_from_url (got {op!r})")
    try:
        from server import brain_service
        from server.applications import artifacts as artifact_service
        from server.applications.artifacts import ArtifactError
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "artifact failed: pool unavailable"}
        eid = brain_service._entity_id
        try:
            if op == "create":
                entry = a.get("entry") or "index.html"
                kind = str(a.get("kind") or "artifact").strip().lower()
                files = a.get("files")
                if kind == "desktop" and not files:
                    # Seed from the template as an OPERATION. The alternative is
                    # the model retyping a 20 KB document it was handed in its
                    # own skill, which is both the slow path and the one that
                    # loses the mode meta and the tokens on the way through.
                    from server.applications.desktop_contract import TEMPLATE_HTML
                    files = [{"path": entry, "content": TEMPLATE_HTML}]
                name = str(a.get("name") or "").strip()
                description = str(a.get("description") or "")
                name_defaulted = False
                if not name:
                    # A missing name is clerical, not a reason to refuse. The
                    # schema marks only `op` required (a JSON schema cannot say
                    # "required for create"), so the model learned at execution
                    # what the schema never said and retried. The kernel names the artifact itself — from
                    # the description, else the kind and the date — inside a
                    # SUBSET of the name rule's character class, checked against
                    # the rule itself, and says so in the result.
                    import re as _re
                    from datetime import datetime as _dt, timezone as _tz
                    cand = " ".join(_re.sub(r"[^\w .,()\-'’]", " ", description).split())
                    cand = cand[:60].strip(" .,-")
                    if not cand or not artifact_service.is_valid_artifact_name(cand):
                        cand = (f"{'Desktop' if kind == 'desktop' else 'Artifact'} "
                                f"{_dt.now(_tz.utc).strftime('%Y-%m-%d %H:%M')}")
                    name = cand
                    name_defaulted = True
                res = await artifact_service.create_artifact(
                    pool, eid,
                    name=name,
                    files=files,
                    entry=entry,
                    description=description)
                if name_defaulted and isinstance(res, dict):
                    res["name_defaulted"] = True
                # words_known: on create the name and description ARE the
                # call's own arguments, so the projects read below is pure
                # waste — every ordinary create would pay for a row it already
                # holds.
                await _attach_desktop_contract(
                    pool, eid, (res or {}).get("artifact_id"), res, entry=entry,
                    kind=kind, name=name, description=description,
                    words_known=True)
                await _note_missing_images(pool, eid, files, res)
            elif op == "write":
                # A write to the WORN desktop is checked in a browser before it
                # reaches the screen (desktop_pin.after_write); the Host waits
                # for that verdict, so the error and its line come back in
                # this result (`desktop`) and get fixed in the same turn.
                from server.applications.desktop_pin import HOST_WAIT_S
                res = await artifact_service.write_files(
                    pool, eid, a.get("artifact_id"), a.get("files") or [],
                    desktop_wait_s=HOST_WAIT_S)
                await _attach_desktop_contract(pool, eid, a.get("artifact_id"), res)
                await _note_missing_images(pool, eid, a.get("files"), res)
            elif op == "promote":
                from server.applications.desktop_pin import HOST_WAIT_S
                res = await artifact_service.promote_entry(
                    pool, eid, a.get("artifact_id"), str(a.get("from") or ""),
                    str(a.get("to") or "index.html"), actor="host",
                    desktop_wait_s=HOST_WAIT_S)
                await _attach_desktop_contract(pool, eid, a.get("artifact_id"), res,
                                               entry=str(a.get("to") or "index.html"))
            elif op == "import":
                from server.applications.desktop_pin import HOST_WAIT_S
                res = await artifact_service.import_files(
                    pool, eid, a.get("artifact_id"), a.get("project_id"),
                    a.get("files") or [], actor="host", desktop_wait_s=HOST_WAIT_S)
                await _attach_desktop_contract(pool, eid, a.get("artifact_id"), res)
                # The copies are new content in the artifact, as a write's
                # files are, so the image names they carry are checked the same
                # way. They are not in the call's arguments: read them back.
                try:
                    copied = [{"content": t} for t in artifact_service.workspace_texts(
                        a.get("artifact_id"),
                        [c.get("to") for c in ((res or {}).get("files") or [])
                         if isinstance(c, dict)])]
                except Exception:  # noqa: BLE001 - a note, never the import's failure
                    copied = []
                await _note_missing_images(pool, eid, copied, res)
            elif op == "render":
                html = await artifact_service.render(
                    pool, eid, a.get("artifact_id"), a.get("entry", "index.html"))
                res = {"artifact_id": a.get("artifact_id"), "html": html}
            elif op == "list":
                res = await artifact_service.list_artifacts(
                    pool, eid, limit=a.get("limit", 50), offset=a.get("offset", 0))
            elif op == "convert":
                res = await artifact_service.convert_to_app(pool, eid, a.get("artifact_id"))
            elif op == "history":
                # Every revision is kept: a page of them, newest first,
                # with total + next_offset for the rest.
                res = await artifact_service.list_history(
                    pool, eid, a.get("artifact_id"),
                    limit=a.get("limit") or 50, offset=a.get("offset", 0))
            elif op == "revert":
                from server.applications.desktop_pin import HOST_WAIT_S
                res = await artifact_service.revert_artifact(
                    pool, eid, a.get("artifact_id"), str(a.get("rev") or ""),
                    actor="host", desktop_wait_s=HOST_WAIT_S)
            elif op == "set_desktop":
                # The appearance route module owns the pointer (one writer for
                # PUT /api/appearance/desktop and this op). Lazy import: the
                # route module is not otherwise a runtime dependency here.
                from server.routes.appearance import set_desktop_artifact
                res = await set_desktop_artifact(
                    pool, eid, a.get("artifact_id"), a.get("entry") or "index.html")
            elif op == "set_wallpaper":
                from server.routes.appearance import set_wallpaper_from_image
                res = await set_wallpaper_from_image(
                    pool, eid, a.get("image_url"), a.get("variant") or "desktop")
            elif op == "desktop_from_url":
                res = await _desktop_from_url(pool, eid, str(a.get("url") or ""),
                                              str(a.get("name") or "").strip())
                if res.get("error"):
                    return {"status": "error", "result": res["error"]}
            elif op == "publish_design":
                # One publish path with the Designs app's button (name rule,
                # size ceiling, the floor). HTTPException carries its reason.
                from fastapi import HTTPException
                from server.routes.designs import publish_artifact
                aid = a.get("artifact_id")
                try:
                    res = await publish_artifact(
                        pool, int(aid) if aid is not None else None,
                        str(a.get("name") or ""))
                except HTTPException as he:
                    return _refused_if_caller(he, str(he.detail))
            else:  # delete
                res = await artifact_service.delete_artifact(pool, eid, a.get("artifact_id"))
        except ArtifactError as e:
            return _refused_if_caller(e, e.detail)
        return {"status": "ok", "result": res}
    except Exception as e:
        return _refused_if_caller(e, f"artifact failed: {getattr(e, 'detail', None) or e}")


async def _desktop_from_url(pool, eid: int, url: str, name: str) -> dict:
    """artifact op='desktop_from_url' — see the op list on _exec_artifact.
    Every step that can fail says which one, in plain words."""
    from urllib.parse import urljoin, urlsplit
    from mastercode.runtime import url_reader
    from server.applications import artifacts as artifact_service
    from server.applications import site_style
    from server.applications.desktop_contract import check_document, template_with_tokens

    page = await url_reader.fetch_raw(url)
    if not page.get("ok"):
        return {"error": f"could not read {url or 'that address'}: {page.get('error')}"}
    base = page["final_url"]
    # Every linked sheet, in order, until the reader has all the CSS it reads
    # (site_style.MAX_TOTAL_CSS) or the page's fetch backstop; any sheet not
    # read for either reason is named in the answer, never dropped unsaid.
    sheets, skipped, not_read = [], [], []
    css_bytes = fetched = 0
    for href in site_style.stylesheet_urls(page["body"]):
        if css_bytes >= site_style.MAX_TOTAL_CSS or fetched >= site_style.MAX_STYLESHEETS:
            not_read.append(href)
            continue
        fetched += 1
        sheet = await url_reader.fetch_raw(urljoin(base, href))
        if sheet.get("ok"):
            sheets.append(sheet["body"][:site_style.MAX_CSS_BYTES])
            css_bytes += len(sheets[-1])
        else:
            skipped.append(href)
    # Off the event loop: the reading is bounded (site_style caps every input
    # and expansion), but it is CPU work and the pod's HTTP shares this loop.
    import asyncio

    def _read():
        st = site_style.extract(page["body"], sheets)
        return st, site_style.tokens_for(st)

    style, tokens = await asyncio.to_thread(_read)
    host = (urlsplit(base).hostname or "").removeprefix("www.")
    title = name or f"Desktop — {style.get('title') or host}"[:80]
    name_note = None
    if not artifact_service.is_valid_artifact_name(title):
        if name:
            name_note = (f"the name {name!r} has characters an artifact name cannot "
                         "carry, so it was named after the site — rename it if you like")
        title = f"Desktop from {host}"[:80]
    doc = template_with_tokens(tokens, title=title)
    art = await artifact_service.create_artifact(
        pool, eid, name=title,
        files=[{"path": "index.html", "content": doc}],
        description=f"Desktop in the palette of {base}")
    report = check_document(doc)
    return {
        "artifact_id": art.get("artifact_id"),
        "name": title,
        "source": base,
        "stylesheets_read": len(sheets),
        "stylesheets_unreadable": skipped,
        **({"stylesheets_not_read": not_read,
            "stylesheets_note": (f"{len(not_read)} more stylesheet(s) were not read: the "
                                 f"reader had its {site_style.MAX_TOTAL_CSS:,} bytes of CSS, "
                                 f"or the page's {site_style.MAX_STYLESHEETS} fetches")}
           if not_read else {}),
        "taken_from_the_site": {
            "background": style.get("background"), "text": style.get("text"),
            "accent": style.get("accent"), "font_body": style.get("font_body"),
            "font_display": style.get("font_display"),
        },
        "observed": style.get("observed"),
        "tokens": tokens,
        "contract": {"ok": report["ok"], "errors": report["errors"], "warnings": report["warnings"]},
        **({"name_note": name_note} if name_note else {}),
        "next": ("It is NOT the desktop yet. Show it (open_app artifacts, view "
                 "artifact:<id>), refine the design with the user via op='write', then "
                 "op='set_desktop'. Anything taken_from_the_site left null used a "
                 "readable neutral — say so."),
    }


# A name or description that says what the artifact is for. The whole point of
# this trigger is the document that IGNORES the floor: it declares no mode and
# no tokens, so nothing in the bytes says "desktop" and only the host's own
# words do.
_DESKTOP_WORD_RE = re.compile(r"desktop|wallpaper", re.IGNORECASE)


def _is_html_entry(entry: str) -> bool:
    return str(entry or "").strip().lower().endswith((".html", ".htm"))


async def _artifact_words(pool, eid: int, artifact_id) -> str:
    """The artifact's own name + description, for the trigger below. Read only
    when the cheaper signals have already said no, so an ordinary write pays
    nothing for it. Best-effort: an unreadable row just means no trigger."""
    try:
        row = await pool.fetchrow(
            "SELECT name, description FROM projects "
            "WHERE id = $1 AND entity_id = $2 AND kind = 'artifact'",
            int(artifact_id), eid)
    except Exception as e:  # noqa: BLE001 — never fail a write on a lookup
        log.debug("artifact name lookup skipped: %s", e)
        return ""
    if row is None:
        return ""
    return f"{row['name'] or ''} {row['description'] or ''}"


def _prospect_report(report: dict) -> str:
    """The NAME-triggered wording. Nothing was refused here: the host called
    something "desktop" and the kernel is pointing out that the document is not
    one yet. Saying "REFUSED" for that is a lie about what happened, and it
    trains the host to read a real refusal as noise."""
    lines = ["Not a desktop document — nothing was refused, and this artifact is "
             "fine as it is."]
    if report.get("errors"):
        lines.append("If it is meant to BE the desktop, it still needs:")
        lines += [f"  · {e}" for e in report["errors"]]
    lines.append("Or create it with kind='desktop' to start from the template "
                 "(default-skills/desktop.md).")
    return "\n".join(lines)


async def _note_missing_images(pool, eid, files, res) -> None:
    """An artifact may name the Host's own images by /api/images/<id>
    (artifacts.inline_own_images puts them in when it renders). A name that is
    not one of them renders as a broken image, silently, so the write's result
    says which, in the turn that can fix them. Best-effort."""
    try:
        from server.applications import artifacts as artifact_service
        texts = [str((f or {}).get("content") or "") for f in (files or []) if isinstance(f, dict)]
        missing = await artifact_service.missing_own_images(pool, eid, texts)
    except Exception:  # noqa: BLE001 - a note, never the write's failure
        return
    if missing and isinstance(res, dict):
        res["images_missing"] = {
            "names": missing,
            "note": ("not among your images, so they render as broken images; "
                     "image_generate(action='gallery') lists yours")}


async def _attach_desktop_contract(pool, eid: int, artifact_id, res: dict,
                                   entry: str = "index.html", *, kind=None,
                                   name=None, description=None,
                                   words_known: bool = False) -> None:
    """After a create/write/promote/import: attach the floor's verdict to the
    tool result as `contract` = {ok, mode, errors, warnings, trigger} plus a
    readable `contract_report`. Informational here (iteration must stay live);
    the hard refusal is set_desktop's. Best-effort — never fails the write.

    It attaches when the entry is an HTML document AND one of three triggers
    fires, and `contract.trigger` says WHICH, because the three do not mean the
    same thing:
      · 'declared' — the document declares a mode meta or cseries-tokens. It is
        asking to be a desktop, so the floor's verdict is about it.
      · 'kind'     — created with kind='desktop'. The host said so.
      · 'name'     — only the artifact's name or description says
        desktop/wallpaper. Nothing has been refused: a name is not a claim about
        the bytes, so this one gets _prospect_report's wording and never the
        REFUSED prefix. REFUSED stays for set_desktop and for the two triggers
        above.

    The last two triggers exist because of a real case: an artifact
    was created with no meta and no tokens, so the old declares-something test
    said "ordinary artifact" and stayed silent — and create never called this at
    all. The host got no verdict from either op, never called set_desktop, and
    told the user the desktop was live. A document that ignores the floor
    completely is exactly the one that has to hear about it.

    words_known: the caller already holds the artifact's name and description
    (create passes its own arguments), so the projects read is skipped.
    """
    try:
        if not _is_html_entry(entry) or artifact_id is None:
            return
        from server.routes.appearance import desktop_contract_report
        from server.applications.desktop_contract import format_report
        report = await desktop_contract_report(pool, eid, artifact_id, entry)
        if report is None:
            return  # the entry does not render — the write result already says so
        if report.get("mode") is not None or report.get("tokens"):
            trigger = "declared"
        elif str(kind or "").strip().lower() == "desktop":
            trigger = "kind"
        else:
            words = f"{name or ''} {description or ''}"
            if not _DESKTOP_WORD_RE.search(words) and not words_known:
                words = await _artifact_words(pool, eid, artifact_id)
            if not _DESKTOP_WORD_RE.search(words):
                return  # an ordinary artifact — nothing here is about the desktop
            trigger = "name"
        res["contract"] = dict(
            {k: report[k] for k in ("ok", "mode", "errors", "warnings")},
            trigger=trigger)
        text = _prospect_report(report) if trigger == "name" else format_report(report)
        if text:
            res["contract_report"] = text
    except Exception as e:  # noqa: BLE001
        log.debug("desktop contract report skipped: %s", e)


# The actions keys_manage's op='use' may broker. Mirrors the enum its schema
# advertises (public_tool_registry: action -> ['http_call', 'sign']); pinned
# equal by tests/test_autofill_broker_guard.py so the two cannot drift again.
# 'browser_type' is deliberately ABSENT: typing a saved form entry into a page
# goes through the `autofill` tool, which applies the user's standing grant.
_KEYS_MANAGE_USE_ACTIONS = frozenset({"http_call", "sign"})


async def _exec_keys_manage(args: dict) -> dict:
    """Manage the host's OWN sealed credential vault. Calls the in-process vault
    service (server.vault.api) + the broker (server.vault.authz) DIRECTLY — no HTTP
    shim, no @router fn. The agent NEVER receives raw secret bytes: list returns
    metadata, add seals a value, use brokers an action server-side (the secret stays
    inside the broker), revoke supersedes. There is intentionally NO reveal op —
    revealing a raw key needs the user's TOTP step-up and lives only in the Keys app
    UI (POST /api/vault/secrets/{name}/reveal). Ops:
      list   -> credential metadata (name/type/created)        (no args)
      add    -> seal a new credential                           (name, cred_type, value | value_b64)
      revoke -> supersede a credential                          (name)
      use    -> broker an action, results only                  (name, action, request)

    Sovereign user-owned keys (opt-in; default behavior unchanged): a host
    can seal a credential TO the user. The user's PRIVATE key
    lives only in their mesh, so the host/platform can seal to the user but can
    NEVER reopen it.
      seal_for_user     -> seal a value TO the user (host can't read) (user_id, name, cred_type, value | value_b64)
    REGISTERING the user's public key is NOT a host op: the
    registered key is the recipient of every later seal_for_user and the register
    is an upsert, so a host that could write it could redirect the user's own
    sealed credentials to a key of its choosing. Registration is the user's act —
    POST /api/vault/user-keys with their TOTP step-up (or the backup key wizard
    in Settings for the owner's own key). Tell the user that; do not try it here.
    """
    a = args or {}
    op = (a.get("op") or "list").strip()
    _OPS = {"list", "add", "revoke", "use", "seal_for_user"}
    if op == "register_user_key":
        return {"status": "denied", "result": (
            "register_user_key is not a host op any more: registering a recipient "
            "key decides who can open everything sealed to that user, so it is the "
            "user's own act — POST /api/vault/user-keys with their authenticator "
            "code, or the backup key wizard in Settings for their own key. "
            "seal_for_user still works once a key is registered.")}
    if op not in _OPS:
        return _refused(f"op must be one of {sorted(_OPS)} (got {op!r})")
    if op in ("add", "revoke", "use"):
        # An MCP server's sign-in (server/mcp_oauth.py) is the person's token
        # for that one server: used only by its connection, ended only from
        # the Network app. A `use` would send it to whatever URL the call names.
        from server.mcp_oauth import is_reserved_key_name
        if is_reserved_key_name(a.get("name")):
            return _refused(f"{str(a.get('name')).strip()!r} is an MCP server's sign-in: only that "
                            "server's connection uses it, and the person signs in or out on its card "
                            "in the Network app")
    if op == "use":
        # use brokers a credential to the URL the call names. On a turn that
        # read untrusted content, that URL may be someone else's choice.
        from mastercode.runtime import turn_taint
        why = turn_taint.action_refusal("a credential use (keys_manage op='use')")
        if why is not None:
            return {"status": "denied", "reason": "untrusted_turn", "result": f"Not run: {why}."}
    # Validate the brokered action HERE, with the other input checks and
    # BEFORE any pool/vault work: rejecting a disallowed action needs no
    # database, and a guard that sits behind a dependency is a guard that
    # does not run when the dependency is missing.
    #
    # The schema advertises enum ['http_call', 'sign'] and nothing enforced it,
    # so `action` reached use_credential verbatim — including 'browser_type',
    # the one action with its own consent model (a standing per-site grant, and
    # a rule about where a saved password may be typed), demonstrated end to
    # end. The broker now
    # guards form entries itself (authz._guard_form_entry), so this is the
    # second layer — but a tool whose declared enum is not enforced is its own
    # defect regardless.
    if op == "use":
        _action = (a.get("action") or "").strip()
        if _action and _action not in _KEYS_MANAGE_USE_ACTIONS:
            return _refused(f"action must be one of {sorted(_KEYS_MANAGE_USE_ACTIONS)} "
                f"(got {_action!r}). Typing a saved form entry into a page is "
                f"the `autofill` tool's job — it applies the user's standing "
                f"per-site grant, which this path does not.")
    try:
        from server import brain_service
        from server.vault import api as vault_api
        from server.vault import authz
    except Exception as e:
        return _refused_if_caller(e, f"keys_manage unavailable: {e}")
    pool = brain_service.get_pool()
    if pool is None:
        return {"status": "error", "result": "keys_manage failed: pool unavailable"}
    eid = brain_service._entity_id
    actor = f"keys_manage:{eid}"

    try:
        if op == "list":
            rows = await vault_api.list_secrets(pool, entity_id=eid)
            return {"status": "ok", "result": {"credentials": [
                {"name": r["logical_name"], "cred_type": r["cred_type"],
                 "created_at": r["created_at"].isoformat(),
                 # A deactivated credential is stored but switched off — it
                 # resolves as absent everywhere; flag it, never blend it.
                 "deactivated": bool(r.get("deactivated_at"))} for r in rows]}}

        if op == "add":
            name = (a.get("name") or "").strip()
            if not name:
                return _refused("name is required for op='add'")
            cred_type = (a.get("cred_type") or "opaque").strip()
            if a.get("value_b64"):
                import base64
                try:
                    pt = base64.b64decode(a["value_b64"])
                except Exception:
                    return {"status": "error", "result": "value_b64 is not valid base64"}
            elif a.get("value") is not None:
                pt = str(a.get("value")).encode("utf-8")
            else:
                return _refused("add requires 'value' (text) or 'value_b64'")
            vid = await vault_api.store_secret(
                pool, entity_id=eid, name=name, cred_type=cred_type, plaintext=pt, actor=actor)
            res: dict = {"stored": name, "cred_type": cred_type, "id": vid}
            # Storing a harness credential RECONNECTS it. Same entry point the
            # HTTP route uses — without it, adding a key through the host after
            # a revoke leaves the tombstone in place and the harness stays dead
            # with a perfectly good credential sitting in Keys.
            try:
                from server.network import harness_state
                reconnected = await harness_state.reconnect_for_credential(name)
                if reconnected:
                    res["reconnected"] = reconnected
            except Exception as e:  # pragma: no cover - defensive
                log.warning("keys_manage: reconnect for %r failed: %r", name, e)
            return {"status": "ok", "result": res}

        if op == "revoke":
            name = (a.get("name") or "").strip()
            if not name:
                return _refused("name is required for op='revoke'")
            ok = await vault_api.revoke_secret(pool, entity_id=eid, name=name, actor=actor)
            if not ok:
                return _refused(f"no active credential named {name!r}")
            res = {"revoked": name}
            # Revoking a harness credential DISCONNECTS it. Same entry point the
            # HTTP route uses — without it, revoking through the host left the
            # runtime file on disk and the reconcilers rebuilt it, so the
            # harness kept running and the revoke was cosmetic.
            try:
                from server.network import harness_state
                disconnected = await harness_state.disconnect_for_credential(
                    name, actor=actor)
                if disconnected:
                    res["disconnected"] = disconnected
            except Exception as e:  # pragma: no cover - defensive
                log.warning("keys_manage: disconnect for %r failed: %r", name, e)
            return {"status": "ok", "result": res}

        if op == "seal_for_user":
            # Seal a credential TO the user (sovereign): only the user's private key
            # — held in their mesh — can open it. The host/platform CANNOT reopen it.
            # The user's public key must have been registered by the USER first
            # (POST /api/vault/user-keys, step-up gated) — never by this tool.
            import base64
            user_id = (a.get("user_id") or "").strip()
            name = (a.get("name") or "").strip()
            if not user_id or not name:
                return _refused("user_id and name are required for op='seal_for_user'")
            cred_type = (a.get("cred_type") or "opaque").strip()
            if a.get("value_b64"):
                try:
                    pt = base64.b64decode(a["value_b64"])
                except Exception:
                    return {"status": "error", "result": "value_b64 is not valid base64"}
            elif a.get("value") is not None:
                pt = str(a.get("value")).encode("utf-8")
            else:
                return _refused("seal_for_user requires 'value' (text) or 'value_b64'")
            try:
                vid = await vault_api.seal_for_user(
                    pool, user_id=user_id, name=name, cred_type=cred_type,
                    plaintext=pt, actor=actor)
            except KeyError:
                return _refused(f"no registered public key for user {user_id!r} — the user "
                                   "registers one themselves (POST /api/vault/user-keys with "
                                   "their authenticator code); a host cannot")
            return {"status": "ok", "result": {
                "sealed_for_user": user_id, "name": name, "cred_type": cred_type,
                "id": vid, "host_can_read": False}}

        # op == "use"
        name = (a.get("name") or "").strip()
        action = (a.get("action") or "").strip()
        if not name or not action:
            return _refused("name and action are required for op='use'")
        try:
            result = await authz.use_credential(
                pool, entity_id=eid, name=name, action=action,
                request=a.get("request") or {}, actor=actor)
        except authz.VaultAuthzError as e:
            return _refused(f"use refused: {e}")
        return {"status": "ok", "result": {"name": name, "action": action, "result": result}}
    except Exception as e:
        return _refused_if_caller(e, f"keys_manage failed: {getattr(e, 'detail', None) or e}")


async def _exec_tickets(args: dict, *, agent_grant: int | None = None) -> dict:
    """Triage / escalation-queue op-dispatch for the host — its OWN ticket queue.

    A ticket is the host asking the user to decide something it won't decide on
    its own (a quote, a confidentiality call, an email needing a human reply).
    One tool, several ops over the SAME entity-scoped service the /api/tickets
    routes use (NOT the route handlers) — every read/write is `entity_id = <eid>`,
    so the host only ever touches its own queue:

      list     -> the host's DECISION tickets as summary rows (status/circle/source/
                  limit/offset) — op='get' reads one whole; support is support_list
      get      -> one ticket in full by id
      badges   -> open-ticket counts by circle + grand total (sidebar badges)
      decide   -> resolve an OPEN ticket by picking an option_id (and_similar=True
                  crystallizes a reusable decision pattern); writes the queue
      dismiss  -> close an OPEN ticket without a decision (no pattern); writes the queue
      import   -> bring a ticket bundle the user uploaded into Circles tickets +
                  Workbench phases + one archive document (runtime/ticket_import.py);
                  the Host's own act, never a dispatched agent's (agent_grant)

    The decide/dismiss writes + their entity-scoping + linked-session cleanup live
    in the service, so this tool shares ONE path with the routes.
    """
    a = args or {}
    op = (a.get("op") or "").strip()
    if not op:
        return _refused("op is required (one of: list, get, badges, decide, dismiss, import, "
            "support_open, support_update, support_list, support_get, support_reply, support_close)")
    try:
        from server import brain_service
        from server.routes import tickets as t
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "pool unavailable"}
        eid = brain_service._entity_id

        if op == "list":
            # Decisions only, as summary rows (tickets.ticket_summary): the list
            # finds a ticket, op='get' reads it. Support tickets are support_list.
            res = await t.list_tickets_service(
                pool, eid,
                status_filter=a.get("status"),
                circle_id=(int(a["circle_id"]) if a.get("circle_id") is not None else None),
                source=a.get("source"),
                limit=int(a.get("limit") or 50),
                offset=int(a.get("offset") or 0),
            )
            return {"status": "ok", "result": {
                "tickets": [t.ticket_summary(r) for r in res.get("tickets") or []],
                "offset": res.get("offset"), "next_offset": res.get("next_offset"),
                "note": ("decision tickets only, summarized — op='get' (ticket_id) reads one in "
                         "full; support tickets (drafts included) are op='support_list'"),
            }}

        if op == "badges":
            res = await t.badge_counts_service(pool, eid)
            return {"status": "ok", "result": res}

        if op == "get":
            if a.get("ticket_id") is None:
                return _refused("ticket_id is required for op='get'")
            res = await t.get_ticket_service(pool, eid, int(a["ticket_id"]))
            return {"status": "ok", "result": res}

        if op == "decide":
            if a.get("ticket_id") is None:
                return _refused("ticket_id is required for op='decide'")
            if not a.get("option_id"):
                return _refused("option_id is required for op='decide'")
            res = await t.decide_ticket_service(
                pool, eid, int(a["ticket_id"]),
                option_id=a.get("option_id"),
                and_similar=bool(a.get("and_similar")),
                note=a.get("note", ""),
                pattern_action_class=a.get("pattern_action_class"),
                pattern_conditions=a.get("pattern_conditions"),
                # The HOST is deciding. A ticket locked user_only (a route
                # proposal the host itself filed) is refused here: the host
                # cannot answer its own question and call it the user's.
                actor="host",
            )
            return {"status": "ok", "result": res}

        if op == "dismiss":
            if a.get("ticket_id") is None:
                return _refused("ticket_id is required for op='dismiss'")
            # actor='host' below: a user_only ticket (the host's own route
            # proposal) cannot be withdrawn by the host either.
            res = await t.dismiss_ticket_service(
                pool, eid, int(a["ticket_id"]), note=a.get("note", ""), actor="host",
            )
            return {"status": "ok", "result": res}

        if op == "import":
            from mastercode.runtime import ticket_import as _ti
            return await _ti.run(a, pool=pool, entity_id=int(eid), agent_grant=agent_grant)

        # ── Support half (server/routes/support.py): platform-help tickets.
        # support_open only DRAFTS — the user approves the shared context in the
        # Tickets pane before anything crosses the bridge.
        if op.startswith("support_"):
            from server.routes import support as sp
            try:
                if op == "support_open":
                    for req in ("category", "title", "problem"):
                        if not a.get(req):
                            return _refused(f"{req} is required for op='support_open'")
                    res = await sp.open_service(
                        pool, eid,
                        category=str(a.get("category")), title=str(a.get("title")),
                        problem=str(a.get("problem")), context=str(a.get("context") or ""),
                        recommendation=str(a.get("recommendation") or ""),
                        pushback=str(a.get("pushback") or ""),
                        repro_steps=str(a.get("repro_steps") or ""),
                        expected=str(a.get("expected") or ""), actual=str(a.get("actual") or ""),
                        severity=str(a.get("severity") or "normal"),
                        project_id=(int(a["project_id"]) if a.get("project_id") is not None else None),
                        files=[str(f) for f in (a.get("files") or [])],
                        harness_runs=[int(x) for x in (a.get("harness_runs") or [])],
                        harness_session=str(a.get("harness_session") or ""),
                    )
                    return {"status": "ok", "result": res}
                if op == "support_list":
                    res = await sp.list_service(
                        pool, eid, status_filter=a.get("status"), category=a.get("category"),
                        project_id=(int(a["project_id"]) if a.get("project_id") is not None else None),
                        limit=int(a.get("limit") or 50),
                    )
                    return {"status": "ok", "result": res}
                if a.get("ticket_id") is None:
                    return _refused(f"ticket_id is required for op={op!r}")
                tid = int(a["ticket_id"])
                if op == "support_get":
                    return {"status": "ok", "result": await sp.get_service(pool, eid, tid)}
                if op == "support_update":
                    # A DRAFT's card is rewritten in place and its shared context
                    # assembled again; only the fields passed change.
                    fields = {k: str(a[k]) for k in sp.UPDATE_FIELDS if a.get(k) is not None}
                    if a.get("files") is not None:
                        fields["files"] = [str(f) for f in (a.get("files") or [])]
                    if a.get("harness_runs") is not None:
                        fields["harness_runs"] = [int(x) for x in (a.get("harness_runs") or [])]
                    if a.get("harness_session") is not None:
                        fields["harness_session"] = str(a.get("harness_session") or "")
                    res = await sp.update_service(pool, eid, tid, **fields)
                    return {"status": "ok", "result": res}
                if op == "support_reply":
                    if not a.get("body"):
                        return _refused("body is required for op='support_reply'")
                    res = await sp.reply_service(pool, eid, tid, body=str(a["body"]), author="host")
                    return {"status": "ok", "result": res}
                if op == "support_close":
                    return {"status": "ok", "result": await sp.close_service(pool, eid, tid)}
            except sp.SupportError as e:
                return _refused_if_caller(e, f"tickets failed: {e.detail}")

        return _refused(f"unknown op {op!r} (one of: list, get, badges, decide, dismiss, import, "
            "support_open, support_update, support_list, support_get, support_reply, support_close)")
    except t.TicketError as e:
        return _refused_if_caller(e, f"tickets failed: {e.detail}")
    except Exception as e:
        return _refused_if_caller(e, f"tickets failed: {getattr(e, 'detail', None) or e}")


async def _exec_host_message(args: dict) -> dict:
    """Direct-message another host. One op-dispatch tool over the host's DM surface —
    the SAME service the /api/messages routes use (server.routes.messages), called
    directly (no HTTP shim, no route handler).

      send          -> send a DM (to_entity_id or to_handle, body, topic_id) — keeps our
                       copy + delivers; returns {message_id, thread_id, delivered, topic}
      conversations -> list the host's DM threads (peer + last + unread)
      thread        -> the full back-and-forth in one thread by thread_id (marks received read)
      open          -> resolve a contact to its DM thread id (may have no messages yet)

    A DM threads identically on both hosts (deterministic thread id from the two
    entity ids). Sending to a stranger may be blocked by their domain policy — the
    result's `delivered`/`error` say so; the send still succeeds locally.
    """
    a = args or {}
    op = (a.get("op") or "").strip().lower()
    if not op:
        return _refused("op is required (one of: send, conversations, thread, open)")
    try:
        from server import brain_service
        from server.routes import messages as msg
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "host_message failed: pool unavailable"}
        eid = brain_service._entity_id
        if not eid:
            return {"status": "error", "result": "host_message failed: host id unknown"}
        eid = int(eid)

        if op == "send":
            body = (a.get("body") or "").strip()
            if not body:
                return _refused("body is required to send a message")
            # topic_id: the topic the message goes into;
            # omitted, the topic of the newest message from that Host.
            res = await msg.send_message_service(
                pool, eid,
                to_entity_id=a.get("to_entity_id"), to_handle=a.get("to_handle"),
                to_display_name=a.get("to_display_name"), body=body,
                topic_id=a.get("topic_id"))
            return {"status": "ok", "result": res}

        if op == "conversations":
            res = await msg.conversations_service(pool, eid)
            return {"status": "ok", "result": res}

        if op == "thread":
            thread_id = (a.get("thread_id") or "").strip()
            if not thread_id:
                return _refused("thread_id is required to read a thread (see op='conversations' or 'open')")
            # One page, newest first; `before` = a next_before it returned
            # reads the page before (R4-1: a long thread is never one answer).
            # Each message names its topic; topic_id reads one topic.
            res = await msg.thread_service(pool, eid, thread_id,
                                           limit=a.get("limit"), before=a.get("before"),
                                           topic_id=a.get("topic_id"))
            return {"status": "ok", "result": res}

        if op == "open":
            res = await msg.open_conversation_service(
                pool, eid,
                to_entity_id=a.get("to_entity_id"), to_handle=a.get("to_handle"),
                to_display_name=a.get("to_display_name"))
            return {"status": "ok", "result": res}

        return _refused(f"unknown op '{op}' — use send|conversations|thread|open")
    except Exception as e:
        # MessageError carries .detail; any other failure falls through to its str.
        return _refused_if_caller(e, f"host_message failed: {getattr(e, 'detail', None) or e}")


async def _exec_contacts_manage(args: dict) -> dict:
    """Contacts (address book + connection requests) op-dispatch for the host.

    One tool, several read/write ops over the host's pod-local address book —
    the SAME service helpers the /api/contacts routes use (NOT the route
    handlers). The address book is pod-local (contacts table); accepting a
    request also writes the per-peer domain_policy allow and best-effort
    delivers an endpoint_grant reply through the bridge.

      list          -> the address book (optional status / text filter)
      card          -> the contact card for other Hosts (host_ids): name,
                       address, number, relationship — the SAME resolver the
                       dashboard shows (server/hosts/card.py), from this
                       Host's own records only
      add           -> add or upsert a contact (write)
      update        -> edit a contact's display_name / notes / status (write)
      remove        -> delete a contact (write)
      accept_request-> accept an inbound connection request: record contact +
                       allow + best-effort grant reply (write)
      deny_request  -> deny an inbound connection request: archive it, no
                       contact, no allow (write)
      request_by_phone -> resolve a phone alias to a host identity + send it a
                       connection request (write)
      request_peer  -> send a connection request to a host you share a MACHINE
                       with (peer_entity_id, from get_network). Only a host one
                       of your machines currently reports serving qualifies —
                       the peer list IS the authorization (write)
    """
    a = args or {}
    op = (a.get("op") or "").strip()
    if not op:
        return _refused("op is required (one of: list, card, add, update, remove, "
            "accept_request, deny_request, request_by_phone, request_peer)")
    try:
        from server import brain_service
        from server.routes import contacts as c
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "pool unavailable"}

        if op == "list":
            res = await c.list_contacts_service(
                pool,
                status=(a.get("status") or None),
                q=(a.get("q") or None),
                limit=int(a.get("limit") or 200),
            )
            return {"status": "ok", "result": res}

        if op == "card":
            ids = a.get("host_ids")
            if not isinstance(ids, list) or not ids:
                return _refused("host_ids (a list of Host ids) is required for card")
            from server.hosts.card import host_cards
            cards = await host_cards(pool, brain_service._entity_id, ids)
            return {"status": "ok", "result": {"cards": {str(k): v for k, v in cards.items()}}}

        if op == "add":
            res = await c.create_contact_service(
                pool,
                handle=(a.get("handle") or ""),
                display_name=a.get("display_name"),
                kind=(a.get("kind") or "host"),
                notes=a.get("notes"),
                status=(a.get("status") or "active"),
            )
            return {"status": "ok", "result": res}

        if op == "update":
            cid = a.get("contact_id")
            if cid is None:
                return _refused("contact_id is required for update")
            # Only the keys the caller actually passed are treated as set, so an
            # omitted field is left untouched (same as the PATCH route's body).
            provided = {k for k in ("display_name", "notes", "status") if k in a}
            if not provided:
                return _refused("nothing to update (pass display_name, notes, or status)")
            res = await c.update_contact_service(
                pool, contact_id=int(cid),
                display_name=a.get("display_name"),
                notes=a.get("notes"),
                status=a.get("status"),
                _provided=provided,
            )
            return {"status": "ok", "result": res}

        if op == "remove":
            cid = a.get("contact_id")
            if cid is None:
                return _refused("contact_id is required for remove")
            res = await c.delete_contact_service(pool, contact_id=int(cid))
            return {"status": "ok", "result": res}

        if op == "accept_request":
            res = await c.accept_request_service(
                pool,
                handle=(a.get("handle") or ""),
                message_id=a.get("message_id"),
                display_name=a.get("display_name"),
                from_entity_id=a.get("from_entity_id"),
            )
            return {"status": "ok", "result": res}

        if op == "deny_request":
            res = await c.deny_request_service(
                pool,
                handle=a.get("handle"),
                message_id=a.get("message_id"),
            )
            return {"status": "ok", "result": res}

        if op == "request_by_phone":
            alias = (a.get("alias") or "").strip()
            if not alias:
                return _refused("alias (phone number) is required")
            res = await c.request_by_phone_service(pool, alias=alias, note=a.get("note"))
            return {"status": "ok", "result": res}

        if op == "request_peer":
            pid = a.get("peer_entity_id")
            if pid in (None, ""):
                return _refused("peer_entity_id is required — read it from get_network, which lists "
                    "the peers each of your machines reports")
            res = await c.request_peer_service(pool, peer_entity_id=pid, note=a.get("note"))
            return {"status": "ok", "result": res}

        return _refused(f"unknown op {op!r} — use list, add, update, remove, "
            "accept_request, deny_request, request_by_phone, or request_peer")
    except c.ContactsError as e:
        return _refused_if_caller(e, f"contacts_manage failed: {e.detail}")
    except Exception as e:
        return _refused_if_caller(e, f"contacts_manage failed: {getattr(e, 'detail', None) or e}")


async def _exec_personality_state(args: dict) -> dict:
    """Read the host's OWN personality settings: the ten slider weights the
    person set, personality_mode, skill weights and the master directive.
    Calls the brain SERVICE directly (no HTTP shim), read-only over the host's
    own entity_registry row: the same shape as GET /api/brain/personality.

    The weights are the person's. Nothing moves them but the person: the
    sliders in Settings → Response Shaping, or asking in words. There is no
    drift, no envelope and no reset any more, so there is nothing here to
    check."""
    try:
        from server import brain_service
        from server.routes import brain as _brain
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "personality_state failed: pool unavailable"}
        eid = brain_service._entity_id
        res = dict(await _brain.get_personality_service(pool, eid))
        res["note"] = (
            "These weights are what the user set and they never move on their own. "
            "They change only when the user moves the sliders in Settings → Response "
            "Shaping or asks you in words. What you learn from the user lands in "
            "rules and your own tables, never in these weights."
        )
        return {"status": "ok", "result": res}
    except Exception as e:
        return _refused_if_caller(e, f"personality_state failed: {getattr(e, 'detail', None) or e}")


async def _exec_explanation_level(args: dict) -> dict:
    """The user's explanation level — read, or write when the
    user asked in words. Both go through the SAME service that Settings →
    Response Shaping's PUT /api/brain/personality/explanation uses, so the
    user is still the one moving their setting. Never inferred."""
    try:
        from server import brain_service
        from server.routes import brain as _brain
        from mastercode.runtime.prompt_builder import EXPLANATION_LEVELS
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "explanation_level failed: pool unavailable"}
        eid = brain_service._entity_id
        op = (args or {}).get("op") or "get"
        if op == "set":
            level = (args or {}).get("level")
            res = await _brain.set_explanation_level_service(pool, eid, level)
            if res.get("error"):
                return {"status": "error", "result": f"explanation_level failed: {res['error']}"}
            label = EXPLANATION_LEVELS[res["level"]][0]
            return {"status": "ok", "result": {
                "level": res["level"], "label": label,
                "note": "Set at the user's request. Tell them the new position in plain words; "
                        "it changes again only when they ask or move it in Settings.",
            }}
        res = await _brain.get_personality_service(pool, eid)
        lvl = res.get("explanation_level") or "new"
        positions = {}
        for key in EXPLANATION_LEVELS:
            positions[key] = EXPLANATION_LEVELS[key][0]
        return {"status": "ok", "result": {
            "level": lvl, "label": EXPLANATION_LEVELS[lvl][0],
            "positions": positions,
            "note": "A user-owned setting. It is not inferred and you never change it on your own.",
        }}
    except Exception as e:
        return _refused_if_caller(e, f"explanation_level failed: {getattr(e, 'detail', None) or e}")


# _exec_memory_timeline retired: it browsed entity_journal, whose writer was
# disabled ("Journal feed DEPRECATED", session.py), so the tool advertised a
# feed nothing had written to for three months. The table and its routes are
# gone too (migrations/v237_dead_tables.sql).


async def _exec_entity_tasks(args: dict) -> dict:
    """View + manage the host's OWN task queue: op='list' (default) lists tasks +
    per-status counts (optional status filter, limit); op='cancel'/'delete' acts on
    one task (task_id); op='purge' cancels-or-deletes a whole status bucket (status,
    action). Calls the brain SERVICE directly (no HTTP shim) — all scoped to the
    host's own entity_tasks (task_id + entity_id). Shapes match the /api/brain/
    manage/tasks routes."""
    a = args or {}
    try:
        from server import brain_service
        from server.routes import brain as _brain
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "entity_tasks failed: pool unavailable"}
        eid = brain_service._entity_id
        op = (a.get("op") or "list").strip().lower()
        if op in ("list", "view", "tasks"):
            limit = min(int(a.get("limit") or 100), 500)
            # The project filter (a call with project_id must not be refused
            # as an unknown field). None = every task.
            pid = a.get("project_id")
            if pid is not None:
                try:
                    pid = int(pid)
                except (TypeError, ValueError):
                    return _refused(f"project_id must be a project's number, not {pid!r}")
            res = await _brain.list_tasks_service(pool, eid, status=a.get("status"), limit=limit,
                                                  offset=max(0, int(a.get("offset") or 0)),
                                                  project_id=pid)
        elif op == "cancel":
            tid = a.get("task_id")
            if tid is None:
                return _refused("task_id required for op='cancel'")
            res = await _brain.cancel_task_service(pool, eid, int(tid),
                                                   actor="entity_tasks_tool")
        elif op == "delete":
            tid = a.get("task_id")
            if tid is None:
                return _refused("task_id required for op='delete'")
            res = await _brain.delete_task_service(pool, eid, int(tid))
        elif op == "purge":
            res = await _brain.purge_tasks_service(
                pool, eid,
                status=(a.get("status") or "queued"),
                action=(a.get("action") or "cancel"),
                actor="entity_tasks_tool")
        else:
            return _refused(f"unknown op '{op}' — use list|cancel|delete|purge")
        return {"status": "ok", "result": res}
    except Exception as e:
        return _refused_if_caller(e, f"entity_tasks failed: {getattr(e, 'detail', None) or e}")


_CAPS_DOC_DIR = Path("/app/docs")

# ── capability-card index ─────────────────────────────────────────────
# capabilities.json carries a `capability_cards` corpus baked at image
# build. It is the PRIMARY search index: the markdown renders most of the
# surface as bare identifiers (route prefixes, tool names) with no human
# words, so a literal doc grep for a user's plain phrasing ("voice",
# "screenshot") misses capabilities that ship. The cards carry the words.
#
# TWO shapes exist in the wild and both are handled:
#   rich   {id, kind, title, what, when[], how, returns, gotchas[],
#           related[], keywords[]}
#   legacy {name, lane, category, purpose, keywords, parameters, read_ops}
# Anything else is normalised best-effort. A card that cannot be read is
# skipped, never raised — this tool degrades and SAYS SO in the result.
_CAPS_MIN_SCORE = 25          # below this a "hit" is noise, not a match
_CAPS_WEAK_SCORE = 50         # below this the hits are candidates, not answers
# Filler that carries no capability meaning. Without this, term-coverage
# scoring counted "the", "you", "what" as matched terms, so a sentence made
# mostly of filler reached full coverage and was presented as an answer.
# `_caps_tokens` already drops anything <=2 chars, so this only needs the
# longer ones.
_CAPS_STOPWORDS = frozenset({
    "the", "and", "for", "you", "your", "yours", "can", "could", "would",
    "will", "with", "how", "what", "when", "where", "why", "who",
    "are", "was", "were", "have", "has", "had", "please", "help", "want",
    "need", "give", "get", "got", "make", "does", "did", "this", "that",
    "these", "those", "from", "into", "about", "some", "any", "all", "let",
    "our", "out", "not", "but", "his", "her", "their", "them", "they",
})
_CAPS_CARD_LIMIT = 8          # cards returned by op='search' (override: limit)
_CAPS_CARD_LIMIT_MAX = 25
_CAPS_DOC_LIMIT = 80          # doc lines returned by op='search'
_CAPS_ID_LIST_LIMIT = 400     # ids returned by op='card' with no id
_CAPS_SECTION_LIMIT = 40_000  # chars returned by op='section'


def _caps_as_list(v) -> list[str]:
    """Coerce a card field to a list of non-empty strings. Never raises."""
    if v is None:
        return []
    if isinstance(v, str):
        return [v.strip()] if v.strip() else []
    if isinstance(v, (list, tuple, set)):
        out: list[str] = []
        for x in v:
            if isinstance(x, str) and x.strip():
                out.append(x.strip())
            elif isinstance(x, dict):
                t = x.get("phrase") or x.get("text") or x.get("name") or x.get("id")
                if isinstance(t, str) and t.strip():
                    out.append(t.strip())
            elif x is not None:
                out.append(str(x))
        return out
    return [str(v)]


def _caps_stem(t: str) -> str:
    """Crude singulariser so 'screenshots' finds 'screenshot'."""
    if len(t) > 4 and t.endswith("ies"):
        return t[:-3] + "y"
    if len(t) > 4 and t.endswith("ses"):
        return t[:-2]
    if len(t) > 3 and t.endswith("s") and not t.endswith("ss"):
        return t[:-1]
    return t


def _caps_tokens(s: str) -> set[str]:
    return {_caps_stem(t) for t in re.findall(r"[a-z0-9_]+", str(s or "").lower())
            if len(t) > 2}


def _caps_normalize_card(raw) -> dict | None:
    """Best-effort normalisation of one card of EITHER shape → the rich shape.
    Returns None for anything unusable rather than raising."""
    if not isinstance(raw, dict):
        return None
    legacy = "id" not in raw and "name" in raw
    cid = str(raw.get("id") or raw.get("name") or raw.get("slug") or "").strip()
    title = str(raw.get("title") or raw.get("name") or cid).strip()
    what = str(raw.get("what") or raw.get("purpose") or raw.get("description") or "").strip()
    if not (cid or title or what):
        return None
    card: dict = {
        "id": cid or title,
        "kind": str(raw.get("kind") or ("op" if legacy else "") or "unknown").strip(),
        "title": title or cid,
        "what": what,
        "when": _caps_as_list(raw.get("when") or raw.get("user_phrasings")),
        "how": raw.get("how") or raw.get("example") or "",
        "returns": raw.get("returns") or "",
        "gotchas": _caps_as_list(raw.get("gotchas")),
        "related": _caps_as_list(raw.get("related")),
        "keywords": [k.lower() for k in _caps_as_list(raw.get("keywords"))],
    }
    # Legacy extras — a flat-card image still answers usefully with these.
    for k in ("lane", "category", "read_ops"):
        if raw.get(k):
            card[k] = raw[k]
    # A wiki page card carries its public link, so the host can hand it over.
    if card["kind"] == "page" and raw.get("url"):
        card["url"] = str(raw["url"])
    params = raw.get("parameters")
    if isinstance(params, dict) and isinstance(params.get("properties"), dict):
        card["params"] = sorted(params["properties"])
    missing = [f for f in ("what", "when", "how") if not card.get(f)]
    if missing:
        card["_incomplete"] = missing
    return card


_CAPS_PAGE_EXCERPT = 900      # chars of a wiki page's text in a search hit


def _caps_search_view(card: dict) -> dict:
    """A search hit as returned. A wiki page's `how` is the whole page, and
    eight of them would crowd out everything else in the result, so a hit
    carries the opening and op='card' returns the rest."""
    if card.get("kind") != "page":
        return card
    how = str(card.get("how") or "")
    if len(how) <= _CAPS_PAGE_EXCERPT:
        return card
    cut = how[:_CAPS_PAGE_EXCERPT].rsplit("\n", 1)[0].rstrip()
    return dict(card, how=cut + f"\n\n… (the whole page: op='card', id='{card.get('id')}')")


def _caps_load_cards(js_path: Path) -> tuple[list[dict], str, str]:
    """→ (cards, shape, degraded_note). Never raises.
    shape: 'cards' (rich) | 'flat-legacy' | 'absent' | 'unreadable'."""
    try:
        data = json.loads(js_path.read_text())
    except FileNotFoundError:
        return [], "absent", "capabilities.json is not baked into this image — doc lines only"
    except Exception as e:
        return [], "unreadable", f"capabilities.json could not be parsed ({e}) — doc lines only"
    raw = data.get("capability_cards") if isinstance(data, dict) else None
    if not isinstance(raw, list) or not raw:
        return [], "absent", ("this image's capabilities.json carries no capability_cards — "
                              "doc lines only, so plain-word misses are expected")
    cards: list[dict] = []
    for r in raw:
        c = _caps_normalize_card(r)
        if c:
            cards.append(c)
    if not cards:
        return [], "unreadable", "capability_cards present but no card was readable — doc lines only"
    rich = sum(1 for c in cards if c.get("when") or c.get("how"))
    if rich:
        return cards, "cards", ""
    return cards, "flat-legacy", ("older flat card shape: cards carry a purpose and keywords but "
                                  "no worked example or user phrasings — 'how' is unavailable here")


def _caps_score_card(card: dict, q: str, q_tokens: set[str]) -> tuple[int, str]:
    """Rank one card against the query. exact id/title > `when` phrase >
    keyword > prose substring > partial term coverage."""
    best, why = 0, ""

    def bump(score: int, reason: str) -> None:
        nonlocal best, why
        if score > best:
            best, why = score, reason

    def norm(s: str) -> str:
        return re.sub(r"[._\-/]+", " ", str(s or "").lower()).strip()

    cid, title = str(card.get("id", "")).lower(), str(card.get("title", "")).lower()
    ids = {cid, title, norm(cid), norm(title)}
    ids.discard("")
    if q in ids:
        bump(100, "exact id/title")
    elif any(q in s for s in ids):
        bump(72, "id/title")
    for phrase in card.get("when") or []:
        p = phrase.lower().strip()
        if not p:
            continue
        if q == p:
            bump(90, "when-phrase (exact)")
        elif p in q:
            # The user's sentence contains this whole phrasing. A MULTI-WORD
            # phrase is specific enough to be an answer. A SINGLE common word
            # is not, and treating it as one produced confident wrong answers
            # (measured): "restore my antique chair" hit the backup
            # area on `restore`, "write a speech for my wedding" hit realtime
            # on `speech`, "buy tickets to a concert" hit support tickets.
            # A lone word is only an answer when it is essentially the whole
            # query ("voice"); inside a sentence it is a candidate, so it
            # lands below _CAPS_WEAK_SCORE and the host offers it as such.
            # Defended here as well as in the generator because the corpus is
            # data and this is the rule that data cannot violate.
            if len(p.split()) >= 2 or len(q.split()) <= 2:
                bump(78, "when-phrase")
            else:
                bump(48, "when-phrase (single word in a sentence)")
        elif q in p:
            # the query is only a fragment of the phrasing — weaker than an
            # exact keyword hit, so 'screenshot' prefers the screenshot card
            # over a card that merely mentions screenshots in a `when` line.
            bump(52, "when-phrase (partial)")
    kws = {str(k).lower() for k in (card.get("keywords") or [])}
    if q in kws:
        bump(56, "keyword")
    prose_parts = [card.get("what"), card.get("returns"), card.get("how"),
                   card.get("kind"), card.get("category"), card.get("lane")]
    prose_parts += list(card.get("gotchas") or []) + list(card.get("related") or [])
    prose = " ".join(str(p) for p in prose_parts if p).lower()
    if q and q in prose:
        bump(30, "prose")
    if q_tokens:
        strong_hay = _caps_tokens(" ".join([cid, title] + list(card.get("when") or [])))
        strong_hay |= {_caps_stem(k) for k in kws}
        hay = strong_hay | _caps_tokens(prose)
        # Scattered term overlap is the WEAKEST evidence there is — it says
        # some words co-occur, not that the card is the answer. It used to top
        # out at exactly _CAPS_WEAK_SCORE, so full coverage was presented as an
        # answer: "delete my account" landed confidently on the Orchestrator
        # and "send a text message" on contacts_manage (SMS is deliberately
        # not built). Cap it strictly BELOW the answer floor so this arm can
        # only ever offer candidates. Stopwords are excluded so filler like
        # "the/you/what/are" cannot inflate coverage.
        hit = (q_tokens - _CAPS_STOPWORDS) & hay
        denom = len(q_tokens - _CAPS_STOPWORDS)
        if hit and denom:
            cov = len(hit) / denom
            base = (_CAPS_WEAK_SCORE - 2) if (q_tokens & strong_hay) else 26
            bump(int(base * cov), "terms " + ",".join(sorted(hit)))
    return best, why


def _caps_doc_search(lines: list[str], q: str, q_tokens: set[str],
                     cap: int) -> tuple[list[str], int, str]:
    """Secondary index: the markdown lines. → (hits, total, mode)."""
    def scan(pred) -> tuple[list[str], int]:
        hits: list[str] = []
        total, head = 0, ""
        for ln in lines:
            if ln.startswith("## "):
                head = ln[3:].strip()
                continue
            if pred(ln):
                total += 1
                if len(hits) < cap:
                    hits.append(f"[{head}] {ln.strip()}")
        return hits, total

    hits, total = scan(lambda ln: q in ln.lower())
    if total:
        return hits, total, "substring"
    if len(q_tokens) > 1:
        hits, total = scan(lambda ln: q_tokens <= _caps_tokens(ln))
        if total:
            return hits, total, "all-terms"
    return [], 0, "substring"


async def _exec_capabilities(args: dict) -> dict:
    """Read the generated platform-capabilities index (docs/capabilities.json's
    capability_cards + docs/CAPABILITIES.md, baked at image build — version-exact
    by construction). THE first stop for any 'can Privatae Host do X?' question.

    op='search' searches the CARDS first (id/title/when-phrases/keywords/prose)
    and falls back to the markdown lines. A miss means THESE WORDS were not
    found — not that the platform lacks the capability: the markdown renders
    most of the route surface as bare identifiers, so plain-word misses are
    routine. Say what you searched; never convert a vocabulary miss into a
    denial. Read-only, in-pod file access only."""
    a = args or {}
    op = (a.get("op") or "overview").strip().lower()
    md_path = _CAPS_DOC_DIR / "CAPABILITIES.md"
    js_path = _CAPS_DOC_DIR / "capabilities.json"
    if not md_path.exists():
        return _refused("capabilities doc not baked in this image (pre-capabilities build) "
                          "— answer from describe_app/explore_environment and say the doc is absent")
    try:
        md = md_path.read_text()
        lines = md.splitlines()
        heads = [ln for ln in lines if ln.startswith("## ")]
        if op == "overview":
            data = {}
            try:
                data = json.loads(js_path.read_text())
            except Exception:
                pass
            cards, shape, degraded = _caps_load_cards(js_path)
            return {"status": "ok", "result": {
                "version": data.get("version") or (lines[0] if lines else ""),
                "sections": heads,
                "section_count": len(heads),
                "counts": {
                    "api_routes": (data.get("api_contract") or {}).get("count"),
                    "host_ops": len(data.get("host_ops") or []),
                    "scopes": len(data.get("scopes") or []),
                    "image_apps": len(data.get("apps") or []),
                    "capability_cards": len(cards),
                },
                "card_index": {"shape": shape, "count": len(cards),
                               "degraded": degraded},
                "rule": ("search the cards first (op='search', plain user words). A hit is a YES — "
                         "cite the card. A miss means those WORDS were not found in the cards or "
                         "the doc; retry with the user's own phrasing and check op='api_routes' "
                         "before saying anything is unsupported."),
            }}
        if op == "section":
            want = str(a.get("section") or "").strip().lower()
            if not want:
                return _refused(f"section required (1-{len(heads)} or a heading substring) "
                                  f"— op='overview' lists them")
            out: list[str] = []
            grab = False
            picked = ""
            for ln in lines:
                if ln.startswith("## "):
                    if grab:
                        break
                    head = ln[3:].strip().lower()
                    grab = head.startswith(f"{want}.") or want in head
                    if grab:
                        picked = ln[3:].strip()
                if grab:
                    out.append(ln)
            if not out:
                return _refused(f"no section matches '{want}' — op='overview' lists all "
                                  f"{len(heads)} sections")
            text = "\n".join(out)
            return {"status": "ok", "result": {
                "section": picked,
                "text": text[:_CAPS_SECTION_LIMIT],
                "chars": len(text),
                "truncated": len(text) > _CAPS_SECTION_LIMIT,
            }}
        if op == "card":
            cards, shape, degraded = _caps_load_cards(js_path)
            want = str(a.get("id") or a.get("q") or "").strip().lower()
            if not cards:
                return {"status": "error",
                        "result": f"no capability cards in this image ({degraded}) — "
                                  f"use op='search' (doc lines) or op='api_routes'"}
            if not want:
                listed = sorted(cards, key=lambda c: str(c.get("id", "")))
                return {"status": "ok", "result": {
                    "count": len(cards), "shape": shape, "degraded": degraded,
                    "cards": [{"id": c["id"], "kind": c["kind"], "title": c["title"]}
                              for c in listed[:_CAPS_ID_LIST_LIMIT]],
                    "truncated": len(cards) > _CAPS_ID_LIST_LIMIT,
                    "note": "op='card' with id=<one of these> returns the whole card",
                }}
            exact = [c for c in cards
                     if str(c.get("id", "")).lower() == want or str(c.get("title", "")).lower() == want]
            if exact:
                return {"status": "ok", "result": {"cards": exact, "exact": True,
                                                   "shape": shape, "degraded": degraded}}
            q_tokens = _caps_tokens(want)
            scored = []
            for c in cards:
                s, why = _caps_score_card(c, want, q_tokens)
                if s > 0:
                    scored.append((s, why, c))
            scored.sort(key=lambda t: (-t[0], str(t[2].get("id", ""))))
            # Near matches are candidates, so a page among them carries its
            # opening like a search hit; its exact id returns the whole page.
            near = [_caps_search_view(dict(c, match=why, score=s)) for s, why, c in scored[:5]]
            return {"status": "ok", "result": {
                "cards": near, "exact": False, "shape": shape, "degraded": degraded,
                "note": (f"no card has id/title '{want}'"
                         + ("; nearest by relevance above" if near
                            else "; nothing scored — try op='search' with plain words")),
            }}
        if op == "search":
            q = str(a.get("q") or "").strip().lower()
            if not q:
                return _refused("q required for op='search'")
            try:
                limit = int(a.get("limit") or _CAPS_CARD_LIMIT)
            except Exception:
                limit = _CAPS_CARD_LIMIT
            limit = max(1, min(limit, _CAPS_CARD_LIMIT_MAX))
            cards, shape, degraded = _caps_load_cards(js_path)
            q_tokens = _caps_tokens(q)
            scored = []
            for c in cards:
                s, why = _caps_score_card(c, q, q_tokens)
                if s >= _CAPS_MIN_SCORE:
                    scored.append((s, why, c))
            scored.sort(key=lambda t: (-t[0], str(t[2].get("id", ""))))
            card_hits = [_caps_search_view(dict(c, match=why, score=s))
                         for s, why, c in scored[:limit]]
            hits, doc_total, doc_mode = _caps_doc_search(lines, q, q_tokens, _CAPS_DOC_LIMIT)
            searched = {"cards": len(cards), "card_shape": shape,
                        "doc_lines": len(lines), "doc_sections": len(heads),
                        "doc_match_mode": doc_mode}
            if degraded:
                searched["degraded"] = degraded
            if card_hits:
                if card_hits[0]["score"] >= _CAPS_WEAK_SCORE:
                    note = ("card hits are the answer — quote the card's `what`, use its `how`, "
                            "and read its `gotchas` before you promise anything")
                else:
                    # Do NOT say "none is a real hit" — that is frequently
                    # false. A correct card lands here whenever the user's
                    # phrasing was a lone word inside a longer sentence, which
                    # is the common case ("take a screenshot of this page").
                    # Telling the host the top candidate is wrong makes it
                    # deny a capability it just found.
                    note = ("CANDIDATES, not a confirmed answer — the top one may well be "
                            "right. Open it with op='card' to confirm, or check "
                            "op='api_routes', before you answer yes or no")
                if shape == "flat-legacy":
                    note += "; this image's cards are the older flat shape (no `how`/`when`)"
            elif doc_total:
                note = ("no card matched, but the doc did — these are raw doc lines, so confirm "
                        "with op='section' or op='api_routes' before answering")
            else:
                note = (f"no match for '{q}' in the capability cards ({len(cards)} searched) or in "
                        f"CAPABILITIES.md ({len(lines)} lines, {len(heads)} sections). That means "
                        f"THESE WORDS were not found — it is NOT proof the capability is missing. "
                        f"Most of the doc lists bare route prefixes and tool names with no plain "
                        f"words. Retry with the user's own phrasing or a synonym, and check "
                        f"op='api_routes' (prefix='/api/...'). Only after that, say what you "
                        f"searched and that you could not find it — never that it cannot be done.")
                if degraded:
                    note += f" NOTE: {degraded}."
            return {"status": "ok", "result": {
                "query": q,
                "cards": card_hits,
                "card_count": len(scored),
                "cards_truncated": len(scored) > len(card_hits),
                "matches": hits,
                "count": doc_total,
                "truncated": doc_total > len(hits),
                "searched": searched,
                "note": note,
            }}
        if op == "api_routes":
            data = json.loads(js_path.read_text())
            routes = (data.get("api_contract") or {}).get("routes") or []
            prefix = str(a.get("prefix") or "").strip()
            if prefix:
                routes = [r for r in routes if str(r.get("path", "")).startswith(prefix)]
            return {"status": "ok", "result": {"count": len(routes), "routes": routes[:200],
                    "truncated": len(routes) > 200}}
        return _refused(f"unknown op '{op}' — use overview|section|search|card|api_routes")
    except Exception as e:
        return _refused_if_caller(e, f"capabilities failed: {e}")


async def _exec_support_collect(args: dict) -> dict:
    """The operator Host's collect of the support queue (runtime/support_collect.py).
    Supplies the pod-local pieces the pure module injects: this host's pool and
    entity id. The module refuses a non-operator host itself; the platform
    refuses it again at the bridge."""
    from mastercode.runtime import support_collect as _sc
    from server import brain_service
    pool = brain_service.get_pool()
    return await _sc.run(args or {}, pool=pool, entity_id=int(brain_service._entity_id))


async def _exec_bug_review(args: dict, *, agent_grant: int | None,
                           session_id: str | None = None) -> dict:
    """The operator Host's door onto the bug cache (runtime/bug_review.py).

    This wrapper supplies the pod-local pieces the pure module injects:
    creating the one-shot "validate pending bug reports" prompt task (the
    same calendar row schedule_task writes) and checking whether one is
    already queued OR fired recently, so the deterministic standing poll can
    run every few minutes at no model cost and wake the host only when there
    is work — and never more than once per WAKE_COOLDOWN while a report sits
    unverdicted. `session_id` is the calling session — for a
    dispatched agent, its own — which ties a verdict to the report that same
    agent read.
    """
    from mastercode.runtime import bug_review as _br

    async def _wake_queued(title: str) -> bool:
        try:
            from server import brain_service
            pool = brain_service.get_pool()
            if pool is None:
                return False
            n = await pool.fetchval(
                "SELECT count(*) FROM calendar_events WHERE entity_id=$1 "
                "AND event_type='scheduled_task' AND title=$2 "
                "AND (status='scheduled' OR (status IN ('running','completed','failed') "
                "     AND event_at > NOW() - ($3::int * interval '1 second')))",
                int(brain_service._entity_id), title, int(_br.WAKE_COOLDOWN_SECONDS))
            return bool(n)
        except Exception as e:  # noqa: BLE001
            log.debug("bug_review wake_queued check failed: %s", e)
            return False

    async def _schedule_wake(title: str, prompt: str) -> dict:
        from datetime import datetime, timedelta, timezone

        from server.bridge.memory_handlers import handle_calendar_append
        fire_at = (datetime.now(timezone.utc) + timedelta(seconds=30)).isoformat()
        env = await handle_calendar_append({
            "event_type": "scheduled_task", "summary": title, "event_at": fire_at,
            "status": "scheduled", "source": "entity",
            # One-shot: no recurrence, and no per-task ceiling — the ceiling
            # is per event row, so it would bound nothing here; the cool-down
            # in _wake_queued is what bounds the spend.
            "payload": {"prompt": prompt, "steps": []},
        })
        if not env.get("ok"):
            raise RuntimeError(env.get("error") or "could not schedule the validation turn")
        return {"scheduled": title, "event_id": env.get("event_id"), "fire_at": env.get("event_at")}

    return await _br.run(args, agent_grant=agent_grant, session_id=session_id,
                         schedule_wake=_schedule_wake, wake_queued=_wake_queued)


async def _exec_propose_capability(args: dict) -> dict:
    """Escalate a VERIFIED capability gap into the community pipeline: create an
    Ideas thread on the board carrying the gap analysis, then open the governed
    community/proposals feature-request PR with this host as its author — the
    exact ladder the board's 'propose this' uses (server/routes/community.py
    propose → capability_propose.propose_feature_request). The PR is filed on a
    branch of the proposals repo itself; there is no fork. Call only after the
    user consents; the tool performs both steps and returns the refs."""
    a = args or {}
    title = str(a.get("title") or "").strip()
    body = str(a.get("body") or "").strip()
    done_looks_like = str(a.get("done_looks_like") or "").strip()
    if not title or not body:
        return _refused("title and body (the gap analysis) are required")
    try:
        import uuid as _uuid

        from server.routes import community as _comm

        # Resolve the Ideas category from the live board (slugs are communityd's).
        cats = ((await _comm._op("community.categories", {})) or {})
        cat_rows = cats.get("categories") if isinstance(cats, dict) else None
        cat_rows = cat_rows if isinstance(cat_rows, list) else (cats if isinstance(cats, list) else [])
        slug = None
        for c in cat_rows:
            label = f"{c.get('slug', '')} {c.get('name', '')}".lower() if isinstance(c, dict) else str(c).lower()
            if "idea" in label:
                slug = (c.get("slug") or c.get("id") or c.get("name")) if isinstance(c, dict) else str(c)
                break
        if slug is None and cat_rows:
            c0 = cat_rows[0]
            slug = (c0.get("slug") or c0.get("id") or c0.get("name")) if isinstance(c0, dict) else str(c0)
        if not slug:
            return {"status": "error", "result": "community board has no categories — board unreachable?"}

        created = await _comm._op("community.post", {
            "op_id": f"cap-{_uuid.uuid4()}",
            "category": str(slug),
            "title": title,
            "body": body,
        })
        thread_id = None
        if isinstance(created, dict):
            thread_id = (created.get("id") or created.get("thread_id")
                         or (created.get("thread") or {}).get("id"))
        if not thread_id:
            return {"status": "error",
                    "result": f"thread create returned no id (got keys: {sorted(created) if isinstance(created, dict) else type(created).__name__})"}

        laddered = await _comm.propose(int(thread_id), done_looks_like=done_looks_like)
        return {"status": "ok", "result": {
            "thread_id": int(thread_id),
            "proposal_ref": (laddered or {}).get("proposal_ref"),
            "url": (laddered or {}).get("url"),
        }}
    except Exception as e:
        return _refused_if_caller(e, f"propose_capability failed: {getattr(e, 'detail', None) or e}")


async def _exec_context_ingest(args: dict) -> dict:
    """Stage external material into the host's user_context intake layer, search it,
    and promote a staged entry into the host's own entity_memory — op-dispatch over
    the context-intake SERVICE (server/routes/context.py), the SAME functions the
    /api/brain/context routes use (NOT the route handlers, NO HTTP shim).

    user_context is the raw material the host can draw from but hasn't internalized —
    the USER owns it. The host stages/searches it, then PROMOTES the worthwhile parts
    into its own identity (entity_memory). All ops are scoped to the calling entity.

    ops:
      stage  (default): stage ONE piece of material. args: content (required),
                        title?, source? (default 'host' — marks it host-staged in
                        the user's Explorer), source_id?, tags?,
                        metadata?, created_at?, embed? (embed inline, default false).
      bulk            : stage MANY at once. args: items (required: a list of the same
                        per-item shape as stage), source? (default 'host'), embed?.
      search          : semantic search within staged context. args: query (required),
                        limit? (default 20, max 100).
      promote         : internalize a staged entry into entity_memory. args:
                        context_id (required), memory_type? (research, the
                        default, | cited_fact | preference | relationship),
                        importance? (default 1.0).
      list            : list staged entries. args: source?, status? (default 'raw';
                        'all' = no status filter), page? (default 1), per_page? (default 50).

    Embedding routes through the bridge with the entity's active model and lands in
    the column matching that model's dim (mirrors entity_memory). For a big backfill,
    stage WITHOUT embed then run a durable embed job (embed_jobs target='user_context').
    """
    a = args or {}
    op = (a.get("op") or "stage").strip().lower()

    try:
        from server import brain_service
        from server.routes import context as _ctx
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "context_ingest failed: brain not initialized"}
        eid = brain_service._entity_id

        if op in ("stage", "add"):
            content = (a.get("content") or "").strip()
            if not content:
                return _refused("context_ingest stage: content is required")
            item = {
                "content": content,
                "title": a.get("title"),
                "source_id": a.get("source_id"),
                "tags": a.get("tags") or [],
                "metadata": a.get("metadata") or {},
                "created_at": a.get("created_at"),
            }
            # Host-staged rows default to source='host' (a caller-supplied
            # source still wins) so the user's Explorer can tell what the host
            # brought in apart from what they added themselves — with 'manual'
            # the two were indistinguishable.
            res = await _ctx.stage_context_service(
                pool, eid,
                source=(a.get("source") or "host"),
                items=[item],
                embed_now=bool(a.get("embed", False)))
            return {"status": "ok", "result": res}

        if op in ("bulk", "import"):
            items = a.get("items")
            if not isinstance(items, list) or not items:
                return _refused("context_ingest bulk: items (a non-empty list) is required")
            res = await _ctx.stage_context_service(
                pool, eid,
                source=(a.get("source") or "host"),
                items=items,
                embed_now=bool(a.get("embed", False)))
            return {"status": "ok", "result": res}

        if op == "search":
            query = (a.get("query") or a.get("q") or "").strip()
            if not query:
                return _refused("context_ingest search: query is required")
            try:
                limit = int(a.get("limit") or 20)
            except (TypeError, ValueError):
                limit = 20
            res = await _ctx.search_context_service(pool, eid, query=query, limit=limit)
            return {"status": "ok", "result": res}

        if op == "promote":
            cid = a.get("context_id", a.get("id"))
            if cid is None:
                return _refused("context_ingest promote: context_id is required")
            try:
                cid = int(cid)
            except (TypeError, ValueError):
                return _refused("context_ingest promote: context_id must be an integer")
            try:
                importance = float(a.get("importance", 1.0))
            except (TypeError, ValueError):
                importance = 1.0
            try:
                res = await _ctx.promote_context_service(
                    pool, eid, cid,
                    memory_type=(a.get("memory_type") or "research"),
                    importance=importance)
            except _ctx.ContextError as ce:
                return _refused_if_caller(ce, f"context_ingest promote: {ce.detail}")
            return {"status": "ok", "result": res}

        if op == "list":
            try:
                page = int(a.get("page") or 1)
            except (TypeError, ValueError):
                page = 1
            try:
                per_page = int(a.get("per_page") or 50)
            except (TypeError, ValueError):
                per_page = 50
            res = await _ctx.list_context_service(
                pool, eid,
                source=a.get("source"),
                status=(a.get("status") or "raw"),
                page=page, per_page=per_page)
            return {"status": "ok", "result": res}

        if op in ("extract", "extract_machines"):
            # Turn a stored document into TEXT. The host reads PDF / Office /
            # text itself (server/readers); a scan, a picture or a recording
            # is a job on one of the user's machines. The text lands as
            # ordinary context rows carrying the file's tags and upload batch,
            # and an embed job is queued for them.
            from server.routes.context_extract import (
                extract_context_file as _extract, machines_for as _prep_machines)
            from server import brain_service as _bs
            _pool = _bs.get_pool()
            if _pool is None:
                return {"status": "error", "error": "Brain not initialized"}
            if op == "extract_machines":
                from server.routes.context_extract import (
                    ocr_blocked_reasons as _ocr_blocked,
                    stt_blocked_reasons as _stt_blocked)
                _ms = await _prep_machines(_pool, _bs._entity_id,
                                           (a.get("tool") or "").strip() or None)
                # Which of them the user has APPROVED for an extraction job
                # (a signed grant naming ctx_extract): a machine that has the
                # engine and no grant is named as that, so the host drafts a
                # grant for the user rather than asking the machine.
                from server.network import nac_mgmt as _nm
                from server.routes.context_extract import EXTRACT_OP as _XOP
                _gate = await _nm.gate_servers(_pool, _bs._entity_id, _XOP,
                                               [m.get("server") for m in _ms])
                for _m in _ms:
                    _ok, _why, _ = _gate.get(_m.get("server"), (False, "no signed grant (default-deny)", ""))
                    _m["granted"] = _ok
                    if not _ok:
                        _m["not_granted"] = _why
                # A machine that HAS the engine and cannot use it is the one
                # answer the model would otherwise report as "no machine can do
                # this" — which sends the user to install what is already there.
                # For speech that is the COMMON case rather than the edge one:
                # the whisper.cpp package ships no model, so a freshly installed
                # engine is blocked until the user downloads one.
                return {"status": "ok", "result": {
                    "machines": _ms, "ocr_blocked": _ocr_blocked(_ms),
                    "stt_blocked": _stt_blocked(_ms)}}
            try:
                _cid = int(a.get("context_id") or a.get("ctx_id"))
            except (TypeError, ValueError):
                return {"status": "error", "error": "context_id required", _INPUT_REFUSED: True}
            # `tool` chooses among the jobs a file supports — a clip has words
            # in it and pictures in it, and the words are the default because
            # that is what someone hunting "the demo where we talked about
            # pricing" is looking for. `model` chooses which speech model reads
            # a recording, from the list the machine advertised. `lang` names the
            # language SPOKEN in it — only ever because someone SAID so, never
            # guessed from a locale or a filename and never defaulted: the engine
            # reads English unless it is told otherwise, and that is what every
            # transcript so far has been.
            res = await _extract(_pool, _bs._entity_id, _cid,
                                 server=(a.get("server") or "").strip() or None,
                                 tool=(a.get("tool") or "").strip() or None,
                                 model=(a.get("model") or "").strip() or None,
                                 lang=(a.get("lang") or "").strip() or None)
            # The service says what happened in its own words; an error from it
            # is a real answer (no machine, wrong file type, the box refused),
            # not a tool failure to be papered over.
            if res.get("refused"):
                # The signed-grant gate said no: a refusal, reported as one — never a route to try
                # around. The words are the gate's.
                return {"status": "denied", "result": res["error"], "detail": res}
            if res.get("pending_approval"):
                # Not a refusal and not a result: the person's card is up
                # (`asked`, with the ask the chat raises as the overlay —
                # written by the pod, app-web-kit/ask.ts RESULT_ASK_TOOLS) or
                # their tap is awaited. status 'ok' so the failure ledger
                # stays quiet; the words in `result` are what the host reads.
                return {"status": "ok", "result": res}
            if res.get("error"):
                return {"status": "error", "error": res["error"], "result": res}
            return {"status": "ok", "result": res}

        if op == "files":
            # FILE-level discovery over the user's uploaded corpus — the same
            # rollup the Context Explorer uses (chunks group by upload_batch /
            # from_file). This is how the host finds "the CSV the user just
            # uploaded" before reading it with op='read'.
            from server.routes.context_manager import context_files as _cm_files
            try:
                page = int(a.get("page") or 1)
            except (TypeError, ValueError):
                page = 1
            try:
                per_page = min(int(a.get("per_page") or 50), 200)
            except (TypeError, ValueError):
                per_page = 50
            # Tool results the host stashed for its own recall (source
            # 'tool:<name>', the retired artifact capture) are NOT
            # the user's documents and are excluded by default — a fresh host
            # listed "personality_state result" beside the user's uploads and
            # described it as theirs. include_host_staged
            # =true lists them too, labelled.
            _incl = bool(a.get("include_host_staged"))
            res = await _cm_files(
                page=page, per_page=per_page, sort="updated", order="desc",
                q=(a.get("query") or None), tag=None, source=None,
                backend=None, machine=None, embedded=None, owner="user_context",
                exclude_source_prefix=(None if _incl else "tool:"))
            if isinstance(res, dict) and res.get("error"):
                return {"status": "error", "result": f"context_ingest files: {res['error']}"}
            if isinstance(res, dict):
                res = dict(res)
                if _incl:
                    for f in res.get("files") or []:
                        if isinstance(f, dict) and str(f.get("source") or "").startswith("tool:"):
                            f["host_staged"] = True
                    res["note"] = ("Rows with host_staged=true are tool results YOU stashed "
                                   "(source 'tool:<name>') — never call them the user's documents.")
                else:
                    res["note"] = ("Host-staged tool results (source 'tool:*') are excluded — "
                                   "these are the user's uploads. Pass include_host_staged=true "
                                   "to list what you stashed yourself, labelled.")
            return {"status": "ok", "result": res}

        if op in ("read", "read_file"):
            # Read an uploaded document WHOLE, in order — the missing verb that
            # forced the host to reconstruct files from search snippets
            # (it could only read metadata). Chunks are
            # returned in upload order (metadata.chunk stamp, created_at/id
            # fallback) with honest pagination — pages, never truncation.
            fname = (a.get("file") or a.get("from_file") or "").strip()
            batch = (a.get("upload_batch") or "").strip() or None
            if not fname and not batch:
                return _refused("context_ingest read: pass `file` (the uploaded filename — "
                    "find it with op='files') and/or `upload_batch`.")
            try:
                page = int(a.get("page") or 1)
            except (TypeError, ValueError):
                page = 1
            try:
                per_page = min(max(int(a.get("per_page") or 50), 1), 200)
            except (TypeError, ValueError):
                per_page = 50
            # Filenames arrive RELAYED — often through a dispatch prompt some
            # other model typed — so treat the argument as a transcription,
            # not truth (a relayed 8-char batch-key shorthand once
            # stalled the same document read three runs over two days;
            # filenames mangle in relay the same way). An exact miss resolves
            # case/separator-insensitively when that lands on exactly one
            # real file; anything else ERRORS naming the corpus's closest
            # real filenames, so an empty result can never be read as "the
            # document doesn't exist".
            file_note = None
            if fname:
                try:
                    frows = await pool.fetch(
                        "SELECT DISTINCT metadata->>'from_file' AS f "
                        "FROM user_context WHERE entity_id = $1 "
                        "AND metadata->>'from_file' IS NOT NULL "
                        "AND status != 'dismissed'", eid)
                except Exception:
                    frows = []
                names = [r["f"] for r in frows if r["f"]]
                if names and fname not in names:
                    def _norm(s: str) -> str:
                        return re.sub(r"[\s._\-/]+", "", s.lower())
                    hits = [n for n in names if _norm(n) == _norm(fname)]
                    if len(hits) == 1:
                        file_note = (f"file {fname!r} resolved to the real "
                                     f"upload {hits[0]!r}.")
                        fname = hits[0]
                    else:
                        close = (difflib.get_close_matches(
                            fname, names, n=5, cutoff=0.4) or names[:8])
                        return _refused(f"context_ingest read: no uploaded file named "
                            f"{fname!r}. Closest real filenames: "
                            f"{', '.join(repr(n) for n in close)}. Use "
                            "op='files' for the full corpus — do not conclude "
                            "the document is missing from this miss alone.")
            # Filename → NEWEST upload batch: the same file
            # uploaded twice is two chunk sets sharing chunk indices — reading
            # both interleaves duplicate content into garbage. Scope to the
            # newest batch and SAY older copies exist. (status='active' below
            # keeps superseded/dismissed copies out entirely.)
            # A wrong upload_batch alongside a good filename must not sink
            # the read (the host once passed its own 8-char shorthand
            # of a real key and the exact-match filter returned nothing,
            # stalling the same document read three runs over two days). Hex
            # keys prefix-match unambiguously in practice; anything still
            # unmatched falls back to the filename's newest upload — with a
            # note, never silently.
            older_note = None
            batch_note = None
            if fname:
                try:
                    brows = await pool.fetch(
                        "SELECT metadata->>'upload_batch' AS ub, MAX(created_at) AS ts "
                        "FROM user_context WHERE entity_id = $1 "
                        "AND metadata->>'from_file' = $2 AND status != 'dismissed' "
                        "GROUP BY 1 ORDER BY MAX(created_at) DESC",
                        eid, fname)
                except Exception:
                    brows = []
                ubs = [r["ub"] for r in brows if r["ub"]]
                if batch and batch not in ubs:
                    prefixed = [u for u in ubs if u.startswith(batch)]
                    if len(prefixed) == 1:
                        batch_note = (f"upload_batch {batch!r} is a prefix of "
                                      f"{prefixed[0]!r} — read that upload.")
                        batch = prefixed[0]
                    elif ubs:
                        batch_note = (f"upload_batch {batch!r} matched no upload "
                                      f"of {fname!r} — read the NEWEST instead. "
                                      f"Real keys: {', '.join(ubs[:5])}.")
                        batch = ubs[0]
                    else:
                        batch_note = (f"upload_batch {batch!r} matched no upload "
                                      f"of {fname!r} (its rows carry no batch "
                                      "stamp) — read by filename alone.")
                        batch = None
                elif not batch and ubs:
                    batch = ubs[0]
                    if len(ubs) > 1:
                        older_note = (
                            f"{len(ubs) - 1} older upload(s) of this file also "
                            "exist — reading the NEWEST. Pass upload_batch to "
                            "read a specific one.")
            # EXTRACTED TEXT WINS OVER THE STORED BYTES. Reading a
            # PDF used to hand back base64: the batch resolution above only
            # sees rows carrying an upload_batch, extracted rows carry none, so
            # it resolved to the original file row — and list_context_service
            # selects `content` raw, with no file-kind guard. The host asked to
            # read a document and got the document's encoding.
            extracted_note = None
            legacy_parent = None
            if fname:
                # Text read from a file carries that upload's batch stamp, so
                # the read stays on ONE upload. Older unstamped text is not
                # matched here: the stored file is
                # read again below, which replaces it with stamped rows.
                has_text = await pool.fetchval(
                    "SELECT 1 FROM user_context WHERE entity_id = $1 "
                    "AND source = 'extracted' AND metadata->>'from_file' = $2 "
                    "AND status != 'dismissed' "
                    "AND ($3::text IS NULL OR metadata->>'upload_batch' = $3) LIMIT 1",
                    eid, fname, batch)
                if not has_text and batch:
                    # Text filed before batch stamps (a machine's OCR of a
                    # scan, a transcript) is still this upload's text when it
                    # hangs off this upload's file row. Read it as-is: the
                    # host cannot re-read a scan or a recording itself.
                    legacy = await pool.fetchval(
                        "SELECT 1 FROM user_context t WHERE t.entity_id = $1 "
                        "AND t.source = 'extracted' AND t.status != 'dismissed' "
                        "AND t.metadata->>'upload_batch' IS NULL "
                        "AND t.media_parent_id IN (SELECT f.id FROM user_context f "
                        "  WHERE f.entity_id = $1 AND f.metadata->>'from_file' = $2 "
                        "  AND f.metadata->>'upload_batch' = $3) LIMIT 1",
                        eid, fname, batch)
                    if legacy:
                        has_text, legacy_parent, batch = True, batch, None
                if has_text:
                    extracted_note = (
                        f"{fname} is a stored document; this is the TEXT "
                        f"read from it.")
            res = await _ctx.list_context_service(
                pool, eid, status="active", fields="full",
                from_file=fname or None, upload_batch=batch,
                source="extracted" if extracted_note else None,
                parent_batch=legacy_parent,
                page=page, per_page=per_page, order="asc")
            items = res.get("items") or []
            if not items:
                return _refused(f"context_ingest read: no staged content matched "
                    f"file={fname!r} upload_batch={batch!r} (page {page}). "
                    "Use op='files' to list the corpus's real file names.")

            def _chunk_key(idx_item):
                idx, it = idx_item
                md = it.get("metadata")
                if isinstance(md, str):
                    try:
                        md = json.loads(md)
                    except (ValueError, TypeError):
                        md = {}
                md = md or {}
                ck = md.get("chunk")
                return (0, int(ck)) if isinstance(ck, int) else (1, idx)

            ordered = [it for _, it in sorted(enumerate(items), key=_chunk_key)]

            # A STORED DOCUMENT WITH NO EXTRACTION IS NOT READABLE, and handing
            # back its base64 is worse than refusing: the model cannot tell
            # encoded bytes from content and will try to reason about them.
            # Say what it is and how to turn it into text on the user's machine.
            if not extracted_note:
                def _kind(it):
                    md = it.get("metadata")
                    if isinstance(md, str):
                        try:
                            md = json.loads(md)
                        except (ValueError, TypeError):
                            md = {}
                    return (md or {}).get("kind")
                if ordered and all(_kind(it) == "file" for it in ordered):
                    mime = ""
                    md0 = ordered[0].get("metadata")
                    if isinstance(md0, str):
                        try:
                            md0 = json.loads(md0)
                        except (ValueError, TypeError):
                            md0 = {}
                    mime = (md0 or {}).get("mime") or "binary"
                    # READ IT NOW when the host has a reader for the type: a
                    # plain function call (server/readers), then this read
                    # continues on the text. Only a type the host cannot read
                    # (a picture, a recording) is sent back as a next step.
                    from server.readers.docread import reader_for as _reader_for
                    _cid0 = ordered[0].get("id")
                    if _reader_for(mime) and _cid0 is not None:
                        from server.routes.context_extract import (
                            extract_context_file as _read_file)
                        # The host's own reader only: `read` is a read, and a
                        # job on one of the user's machines (OCR of a scan)
                        # stays behind op='extract' and its write bits.
                        from server.routes.context_extract import HOST_TOOL as _HOST_TOOL
                        try:
                            _r = await _read_file(pool, eid, int(_cid0), tool=_HOST_TOOL)
                        except Exception as _e:  # noqa: BLE001 — said, never raised
                            _r = {"error": f"the host's reader failed ({type(_e).__name__})"}
                        if not (_r.get("ok") and _r.get("chunks")):
                            return {"status": "error", "result": (
                                f"{fname!r} ({mime}) could not be read: "
                                f"{_r.get('error') or _r.get('note') or 'no text in it'}")}
                        res = await _ctx.list_context_service(
                            pool, eid, status="active", fields="full",
                            from_file=fname or None, upload_batch=batch,
                            source="extracted", page=page, per_page=per_page,
                            order="asc")
                        items = res.get("items") or []
                        ordered = [it for _, it in sorted(enumerate(items), key=_chunk_key)]
                        extracted_note = (f"{fname} was just read by the host "
                                          f"({_r.get('reader') or _r.get('tool')}); "
                                          f"this is its text.")
                    else:
                        # No reader here. The error names a machine route
                        # ONLY when one exists for this type and one of the
                        # user's machines is online for it — it used to
                        # point at op='extract' for every type, which sent
                        # the host probing machines that could not help.
                        from server.routes.context_extract import (
                            no_reader_message as _no_reader)
                        return _refused(await _no_reader(
                            pool, eid, fname, mime, _cid0))

            content = "\n".join((it.get("content") or "") for it in ordered)
            pages = int(res.get("pages") or 1)
            out = {
                "file": fname or None,
                "upload_batch": batch or legacy_parent,
                "content": content,
                "chunks": len(ordered),
                "total_chunks": res.get("total"),
                "page": page,
                "pages": pages,
            }
            if pages > 1:
                out["note"] = (f"page {page} of {pages} — the document continues; "
                               f"request page {page + 1} for the next part.")
            if older_note:
                out["older_copies"] = older_note
            if batch_note:
                out["batch_note"] = batch_note
            if file_note:
                out["file_note"] = file_note
            if extracted_note:
                out["extracted"] = extracted_note
            return {"status": "ok", "result": out}

        return _refused(f"context_ingest: unknown op '{op}' (one of stage|bulk|search|promote|list|files|read)")
    except Exception as e:
        return _refused_if_caller(e, f"context_ingest failed: {getattr(e, 'detail', None) or e}")


async def _exec_context_backend(args: dict) -> dict:
    """Pick or show WHERE the host stores its context CONTENT bytes.

    ops:
      get  (default): show the current backend selection + a per-backend usage
                      rollup (total files + bytes per backend, from
                      context_backend_meta). No args.
      list (index)  : the HOST-LOCAL CONTEXT INDEX — one row per context file with
                      {file_path, backend, machine (server or bucket), object_key,
                      size_bytes, updated_at}. External (s3/bastion) files come from
                      context_backend_meta with their recorded location; pg-resident
                      files (entity_context) are UNION'd in as backend='pg',
                      machine='platform'. Optional prefix filter + limit.
      set           : select a backend. args: backend ('pg'|'s3'|'bastion').
                      's3' also needs bucket (+ optional prefix/region/endpoint_url/
                      cred_name; the S3 credential is sealed in the vault under
                      cred_name, default 'ctx:s3'). 'bastion' also needs server
                      (a host in the mesh; + optional root, default 'context/').

    The DEFAULT is 'pg' (the original entity_context store). Selecting 's3' meters
    storage + requests through the platform ledger; selecting 'bastion' keeps the
    bytes USER-OWNED on the home box and the host retrieves on demand over the mesh.
    Switching backends changes only where NEW writes land — existing files keep the
    backend they were written with (recorded per-file), so reads stay correct.
    """
    a = args or {}
    op = (a.get("op") or "get").strip().lower()
    try:
        from server import brain_service
        from brain.mastercode import context_backends
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "context_backend failed: brain not initialized"}
        eid = brain_service._entity_id

        if op == "get":
            cfg = await context_backends.get_backend_config(pool, eid)
            routes = await context_backends.get_routes(pool, eid)
            usage = []
            try:
                rows = await pool.fetch(
                    "SELECT backend, count(*) AS files, COALESCE(sum(size_bytes),0) AS bytes "
                    "FROM context_backend_meta WHERE entity_id = $1 GROUP BY backend",
                    eid)
                usage = [{"backend": r["backend"], "files": r["files"], "bytes": int(r["bytes"])}
                         for r in rows]
            except Exception:
                usage = []
            return {"status": "ok", "result": {
                "current": cfg,
                "routes": routes,
                "usage": usage,
                "available": list(context_backends.VALID_BACKENDS),
                "availability_options": list(context_backends.VALID_AVAILABILITY),
            }}

        if op in ("bastions", "targets"):
            # The choosable, REAL targets for a bastion backend / replica: the host's
            # ONLINE bastions that advertise the 'context-store' capability. hostname
            # is the value to pass as 'server' (run_mgmt_op addresses by hostname).
            choosable = await context_backends.list_context_store_bastions(pool, eid)
            return {"status": "ok", "result": {
                "bastions": choosable,
                "capability": context_backends.CONTEXT_STORE_CAPABILITY,
                "count": len(choosable),
                "note": ("pass a hostname from this list as 'server' when setting a "
                         "bastion backend; only online context-store bastions are listed"),
            }}

        if op == "cabinets":
            # The user's S3 filing cabinets — buckets the user KEEPS
            # files in, distinct from choosing s3 as a write backend. Cards carry
            # index coverage and the fixed cabinet tier (locations + previews).
            from brain.mastercode import dcn
            cabinets = await dcn.list_cabinet_stores(pool, eid)
            return {"status": "ok", "result": {
                "cabinets": cabinets,
                "count": len(cabinets),
                "note": ("a cabinet is a bucket the user keeps files in; an "
                         "'unindexed' cabinet becomes searchable once granted as a "
                         "DCN store and swept"),
            }}

        if op in ("list", "index"):
            # Host-local context index: per-file "what is where". External files
            # (s3/bastion) carry their recorded backend + machine (server|bucket);
            # pg-resident files are UNION'd in as backend='pg', machine='platform'.
            # NOTE: entity_context has no embedding column (content embeddings live
            # in entity_memory/user_context, not here), so 'embedded' is omitted —
            # there is no cheap join to stamp it for context files.
            prefix = (a.get("prefix") or a.get("path") or "").strip()
            try:
                limit = int(a.get("limit") or 500)
            except (TypeError, ValueError):
                limit = 500
            limit = max(1, min(limit, 2000))
            # Online status for bastion machines (offline surfacing): map hostname ->
            # online bool from list_bastions. A bastion file whose holder isn't in
            # the online set (or is offline) is flagged offline so the user sees it.
            bastion_online: dict[str, bool] = {}
            try:
                from server.network import topology
                for b in await topology.list_bastions(pool, eid):
                    if b.get("hostname"):
                        bastion_online[b["hostname"]] = bool(b.get("online"))
            except Exception:
                bastion_online = {}
            # Replica fan-out per file (from context_backend_locations): how many
            # physical copies the file has, so the list shows replicate coverage.
            replicas_by_file: dict[str, int] = {}
            try:
                rep_rows = await pool.fetch(
                    "SELECT file_path, count(*) AS n FROM context_backend_locations "
                    "WHERE entity_id = $1 GROUP BY file_path", eid)
                replicas_by_file = {r["file_path"]: int(r["n"]) for r in rep_rows}
            except Exception:
                replicas_by_file = {}
            files: dict[str, dict] = {}
            # 1) External files from the host-local index (authoritative for backend
            #    + physical location). server takes precedence as 'machine' for a
            #    bastion file; bucket for s3; pg shouldn't appear here but is mapped
            #    to 'platform' defensively.
            ext_rows = await pool.fetch(
                "SELECT file_path, backend, object_key, size_bytes, "
                "       server, bucket, endpoint, updated_at "
                "FROM context_backend_meta WHERE entity_id = $1 "
                "ORDER BY file_path", eid)
            for r in ext_rows:
                fp = r["file_path"]
                if prefix and not fp.startswith(prefix):
                    continue
                backend = r["backend"]
                machine = (r["server"] or r["bucket"]
                           or ("platform" if backend == "pg" else None))
                # Offline surfacing: a bastion file's holder may be offline. s3/pg
                # are treated as always-available (the platform / the bucket).
                if backend == "bastion" and r["server"]:
                    online = bastion_online.get(r["server"], False)
                else:
                    online = True
                files[fp] = {
                    "file_path": fp,
                    "backend": backend,
                    "machine": machine,
                    "online": online,
                    "replicas": replicas_by_file.get(fp, 0),
                    "object_key": r["object_key"],
                    "size_bytes": int(r["size_bytes"] or 0),
                    "endpoint": r["endpoint"],
                    "updated_at": r["updated_at"].isoformat() if r["updated_at"] else None,
                }
            # 2) pg-resident files from entity_context. Skip any file_path already
            #    covered by the index (an external file keeps a pg pointer row);
            #    the index row is authoritative for those.
            if prefix:
                pg_rows = await pool.fetch(
                    "SELECT file_path, length(content) AS size, updated_at "
                    "FROM entity_context WHERE entity_id = $1 AND file_path LIKE $2 "
                    "ORDER BY file_path", eid, prefix + "%")
            else:
                pg_rows = await pool.fetch(
                    "SELECT file_path, length(content) AS size, updated_at "
                    "FROM entity_context WHERE entity_id = $1 "
                    "ORDER BY file_path", eid)
            for r in pg_rows:
                fp = r["file_path"]
                if fp in files:
                    continue  # external file's pointer row — index row wins
                files[fp] = {
                    "file_path": fp,
                    "backend": "pg",
                    "machine": "platform",
                    "online": True,
                    "replicas": 0,
                    "object_key": fp,
                    "size_bytes": int(r["size"] or 0),
                    "endpoint": None,
                    "updated_at": r["updated_at"].isoformat() if r["updated_at"] else None,
                }
            rows = sorted(files.values(), key=lambda d: d["file_path"])[:limit]
            return {"status": "ok", "result": {"files": rows, "count": len(rows)}}

        if op == "set":
            backend = (a.get("backend") or "").strip().lower()
            if not backend:
                return _refused("context_backend set: 'backend' is required (pg|s3|bastion)")
            availability = (a.get("availability") or "").strip().lower()
            replicas = a.get("replicas") if isinstance(a.get("replicas"), list) else None
            # Validate a bastion target against the REAL choosable list (online +
            # context-store capability). Refuse a typed/dead hostname so the user
            # targets a live machine, not a string. (Both route + host-wide paths.)
            if backend == "bastion":
                server = (a.get("server") or "").strip()
                ok, reason = await context_backends.validate_bastion_target(pool, eid, server)
                if not ok:
                    return _refused(f"context_backend set: {reason}. Run op='bastions' to see "
                            f"online context-store targets.")
            # Validate explicit replica targets the same way (each must be live+capable).
            if replicas:
                bad = []
                for h in replicas:
                    rok, _ = await context_backends.validate_bastion_target(pool, eid, str(h).strip())
                    if not rok:
                        bad.append(str(h).strip())
                if bad:
                    return _refused(f"context_backend set: replica target(s) not online context-store "
                            f"bastions: {', '.join(bad)}. Run op='bastions' to see targets.")

            route_prefix = (a.get("route_prefix") or "").strip()
            # ── PER-PREFIX ROUTE: route_prefix present → add/replace a route, not the
            #    host-wide selection. Different context lives on different machines. ──
            if route_prefix:
                route = {"prefix": route_prefix, "backend": backend}
                if backend == "s3":
                    if a.get("bucket") is not None:
                        route["bucket"] = a.get("bucket")
                    # In a route, the s3 KEY prefix is 'prefix_key' (route_prefix is the
                    # context path prefix); fall back to 'prefix' for convenience.
                    keyp = a.get("prefix_key", a.get("prefix"))
                    if keyp is not None:
                        route["prefix_key"] = keyp
                    for k in ("region", "endpoint_url", "cred_name"):
                        if a.get(k) is not None:
                            route[k] = a.get(k)
                elif backend == "bastion":
                    for k in ("server", "root"):
                        if a.get(k) is not None:
                            route[k] = a.get(k)
                if availability:
                    route["availability"] = availability
                if replicas is not None:
                    route["replicas"] = replicas
                try:
                    stored = await context_backends.set_route(pool, eid, route)
                except ValueError as ve:
                    return _refused(f"context_backend set route: {ve}")
                return {"status": "ok", "result": {"route_set": stored}}

            # ── HOST-WIDE selection (default; 'prefix' stays the s3 KEY prefix here). ──
            cfg = {"backend": backend}
            if backend == "s3":
                cfg.update({k: a.get(k) for k in
                            ("bucket", "prefix", "region", "endpoint_url", "cred_name")
                            if a.get(k) is not None})
            elif backend == "bastion":
                cfg.update({k: a.get(k) for k in ("server", "root") if a.get(k) is not None})
            if availability:
                cfg["availability"] = availability
            if replicas is not None:
                cfg["replicas"] = replicas
            try:
                stored = await context_backends.set_backend_config(pool, eid, cfg)
            except ValueError as ve:
                return _refused(f"context_backend set: {ve}")
            return {"status": "ok", "result": {"set": stored}}

        if op in ("clear_route", "unset_route"):
            rp = (a.get("route_prefix") or a.get("prefix") or "").strip()
            if not rp:
                return _refused("context_backend clear_route: 'route_prefix' is required")
            removed = await context_backends.clear_route(pool, eid, rp)
            return {"status": "ok", "result": {"cleared": removed, "route_prefix": rp}}

        return _refused(f"context_backend: unknown op '{op}' "
                f"(one of get|list|set|bastions|clear_route)")
    except Exception as e:
        return _refused_if_caller(e, f"context_backend failed: {getattr(e, 'detail', None) or e}")


async def _exec_set_project_manifest(args: dict) -> dict:
    """Write + validate a project's app.yaml so the Workbench can ship it. Calls the projects
    set_project_manifest_service directly (no HTTP shim) — entity-scoped (a project you don't own is
    'not found') and the manifest is rolled back if it fails validation, so an invalid YAML is never
    persisted."""
    a = args or {}
    try:
        from server import brain_service
        from server.routes import projects
        pool = brain_service.get_pool()
        if pool is None:
            return {"status": "error", "result": "set_project_manifest failed: pool unavailable"}
        eid = brain_service._entity_id
        try:
            project_id = int(a.get("project_id"))
        except (TypeError, ValueError):
            return _refused("project_id (int) is required")
        res = await projects.set_project_manifest_service(pool, eid, project_id, a.get("yaml"))
        return {"status": "ok", "result": res}
    except Exception as e:
        return _refused_if_caller(e, f"set_project_manifest failed: {getattr(e, 'detail', None) or e}")


